**Logic**

The hard part is that any delimiter you pick might appear inside the data. Escaping works but is fiddly and slows decoding. Length-prefixing avoids the problem entirely: write each string's length, a marker, then the string itself.

Decoding reads digits up to the marker, takes exactly that many characters, and repeats. Because the length is known before the content is read, the content is never scanned for anything, so no character is special and no escaping is needed.

O(total length) in both directions.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Codec
{
    // length + '#' + content. No character inside the content is ever special.
    public string Encode(IList<string> strings)
    {
        var sb = new StringBuilder();

        foreach (string s in strings)
            sb.Append(s.Length).Append('#').Append(s);

        return sb.ToString();
    }

    public IList<string> Decode(string encoded)
    {
        var result = new List<string>();
        int i = 0;

        while (i < encoded.Length)
        {
            int marker = encoded.IndexOf('#', i);
            if (marker < 0) throw new FormatException("missing length marker");

            int length = int.Parse(encoded[i..marker]);
            int start = marker + 1;

            if (start + length > encoded.Length) throw new FormatException("truncated payload");

            result.Add(encoded.Substring(start, length));
            i = start + length;      // jump past the content, never scan it
        }

        return result;
    }
}

public class Solution
{
    private static string RoundTrip(params string[] input)
    {
        var codec = new Codec();
        var decoded = codec.Decode(codec.Encode(input));

        bool same = decoded.Count == input.Length;
        for (int i = 0; same && i < input.Length; i++) same = decoded[i] == input[i];

        return same ? "ok: " + codec.Encode(input) : "MISMATCH";
    }

    public static void Main()
    {
        Console.WriteLine(RoundTrip("hello", "world"));
        Console.WriteLine(RoundTrip("a#b", "c"));         // the delimiter inside the data
        Console.WriteLine(RoundTrip("", ""));            // empty strings survive
        Console.WriteLine(RoundTrip());                   // empty list
        Console.WriteLine(RoundTrip("12#34"));            // looks like a header
        Console.WriteLine(RoundTrip("line1\nline2"));     // newlines are not special
    }
}
```

