**Logic**

A one-line insight: `s2` is a rotation of `s1` exactly when `s2` is a substring of `s1 + s1`. Concatenating a string with itself contains every rotation of it as a contiguous block, so a single substring search answers the question.

The length check first is not optional: without it, a short string would be found inside the doubled longer one and wrongly reported as a rotation.

O(n) with a linear substring search such as KMP; .NET's `Contains` is typically vectorised and fast in practice.

**Program**

```csharp
using System;

public class Solution
{
    public static bool IsRotation(string s1, string s2)
    {
        if (s1 == null || s2 == null) return false;
        if (s1.Length != s2.Length) return false;      // essential, not an optimisation
        if (s1.Length == 0) return true;

        // s1 + s1 contains every rotation of s1 as a contiguous substring.
        return (s1 + s1).Contains(s2, StringComparison.Ordinal);
    }

    // Without the doubling trick: compare at every offset. O(n^2) but no allocation.
    public static bool IsRotationManual(string s1, string s2)
    {
        if (s1 == null || s2 == null || s1.Length != s2.Length) return false;
        if (s1.Length == 0) return true;

        int n = s1.Length;
        for (int offset = 0; offset < n; offset++)
        {
            bool match = true;
            for (int i = 0; i < n && match; i++)
                if (s1[(offset + i) % n] != s2[i]) match = false;

            if (match) return true;
        }
        return false;
    }

    public static void Main()
    {
        Console.WriteLine(IsRotation("waterbottle", "erbottlewat"));
        Console.WriteLine(IsRotation("abcde", "cdeab"));
        Console.WriteLine(IsRotation("abcde", "abced"));     // not a rotation
        Console.WriteLine(IsRotation("abc", "abc"));         // zero rotation
        Console.WriteLine(IsRotation("ab", "abab"));         // length differs
        Console.WriteLine(IsRotationManual("aa", "aa"));
    }
}
