```

The all-equal case gives zeros because the problem asks for a strictly *warmer* day, which the `<` comparison enforces.

**Logic**

Every maximal rectangle is limited by some bar's height, extending left and right until it meets a strictly shorter bar. So for each bar, find the nearest shorter bar on each side; the width between them times that height is the best rectangle capped by it.

A monotonic increasing stack finds both boundaries in one pass. When a bar shorter than the stack top arrives, the top is popped and resolved: the new bar is its right boundary and the element now beneath it is its left. Appending a sentinel height of zero flushes the stack at the end.

O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static long LargestRectangleArea(int[] heights)
    {
        if (heights == null || heights.Length == 0) return 0;

        var stack = new Stack<int>();    // indices, heights increasing
        long best = 0;

        // One extra step with a height of 0 flushes everything still on the stack.
        for (int i = 0; i <= heights.Length; i++)
        {
            int current = i == heights.Length ? 0 : heights[i];

            while (stack.Count > 0 && heights[stack.Peek()] >= current)
            {
                int height = heights[stack.Pop()];

                // Left boundary is whatever is now on top; if empty, the array start.
                int left = stack.Count == 0 ? -1 : stack.Peek();
                long width = i - left - 1;

                best = Math.Max(best, height * width);
            }

            stack.Push(i);
        }

        return best;
    }

    public static void Main()
    {
        Console.WriteLine(LargestRectangleArea(new[] { 2, 1, 5, 6, 2, 3 }));   // 5 and 6 -> 10
        Console.WriteLine(LargestRectangleArea(new[] { 2, 4 }));
        Console.WriteLine(LargestRectangleArea(new[] { 1, 1, 1, 1 }));         // flat
        Console.WriteLine(LargestRectangleArea(new[] { 5 }));
        Console.WriteLine(LargestRectangleArea(new[] { 1, 2, 3, 4, 5 }));      // increasing
        Console.WriteLine(LargestRectangleArea(new[] { 5, 4, 3, 2, 1 }));      // decreasing
    }
}
