```
True
True
True
False
1
True
2
3
False
```

**Approach**

Keep a fixed-size circular buffer and a running sum. Each arrival overwrites the oldest slot, adjusting the sum by the difference rather than recomputing it.

**Logic**

Recomputing the sum over the window on every call is O(k). Maintaining a running total makes each call O(1): add the entering value, subtract the leaving one. The circular buffer avoids shifting elements and allocates once.

The only subtlety is the warm-up period, where fewer than k values have arrived and the average must divide by the count so far rather than by k.

O(1) per call, O(k) space.

**Program**

```csharp
using System;

public class MovingAverage
{
    private readonly double[] _window;
    private double _sum;
    private int _index;
    private int _count;

    public MovingAverage(int size)
    {
        if (size <= 0) throw new ArgumentOutOfRangeException(nameof(size));
        _window = new double[size];
    }

    public double Next(int value)
    {
        // Subtract whatever occupied this slot before overwriting it.
        _sum -= _window[_index];
        _window[_index] = value;
        _sum += value;

        _index = (_index + 1) % _window.Length;
        if (_count < _window.Length) _count++;   // still warming up

        return _sum / _count;
    }
}

public class Solution
{
    public static void Main()
    {
        var m = new MovingAverage(3);

        Console.WriteLine(m.Next(1));      // 1 / 1
        Console.WriteLine(m.Next(10));     // 11 / 2
        Console.WriteLine(m.Next(3));      // 14 / 3
        Console.WriteLine(m.Next(5));      // window full: 1 drops out

        var single = new MovingAverage(1);
        Console.WriteLine(single.Next(4));
        Console.WriteLine(single.Next(9));
    }
}
