**Approach**

A stack, because a closing bracket must match the most recently opened one, which is last-in-first-out by definition.

**Logic**

Push every opening bracket. On a closing bracket, the stack must be non-empty and its top must be the matching opener, so pop and compare. At the end the stack must be empty, otherwise something was never closed.

Counting brackets instead of stacking them fails, because `([)]` has balanced counts but interleaved pairs. That case is the whole point of the question.

O(n) time, O(n) space in the worst case of all openers.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static bool IsValid(string s)
    {
        if (string.IsNullOrEmpty(s)) return true;

        var closers = new Dictionary<char, char> { [')'] = '(', [']'] = '[', ['}'] = '{' };
        var stack = new Stack<char>();

        foreach (char c in s)
        {
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(c);
            }
            else if (closers.TryGetValue(c, out char opener))
            {
                // A closer with nothing open, or the wrong thing open, is invalid.
                if (stack.Count == 0 || stack.Pop() != opener) return false;
            }
            // anything else is ordinary text and is ignored
        }

        return stack.Count == 0;
    }

    public static void Main()
    {
        Console.WriteLine(IsValid("()[]{}"));
        Console.WriteLine(IsValid("([{}])"));
        Console.WriteLine(IsValid("([)]"));      // balanced counts, wrong nesting
        Console.WriteLine(IsValid("("));
        Console.WriteLine(IsValid("]"));
        Console.WriteLine(IsValid("a(b)c[d]"));  // text is ignored
    }
}
```

**Output**

```
True
True
False
False
False
True
```

**Logic**

A stack of indices, seeded with -1 as a base marker. On an open bracket, push its index. On a close, pop: if the stack is then empty, this close is unmatched and its index becomes the new base; otherwise the current length is the distance from the current index back to the new stack top.

The sentinel is what makes the arithmetic uniform, so no special case is needed for a valid substring starting at index 0. O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int LongestValidParentheses(string s)
    {
        if (string.IsNullOrEmpty(s)) return 0;

        var stack = new Stack<int>();
        stack.Push(-1);              // base marker: the position before any match
        int best = 0;

        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '(')
            {
                stack.Push(i);
            }
            else
            {
                stack.Pop();

                if (stack.Count == 0)
                    stack.Push(i);    // unmatched close: it becomes the new base
                else
                    best = Math.Max(best, i - stack.Peek());
            }
        }

        return best;
    }

    public static void Main()
    {
        Console.WriteLine(LongestValidParentheses("(()"));
        Console.WriteLine(LongestValidParentheses(")()())"));
        Console.WriteLine(LongestValidParentheses(""));
        Console.WriteLine(LongestValidParentheses("()(()"));
        Console.WriteLine(LongestValidParentheses("()()"));      // adjacent groups join
        Console.WriteLine(LongestValidParentheses("(((("));
    }
}
```

**Output**

```
2
4
0
2
4
0
```

**Logic**

A stack of surviving asteroids. A collision is possible only when a right-moving asteroid is already on the stack and a left-moving one arrives, since that is the only configuration where their paths cross.

On such a meeting, compare sizes: the smaller is destroyed, and equal sizes destroy both. The incoming asteroid may survive several collisions in a row, so the comparison loops until it is destroyed or nothing on the stack opposes it.

Each asteroid is pushed and popped at most once, so O(n).

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int[] AsteroidCollision(int[] asteroids)
    {
        var stack = new Stack<int>();

        foreach (int incoming in asteroids)
        {
            int current = incoming;
            bool destroyed = false;

            // A collision needs a right-mover on the stack and a left-mover arriving.
            while (!destroyed && current < 0 && stack.Count > 0 && stack.Peek() > 0)
            {
                int top = stack.Peek();

                if (top < -current) stack.Pop();            // the one on the stack loses
                else if (top == -current) { stack.Pop(); destroyed = true; }   // both go
                else destroyed = true;                       // the incoming one loses
            }

            if (!destroyed) stack.Push(current);
        }

        return stack.Reverse().ToArray();   // stack pops newest-first
    }

    private static string Show(int[] a) => a.Length == 0 ? "(none)" : string.Join(",", a);

    public static void Main()
    {
        Console.WriteLine(Show(AsteroidCollision(new[] { 5, 10, -5 })));
        Console.WriteLine(Show(AsteroidCollision(new[] { 8, -8 })));        // equal: both die
        Console.WriteLine(Show(AsteroidCollision(new[] { 10, 2, -5 })));
        Console.WriteLine(Show(AsteroidCollision(new[] { -2, -1, 1, 2 })));  // never meet
        Console.WriteLine(Show(AsteroidCollision(new[] { 1, -2, -2, -2 })));
        Console.WriteLine(Show(AsteroidCollision(new[] { -5 })));
    }
}
```

**Output**

```
5,10
(none)
10
-2,-1,1,2
-2,-2,-2
-5
```

**Approach**

Depth-first. When a node has a child list, splice that whole list in between the node and its successor, then continue. A stack holds the deferred successors.

**Logic**

Walk the list. On reaching a node with a child, push its `next` onto a stack so it is not lost, wire the child in as the new `next`, fix the `prev` pointer, and clear the child pointer. When the walk reaches a null `next`, pop a deferred successor and continue from there.

The three pointers that must all be updated on a splice — `next`, `prev` and `child` — are where this goes wrong. Forgetting `child = null` leaves the flattened list still claiming to have levels.

O(n) time, O(depth) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Node
{
    public int Val;
    public Node Prev, Next, Child;
    public Node(int val) => Val = val;
}

public class Solution
{
    public static Node Flatten(Node head)
    {
        if (head == null) return null;

        var deferred = new Stack<Node>();
        var current = head;

        while (current != null)
        {
            if (current.Child != null)
            {
                if (current.Next != null) deferred.Push(current.Next);

                current.Next = current.Child;
                current.Child.Prev = current;
                current.Child = null;          // the level is gone once spliced
            }
            else if (current.Next == null && deferred.Count > 0)
            {
                var resume = deferred.Pop();
                current.Next = resume;
                resume.Prev = current;
            }

            current = current.Next;
        }

        return head;
    }

    private static string Render(Node head)
    {
        var parts = new List<string>();
        Node last = null;

        for (var n = head; n != null; n = n.Next)
        {
            if (n.Child != null) return "BROKEN: a child pointer survived";
            if (!ReferenceEquals(n.Prev, last)) return "BROKEN: prev pointer wrong";
            parts.Add(n.Val.ToString());
            last = n;
        }

        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    private static Node Chain(params int[] values)
    {
        Node head = null, tail = null;
        foreach (int v in values)
        {
            var node = new Node(v);
            if (head == null) head = tail = node;
            else { tail.Next = node; node.Prev = tail; tail = node; }
        }
        return head;
    }

    private static Node NodeAt(Node head, int index)
    {
        for (int i = 0; i < index; i++) head = head.Next;
        return head;
    }

    public static void Main()
    {
        // 1-2-3 with a child list 7-8 hanging off node 2, and 11 off node 8.
        var top = Chain(1, 2, 3);
        var mid = Chain(7, 8);
        var low = Chain(11, 12);

        NodeAt(top, 1).Child = mid;
        NodeAt(mid, 1).Child = low;

        Console.WriteLine(Render(Flatten(top)));

        Console.WriteLine(Render(Flatten(null)));
        Console.WriteLine(Render(Flatten(Chain(1))));

        // A child on the LAST node: nothing deferred.
        var tail = Chain(1, 2);
        NodeAt(tail, 1).Child = Chain(9);
        Console.WriteLine(Render(Flatten(tail)));

        // A child on the FIRST node.
        var first = Chain(1, 2);
        first.Child = Chain(5, 6);
        Console.WriteLine(Render(Flatten(first)));
    }
}
```

**Output**

```
1->2->7->8->11->12->3
(empty)
1
1->2->9
1->5->6->2
```

**Approach**

Build two separate lists — one for nodes strictly less than x, one for the rest — then join them. Two dummy heads make the appends unconditional.

**Logic**

A single pass appends each node to whichever list it belongs in, preserving the order of arrival within each. Joining the two at the end gives the answer.

The step that is easy to forget is terminating the second list. Its last node still points at whatever followed it in the original, so without setting it to null the result contains a cycle or trailing garbage.

This preserves relative order, which the stable version of the problem requires. A version that swaps values in place would be shorter and would not.

O(n) time, O(1) extra space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode Partition(ListNode head, int x)
    {
        var lessHead = new ListNode();
        var greaterHead = new ListNode();
        var less = lessHead;
        var greater = greaterHead;

        for (var node = head; node != null; node = node.Next)
        {
            if (node.Val < x) { less.Next = node; less = node; }
            else { greater.Next = node; greater = node; }
        }

        greater.Next = null;          // essential: cuts the tail loose
        less.Next = greaterHead.Next; // join the two lists

        return lessHead.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        int guard = 0;
        for (; n != null; n = n.Next)
        {
            if (++guard > 100) return "BROKEN: cycle detected";
            parts.Add(n.Val.ToString());
        }
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(Partition(Build(1, 4, 3, 2, 5, 2), 3)));
        Console.WriteLine(Render(Partition(Build(2, 1), 2)));
        Console.WriteLine(Render(Partition(Build(1, 2, 3), 0)));   // all go right
        Console.WriteLine(Render(Partition(Build(1, 2, 3), 9)));   // all go left
        Console.WriteLine(Render(Partition(null, 5)));
        Console.WriteLine(Render(Partition(Build(3, 3, 3), 3)));   // all equal
    }
}
```

**Output**

```
