1->2
1->2->3
1->2->3
(empty)
3->3->3
```

**Logic**

Merge sort is the right choice for a list. Quicksort needs random access for good pivot selection and its partitioning is awkward without indices, while merge sort only ever walks forward and splices, which is exactly what a list supports.

Split at the first middle so both halves are non-empty, sort each recursively, then merge. Splitting at the second middle would leave a two-node list producing an empty half and a two-node half, which recurses forever.

O(n log n) time. Space is O(log n) for the recursion; a bottom-up version reaches O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode SortList(ListNode head)
    {
        if (head?.Next == null) return head;     // 0 or 1 nodes: already sorted

        // Split at the FIRST middle, so neither half is empty.
        ListNode slow = head, fast = head.Next;
        while (fast?.Next != null) { slow = slow.Next; fast = fast.Next.Next; }

        ListNode second = slow.Next;
        slow.Next = null;                        // detach, or the recursion never ends

        return Merge(SortList(head), SortList(second));
    }

    private static ListNode Merge(ListNode a, ListNode b)
    {
        var dummy = new ListNode();
        var tail = dummy;

        while (a != null && b != null)
        {
            if (a.Val <= b.Val) { tail.Next = a; a = a.Next; }   // <= keeps it stable
            else                { tail.Next = b; b = b.Next; }
            tail = tail.Next;
        }

        tail.Next = a ?? b;
        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(SortList(Build(4, 2, 1, 3))));
        Console.WriteLine(Render(SortList(Build(-1, 5, 3, 4, 0))));
        Console.WriteLine(Render(SortList(Build(1, 2, 3))));      // already sorted
        Console.WriteLine(Render(SortList(Build(3, 2, 1))));      // reversed
        Console.WriteLine(Render(SortList(Build(2, 2, 1, 1))));   // duplicates
        Console.WriteLine(Render(SortList(null)));
    }
}
```

**Output**

```
1->2->3->4
-1->0->3->4->5
1->2->3
1->2->3
1->1->2->2
(empty)
```

**Approach**

A monotonic deque alongside the queue. The deque holds candidates for the maximum in decreasing order, so its front is always the current maximum.

**Logic**

On enqueue, pop from the back of the deque every value smaller than the incoming one: a smaller value that arrived earlier can never be the maximum again, because the new value outlives it and is larger. Then append.

On dequeue, if the departing value equals the deque's front, remove it too.

Each element is pushed and popped from the deque at most once, so the amortised cost per operation is O(1) even though a single enqueue can pop many entries.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class MaxQueue
{
    private readonly Queue<int> _items = new();
    private readonly LinkedList<int> _maxima = new();   // decreasing front to back

    public void Enqueue(int value)
    {
        _items.Enqueue(value);

        // A smaller earlier value can never be the max while this one is present.
        while (_maxima.Count > 0 && _maxima.Last.Value < value) _maxima.RemoveLast();

        _maxima.AddLast(value);
    }

    public int Dequeue()
    {
        if (_items.Count == 0) throw new InvalidOperationException("queue is empty");

        int value = _items.Dequeue();
        if (_maxima.Count > 0 && _maxima.First.Value == value) _maxima.RemoveFirst();

        return value;
    }

    public int Max => _maxima.Count > 0
        ? _maxima.First.Value
        : throw new InvalidOperationException("queue is empty");

    public int Count => _items.Count;
}

public class Solution
{
    public static void Main()
    {
        var q = new MaxQueue();

        q.Enqueue(1); q.Enqueue(3); q.Enqueue(2);
        Console.WriteLine(q.Max);          // 3

        Console.WriteLine(q.Dequeue());    // 1, max unchanged
        Console.WriteLine(q.Max);

        Console.WriteLine(q.Dequeue());    // 3 leaves, so the max drops
        Console.WriteLine(q.Max);

        // Duplicated maximum: both must be tracked.
        var d = new MaxQueue();
        d.Enqueue(5); d.Enqueue(5); d.Enqueue(1);
        Console.WriteLine(d.Max);
        d.Dequeue();
        Console.WriteLine(d.Max);          // still 5

        try { new MaxQueue().Max.ToString(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
```

**Output**

```
3
1
3
3
2
5
5
queue is empty
```

**Logic**

Split on slashes and process each component with a stack. A normal name is pushed; `..` pops one level, if there is one; `.` and empty components, which come from repeated or trailing slashes, are skipped. Joining the stack with slashes gives the canonical path.

The edge cases are what the question is really about: `..` at the root must be ignored rather than escaping above it, the result always begins with a slash, and it never ends with one except for the root itself.

O(n) time and space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static string SimplifyPath(string path)
    {
        if (string.IsNullOrEmpty(path)) return "/";

        var stack = new List<string>();   // a list so it can be joined in order

        foreach (string part in path.Split('/'))
        {
            if (part.Length == 0 || part == ".") continue;      // "//" and "/./"

            if (part == "..")
            {
                // Going up from the root stays at the root.
                if (stack.Count > 0) stack.RemoveAt(stack.Count - 1);
                continue;
            }

            stack.Add(part);
        }

        return "/" + string.Join("/", stack);
    }

    public static void Main()
    {
        Console.WriteLine(SimplifyPath("/home/"));
        Console.WriteLine(SimplifyPath("/../"));                  // cannot go above root
        Console.WriteLine(SimplifyPath("/home//foo/"));           // double slash
        Console.WriteLine(SimplifyPath("/a/./b/../../c/"));
        Console.WriteLine(SimplifyPath("/"));
        Console.WriteLine(SimplifyPath("/a/../../b/../c//.//"));
    }
}
```

**Output**

```
/home
/
/home/foo
/c
/
/c
```

**Logic**

The depth of a tree is one plus the deeper of its two subtrees, and an empty tree has depth 0. That recurrence is the whole solution: recurse both sides, take the larger, add one. Every node is visited once, so O(n) time. Space is O(h) for the call stack, which is O(log n) on a balanced tree but O(n) on a degenerate one.

The iterative alternative is a level-order traversal counting levels, which uses O(w) space for the widest level and avoids the stack-overflow risk entirely.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int MaxDepth(TreeNode root)
    {
        if (root == null) return 0;                    // base case: empty tree
        return 1 + Math.Max(MaxDepth(root.Left), MaxDepth(root.Right));
    }

    // Level-order version: no recursion, so no stack-overflow risk on deep trees.
    public static int MaxDepthIterative(TreeNode root)
    {
        if (root == null) return 0;
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        int depth = 0;

        while (queue.Count > 0)
        {
            int levelSize = queue.Count;               // snapshot: this level only
            for (int i = 0; i < levelSize; i++)
            {
                var node = queue.Dequeue();
                if (node.Left != null) queue.Enqueue(node.Left);
                if (node.Right != null) queue.Enqueue(node.Right);
            }
            depth++;
        }
        return depth;
    }

    public static void Main()
    {
        //     3
        //    / \
        //   9  20
        //     /  \
        //    15   7
        var root = new TreeNode(3,
            new TreeNode(9),
            new TreeNode(20, new TreeNode(15), new TreeNode(7)));

        Console.WriteLine(MaxDepth(root));
        Console.WriteLine(MaxDepthIterative(root));
        Console.WriteLine(MaxDepth(null));
        Console.WriteLine(MaxDepth(new TreeNode(1)));

        // Degenerate: a 1-2-3 right chain behaves like a linked list.
        var chain = new TreeNode(1, null, new TreeNode(2, null, new TreeNode(3)));
        Console.WriteLine(MaxDepth(chain));
    }
}
```

**Output**

```
3
3
0
1
3
```

**Logic**

Swap the left and right child of every node. Recursively: swap the current node's children, then invert each subtree. The order does not matter, since swapping references and recursing are independent. O(n) time, O(h) stack space.

This is famously the question that got the author of Homebrew rejected by Google. It is four lines, and what is really being tested is whether you mutate in place correctly rather than building a new tree by accident.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static TreeNode Invert(TreeNode root)
    {
        if (root == null) return null;

        (root.Left, root.Right) = (root.Right, root.Left);   // tuple swap, no temp
        Invert(root.Left);
        Invert(root.Right);

        return root;
    }

    // Iterative: any traversal works, since the swap is per node and order-free.
    public static TreeNode InvertIterative(TreeNode root)
    {
        if (root == null) return null;
        var stack = new Stack<TreeNode>();
        stack.Push(root);

        while (stack.Count > 0)
        {
            var node = stack.Pop();
            (node.Left, node.Right) = (node.Right, node.Left);
            if (node.Left != null) stack.Push(node.Left);
            if (node.Right != null) stack.Push(node.Right);
        }
        return root;
    }

    private static string LevelOrder(TreeNode root)
    {
        if (root == null) return "(empty)";
        var outp = new List<string>();
        var q = new Queue<TreeNode>();
        q.Enqueue(root);
        while (q.Count > 0)
        {
            var n = q.Dequeue();
            outp.Add(n.Val.ToString());
            if (n.Left != null) q.Enqueue(n.Left);
            if (n.Right != null) q.Enqueue(n.Right);
        }
        return string.Join(",", outp);
    }

    public static void Main()
    {
        //      4
        //    /   \
        //   2     7
        //  / \   / \
        // 1   3 6   9
        var root = new TreeNode(4,
            new TreeNode(2, new TreeNode(1), new TreeNode(3)),
            new TreeNode(7, new TreeNode(6), new TreeNode(9)));

        Console.WriteLine(LevelOrder(root));
        Console.WriteLine(LevelOrder(Invert(root)));
        Console.WriteLine(LevelOrder(InvertIterative(root)));   // back to the original
        Console.WriteLine(LevelOrder(Invert(null)));
    }
}
```

**Output**

```
4,2,7,1,3,6,9
4,7,2,9,6,3,1
4,2,7,1,3,6,9
(empty)
```

**Logic**

Compare structurally and by value at the same time. Two trees are identical when both are null, or both are non-null with equal values and identical left and right subtrees. The null handling comes first: both null is true, exactly one null is false.

O(n) time where n is the smaller tree, since a mismatch short-circuits. O(h) stack space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static bool IsSameTree(TreeNode p, TreeNode q)
    {
        if (p == null && q == null) return true;    // both absent: equal
        if (p == null || q == null) return false;   // exactly one absent: differ
        if (p.Val != q.Val) return false;

        return IsSameTree(p.Left, q.Left)
            && IsSameTree(p.Right, q.Right);
    }

    // Iterative: pairs on a stack, so no recursion depth limit.
    public static bool IsSameTreeIterative(TreeNode p, TreeNode q)
    {
        var stack = new Stack<(TreeNode a, TreeNode b)>();
        stack.Push((p, q));

        while (stack.Count > 0)
        {
            var (a, b) = stack.Pop();
            if (a == null && b == null) continue;
            if (a == null || b == null || a.Val != b.Val) return false;

            stack.Push((a.Left, b.Left));
            stack.Push((a.Right, b.Right));
        }
        return true;
    }

    public static void Main()
    {
        var a = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        var b = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        Console.WriteLine(IsSameTree(a, b));

        var c = new TreeNode(1, new TreeNode(2), null);
        var d = new TreeNode(1, null, new TreeNode(2));   // same values, different shape
        Console.WriteLine(IsSameTree(c, d));

        Console.WriteLine(IsSameTree(null, null));
        Console.WriteLine(IsSameTree(new TreeNode(1), null));
        Console.WriteLine(IsSameTree(new TreeNode(1), new TreeNode(2)));
        Console.WriteLine(IsSameTreeIterative(a, b));
    }
}
