```

**Approach**

A level-order traversal would work but costs O(w) space for the queue. In a *perfect* tree the already-established next pointers on one level provide a free linked list for traversing it, making O(1) space possible.

**Logic**

Walk the leftmost spine one level at a time. For each node on the current level, connect its left child to its right child, and connect its right child to the left child of the node's own next sibling. Then follow the next pointer to move along the level.

Because the tree is perfect, every node either has both children or none, so the two connection rules cover every case with no null checks beyond the loop conditions.

O(n) time, O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Node
{
    public int Val;
    public Node Left, Right, Next;
    public Node(int val) { Val = val; }
}

public class Solution
{
    public static Node Connect(Node root)
    {
        var leftmost = root;

        while (leftmost?.Left != null)          // stop once a level has no children
        {
            for (var node = leftmost; node != null; node = node.Next)
            {
                node.Left.Next = node.Right;                       // within one parent
                if (node.Next != null)
                    node.Right.Next = node.Next.Left;              // across parents
            }

            leftmost = leftmost.Left;           // descend using the spine
        }

        return root;
    }

    private static Node Build(int depth, ref int counter)
    {
        if (depth == 0) return null;
        var node = new Node(counter++);
        node.Left = Build(depth - 1, ref counter);
        node.Right = Build(depth - 1, ref counter);
        return node;
    }

    // Reads each level by following Next, which proves the wiring is right.
    private static string Levels(Node root)
    {
        var sb = new StringBuilder();
        for (var level = root; level != null; level = level.Left)
        {
            var parts = new List<string>();
            for (var n = level; n != null; n = n.Next) parts.Add(n.Val.ToString());
            sb.Append('[').Append(string.Join(",", parts)).Append(']');
        }
        return sb.Length == 0 ? "(empty)" : sb.ToString();
    }

    public static void Main()
    {
        int c = 1;
        var root = Build(3, ref c);      // a perfect tree of depth 3, values in preorder
        Connect(root);
        Console.WriteLine(Levels(root));

        int c2 = 1;
        var single = Build(1, ref c2);
        Connect(single);
        Console.WriteLine(Levels(single));

        Console.WriteLine(Levels(Connect(null)));

        int c3 = 1;
        var two = Build(2, ref c3);
        Connect(two);
        Console.WriteLine(Levels(two));
    }
}
```

**Output**

```
[1][2,5][3,4,6,7]
[1]
(empty)
[1][2,3]
```

**Logic**

Take the middle element as the root, then build the left subtree from the elements before it and the right subtree from those after. Because the array is sorted, the middle element is greater than everything on its left and less than everything on its right, which is exactly the BST property. Halving the range at every step keeps the two sides within one element of each other, so the result is height-balanced by construction.

O(n) time, since each element becomes exactly one node, and O(log n) stack space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0) { Val = val; }
}

public class Solution
{
    public static TreeNode SortedArrayToBst(int[] nums) =>
        nums == null ? null : Build(nums, 0, nums.Length - 1);

    private static TreeNode Build(int[] nums, int low, int high)
    {
        if (low > high) return null;

        int mid = low + (high - low) / 2;     // overflow-safe, and picks the left middle

        return new TreeNode(nums[mid])
        {
            Left = Build(nums, low, mid - 1),
            Right = Build(nums, mid + 1, high),
        };
    }

    private static string LevelOrder(TreeNode root)
    {
        if (root == null) return "(empty)";
        var outp = new List<string>();
        var q = new Queue<TreeNode>();
        q.Enqueue(root);
        while (q.Count > 0)
        {
            var n = q.Dequeue();
            outp.Add(n.Val.ToString());
            if (n.Left != null) q.Enqueue(n.Left);
            if (n.Right != null) q.Enqueue(n.Right);
        }
        return string.Join(",", outp);
    }

    private static int Height(TreeNode n) =>
        n == null ? 0 : 1 + Math.Max(Height(n.Left), Height(n.Right));

    public static void Main()
    {
        var t = SortedArrayToBst(new[] { -10, -3, 0, 5, 9 });
        Console.WriteLine(LevelOrder(t));
        Console.WriteLine(Height(t));

        Console.WriteLine(LevelOrder(SortedArrayToBst(new[] { 1, 3 })));
        Console.WriteLine(LevelOrder(SortedArrayToBst(new[] { 7 })));
        Console.WriteLine(LevelOrder(SortedArrayToBst(new int[0])));

        // 15 elements: a perfectly balanced tree is height 4.
        var big = new int[15];
        for (int i = 0; i < 15; i++) big[i] = i;
        Console.WriteLine(Height(SortedArrayToBst(big)));
    }
}
```

