**Approach**

Kruskal's: sort every edge by weight and add each one whose endpoints are not already connected, using union-find to test connectivity. The greedy is provably optimal by the cut property.

**Logic**

Sorting puts the cheapest edges first. An edge whose endpoints already share a component would create a cycle, so it is skipped. After V-1 accepted edges the tree is complete; if the edges run out first, the graph was disconnected and no spanning tree exists.

O(E log E) for the sort, then effectively linear for the union-find operations with path compression and union by rank.

Prim's is the alternative: grow one tree from a starting vertex, always taking the cheapest edge leaving it, at O(E log V) with a heap. Kruskal's suits sparse graphs, Prim's suits dense ones.

**Program**

```csharp
using System;
using System.Linq;

public class Solution
{
    // edges[i] = [u, v, weight]; returns total weight, or -1 if disconnected.
    public static int MinimumSpanningTree(int n, int[][] edges)
    {
        var parent = new int[n];
        var rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int Find(int x)
        {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;
        }

        bool Union(int a, int b)
        {
            int ra = Find(a), rb = Find(b);
            if (ra == rb) return false;                 // already connected: a cycle

            if (rank[ra] < rank[rb]) (ra, rb) = (rb, ra);
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) rank[ra]++;
            return true;
        }

        int total = 0, accepted = 0;

        foreach (var e in edges.OrderBy(e => e[2]))     // cheapest first
        {
            if (!Union(e[0], e[1])) continue;

            total += e[2];
            if (++accepted == n - 1) break;             // a tree on n nodes has n-1 edges
        }

        return accepted == n - 1 ? total : -1;
    }

    public static void Main()
    {
        Console.WriteLine(MinimumSpanningTree(4, new[] {
            new[] { 0, 1, 10 }, new[] { 0, 2, 6 }, new[] { 0, 3, 5 },
            new[] { 1, 3, 15 }, new[] { 2, 3, 4 } }));

        Console.WriteLine(MinimumSpanningTree(2, new[] { new[] { 0, 1, 7 } }));
        Console.WriteLine(MinimumSpanningTree(1, Array.Empty<int[]>()));   // single node
        Console.WriteLine(MinimumSpanningTree(3, new[] { new[] { 0, 1, 1 } }));  // disconnected
        Console.WriteLine(MinimumSpanningTree(3, new[] {
            new[] { 0, 1, 1 }, new[] { 1, 2, 2 }, new[] { 0, 2, 5 } }));
    }
}
