**Approach**

Running the single-word search once per word is O(words × cells × 4^L). Instead build a trie of all the words and do one DFS from each cell, walking the trie in lockstep with the grid.

**Logic**

At each step the path must correspond to a trie node; the moment no child matches the current letter, the branch is dead and is abandoned immediately. That prunes far harder than checking a single word, because one traversal tests every word at once.

Two refinements matter. Store the word on its terminal node so a match needs no reconstruction. And clear that word once found, so the same word is never reported twice from different starting cells.

O(cells × 4^L) for the whole dictionary rather than per word.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    private sealed class TrieNode
    {
        public readonly Dictionary<char, TrieNode> Children = new();
        public string Word;            // non-null only on a terminal node
    }

    public static IList<string> FindWords(char[][] board, string[] words)
    {
        var root = new TrieNode();

        foreach (string word in words)
        {
            var node = root;
            foreach (char c in word)
            {
                if (!node.Children.TryGetValue(c, out var next))
                    node.Children[c] = next = new TrieNode();
                node = next;
            }
            node.Word = word;
        }

        var found = new List<string>();
        if (board == null || board.Length == 0) return found;

        for (int r = 0; r < board.Length; r++)
            for (int c = 0; c < board[0].Length; c++)
                Search(board, r, c, root, found);

        return found;
    }

    private static void Search(char[][] board, int r, int c, TrieNode node, IList<string> found)
    {
        if (r < 0 || r >= board.Length || c < 0 || c >= board[0].Length) return;

        char letter = board[r][c];
        if (letter == '#' || !node.Children.TryGetValue(letter, out var next)) return;

        if (next.Word != null)
        {
            found.Add(next.Word);
            next.Word = null;          // report each word once
        }

        board[r][c] = '#';             // in use on this path only

        Search(board, r - 1, c, next, found);
        Search(board, r + 1, c, next, found);
        Search(board, r, c - 1, next, found);
        Search(board, r, c + 1, next, found);

        board[r][c] = letter;          // restore for other paths
    }

    private static char[][] Parse(params string[] rows)
    {
        var g = new char[rows.Length][];
        for (int i = 0; i < rows.Length; i++) g[i] = rows[i].ToCharArray();
        return g;
    }

    private static string Show(IList<string> r)
    {
        if (r.Count == 0) return "(none)";
        var copy = new List<string>(r);
        copy.Sort(StringComparer.Ordinal);
        return string.Join(",", copy);
    }

    public static void Main()
    {
        var board = Parse("oaan", "etae", "ihkr", "iflv");
        Console.WriteLine(Show(FindWords(board, new[] { "oath", "pea", "eat", "rain" })));

        Console.WriteLine(Show(FindWords(Parse("ab", "cd"), new[] { "abcb" })));   // needs reuse
        Console.WriteLine(Show(FindWords(Parse("a"), new[] { "a" })));
        Console.WriteLine(Show(FindWords(Parse("ab"), new[] { "ba" })));

        // The same word reachable from two starts is reported once.
        Console.WriteLine(Show(FindWords(Parse("aa", "aa"), new[] { "aa" })));
    }
}
```

