**Approach**

The sorted word list encodes pairwise ordering constraints between characters. Extract those constraints into a directed graph and topologically sort it.

**Logic**

Comparing two adjacent words, the first position where they differ tells you that the character in the earlier word precedes the character in the later one. That is one edge. Everything after the first difference tells you nothing.

Two failure cases must be detected. A cycle means the constraints contradict each other, so no ordering exists. And a word followed by a strict prefix of itself, such as `abc` then `ab`, is invalid input because a prefix must sort first.

O(total characters) to build the graph, then O(V + E) for the sort.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    public static string AlienOrder(string[] words)
    {
        var dependents = new Dictionary<char, List<char>>();
        var indegree = new Dictionary<char, int>();

        // Every character that appears must end up in the answer.
        foreach (string w in words)
            foreach (char c in w)
            {
                dependents.TryAdd(c, new List<char>());
                indegree.TryAdd(c, 0);
            }

        for (int i = 0; i + 1 < words.Length; i++)
        {
            string a = words[i], b = words[i + 1];

            // "abc" before "ab" is impossible in any ordering.
            if (a.Length > b.Length && a.StartsWith(b, StringComparison.Ordinal))
                return "";

            int limit = Math.Min(a.Length, b.Length);
            for (int k = 0; k < limit; k++)
            {
                if (a[k] == b[k]) continue;

                dependents[a[k]].Add(b[k]);   // a[k] comes before b[k]
                indegree[b[k]]++;
                break;                         // only the FIRST difference informs us
            }
        }

        var ready = new Queue<char>();
        foreach (var (c, degree) in indegree)
            if (degree == 0) ready.Enqueue(c);

        var order = new StringBuilder();

        while (ready.Count > 0)
        {
            char c = ready.Dequeue();
            order.Append(c);

            foreach (char next in dependents[c])
                if (--indegree[next] == 0) ready.Enqueue(next);
        }

        // Short result means a cycle blocked the rest.
        return order.Length == indegree.Count ? order.ToString() : "";
    }

    private static string Show(string s) => s.Length == 0 ? "(invalid)" : s;

    public static void Main()
    {
        Console.WriteLine(Show(AlienOrder(new[] { "wrt", "wrf", "er", "ett", "rftt" })));
        Console.WriteLine(Show(AlienOrder(new[] { "z", "x" })));
        Console.WriteLine(Show(AlienOrder(new[] { "z", "x", "z" })));      // cycle
        Console.WriteLine(Show(AlienOrder(new[] { "abc", "ab" })));        // invalid prefix
        Console.WriteLine(Show(AlienOrder(new[] { "ab", "abc" })));        // valid prefix
        Console.WriteLine(Show(AlienOrder(new[] { "a" })));
    }
}
