**Logic**

A three-state machine per day: holding a share, just sold today and therefore in cooldown, or free to act. Transitions are the whole solution.

Holding is either continuing to hold or buying from the free state. Sold is holding plus today's price. Free is the better of staying free or yesterday's sold state, which is what enforces the one-day cooldown: a buy can only draw from `free`, and `free` only receives `sold` after a day's delay.

O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int MaxProfitWithCooldown(int[] prices)
    {
        if (prices == null || prices.Length < 2) return 0;

        int holding = -prices[0];   // owns a share
        int sold = 0;               // sold today: cannot buy tomorrow
        int free = 0;               // idle and free to buy

        for (int i = 1; i < prices.Length; i++)
        {
            int prevHolding = holding, prevSold = sold, prevFree = free;

            holding = Math.Max(prevHolding, prevFree - prices[i]);  // buy only from free
            sold = prevHolding + prices[i];                          // sell today
            free = Math.Max(prevFree, prevSold);                     // cooldown expires here
        }

        return Math.Max(sold, free);   // never finish holding
    }

    public static void Main()
    {
        Console.WriteLine(MaxProfitWithCooldown(new[] { 1, 2, 3, 0, 2 }));
        Console.WriteLine(MaxProfitWithCooldown(new[] { 1 }));
        Console.WriteLine(MaxProfitWithCooldown(new[] { 1, 2 }));
        Console.WriteLine(MaxProfitWithCooldown(new[] { 2, 1 }));
        Console.WriteLine(MaxProfitWithCooldown(new[] { 1, 4, 2, 7 }));
        Console.WriteLine(MaxProfitWithCooldown(new[] { 6, 1, 3, 2, 4, 7 }));
    }
}
```

