0
1
0
6
6
```

**Approach**

Backtracking with memoisation. The number of valid sentences can be exponential, so no polynomial algorithm exists for producing all of them, but memoising by suffix avoids recomputing shared work.

**Logic**

For each starting position, try every prefix that is a dictionary word, recurse on the remainder, and prepend the prefix to each sentence the remainder produces. Cache the list of sentences per starting index, since the same suffix is reached along many different paths.

The critical practical step is a feasibility check first: run the boolean word-break DP, which is polynomial, and return immediately if no segmentation exists. Without it, an input like a long run of `a` with a dictionary lacking the needed word explores exponentially before concluding nothing works.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<string> WordBreak(string s, IList<string> wordDict)
    {
        var words = new HashSet<string>(wordDict);

        // Polynomial feasibility check first: refuse hopeless input cheaply.
        if (!CanBreak(s, words)) return new List<string>();

        return Solve(s, 0, words, new Dictionary<int, IList<string>>());
    }

    private static bool CanBreak(string s, HashSet<string> words)
    {
        var reachable = new bool[s.Length + 1];
        reachable[0] = true;

        for (int i = 1; i <= s.Length; i++)
            for (int j = 0; j < i && !reachable[i]; j++)
                if (reachable[j] && words.Contains(s[j..i])) reachable[i] = true;

        return reachable[s.Length];
    }

    private static IList<string> Solve(string s, int start, HashSet<string> words,
                                       Dictionary<int, IList<string>> memo)
    {
        if (memo.TryGetValue(start, out var cached)) return cached;

        var result = new List<string>();

        if (start == s.Length) { result.Add(""); return memo[start] = result; }

        for (int end = start + 1; end <= s.Length; end++)
        {
            string prefix = s[start..end];
            if (!words.Contains(prefix)) continue;

            foreach (string rest in Solve(s, end, words, memo))
                result.Add(rest.Length == 0 ? prefix : prefix + " " + rest);
        }

        return memo[start] = result;
    }

    private static string Show(IList<string> r)
    {
        if (r.Count == 0) return "(none)";
        var copy = new List<string>(r);
        copy.Sort(StringComparer.Ordinal);
        return string.Join(" | ", copy);
    }

    public static void Main()
    {
        Console.WriteLine(Show(WordBreak("catsanddog",
            new List<string> { "cat", "cats", "and", "sand", "dog" })));

        Console.WriteLine(Show(WordBreak("pineapplepenapple",
            new List<string> { "apple", "pen", "applepen", "pine", "pineapple" })));

        Console.WriteLine(Show(WordBreak("catsandog",
            new List<string> { "cats", "dog", "sand", "and", "cat" })));

        Console.WriteLine(Show(WordBreak("aaa", new List<string> { "a", "aa" })));
    }
}
```

