**Approach**

The O(n²) LIS dynamic programme, extended to carry a count alongside each length.

**Logic**

For each index keep two values: the length of the longest increasing subsequence ending there, and how many such subsequences exist.

Scanning earlier indices with a smaller value, if extending gives a strictly longer subsequence than previously recorded, the length improves and the count is *replaced* by that predecessor's count. If it ties the best length found so far, the counts *accumulate*, because both routes are equally long.

That replace-versus-accumulate distinction is the entire difficulty. Getting it backwards produces counts that look plausible and are wrong.

O(n²) time, O(n) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int FindNumberOfLis(int[] nums)
    {
        if (nums == null || nums.Length == 0) return 0;

        int n = nums.Length;
        var length = new int[n];   // longest subsequence ending at i
        var count = new int[n];    // how many of that length

        for (int i = 0; i < n; i++) { length[i] = 1; count[i] = 1; }

        int longest = 1;

        for (int i = 1; i < n; i++)
        {
            for (int j = 0; j < i; j++)
            {
                if (nums[j] >= nums[i]) continue;

                if (length[j] + 1 > length[i])
                {
                    length[i] = length[j] + 1;
                    count[i] = count[j];        // strictly better: REPLACE
                }
                else if (length[j] + 1 == length[i])
                {
                    count[i] += count[j];       // equally good: ACCUMULATE
                }
            }

            longest = Math.Max(longest, length[i]);
        }

        int total = 0;
        for (int i = 0; i < n; i++) if (length[i] == longest) total += count[i];

        return total;
    }

    public static void Main()
    {
        Console.WriteLine(FindNumberOfLis(new[] { 1, 3, 5, 4, 7 }));   // two of length 4
        Console.WriteLine(FindNumberOfLis(new[] { 2, 2, 2, 2, 2 }));   // five of length 1
        Console.WriteLine(FindNumberOfLis(new[] { 1, 2, 3 }));
        Console.WriteLine(FindNumberOfLis(new[] { 3, 2, 1 }));
        Console.WriteLine(FindNumberOfLis(new[] { 5 }));
        Console.WriteLine(FindNumberOfLis(new[] { 1, 3, 2, 4 }));
    }
}
```

