**Approach**

Backtracking with constraint tracking. Try each digit in the first empty cell, recurse, and undo on failure. The difference between a solution that finishes instantly and one that takes minutes is how cheaply legality is checked.

**Logic**

Keep three bitmask arrays — one per row, column and 3×3 box — so validity is a single bitwise test rather than a scan of 27 cells. The box index is `(row / 3) * 3 + col / 3`.

On placing a digit, set the bit in all three masks; on backtracking, clear it. The incremental maintenance is what makes the search fast.

Worst case is exponential, but real puzzles are solved in milliseconds because the constraints prune almost everything.

**Program**

```csharp
using System;

public class Solution
{
    public static bool Solve(char[][] board)
    {
        var rows = new int[9];
        var cols = new int[9];
        var boxes = new int[9];

        // Seed the masks from the given digits.
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++)
            {
                if (board[r][c] == '.') continue;

                int bit = 1 << (board[r][c] - '1');
                int box = (r / 3) * 3 + c / 3;

                // The givens themselves must be legal. Without this check a board
                // with two 5s in one row looks fine and the search never terminates.
                if ((rows[r] & bit) != 0 || (cols[c] & bit) != 0 || (boxes[box] & bit) != 0)
                    return false;

                rows[r] |= bit;
                cols[c] |= bit;
                boxes[box] |= bit;
            }

        return Fill(board, 0, rows, cols, boxes);
    }

    private static bool Fill(char[][] board, int position, int[] rows, int[] cols, int[] boxes)
    {
        if (position == 81) return true;               // every cell filled

        int r = position / 9, c = position % 9;
        if (board[r][c] != '.') return Fill(board, position + 1, rows, cols, boxes);

        int box = (r / 3) * 3 + c / 3;

        for (char digit = '1'; digit <= '9'; digit++)
        {
            int bit = 1 << (digit - '1');

            // One test against three masks: no scanning.
            if ((rows[r] & bit) != 0 || (cols[c] & bit) != 0 || (boxes[box] & bit) != 0) continue;

            board[r][c] = digit;
            rows[r] |= bit; cols[c] |= bit; boxes[box] |= bit;

            if (Fill(board, position + 1, rows, cols, boxes)) return true;

            board[r][c] = '.';                          // undo
            rows[r] &= ~bit; cols[c] &= ~bit; boxes[box] &= ~bit;
        }

        return false;
    }

    private static char[][] Parse(params string[] rows)
    {
        var b = new char[9][];
        for (int i = 0; i < 9; i++) b[i] = rows[i].ToCharArray();
        return b;
    }

    private static bool IsValidSolution(char[][] b)
    {
        for (int i = 0; i < 9; i++)
        {
            int row = 0, col = 0, box = 0;
            for (int j = 0; j < 9; j++)
            {
                row |= 1 << (b[i][j] - '1');
                col |= 1 << (b[j][i] - '1');
                int br = (i / 3) * 3 + j / 3, bc = (i % 3) * 3 + j % 3;
                box |= 1 << (b[br][bc] - '1');
            }
            if (row != 0x1FF || col != 0x1FF || box != 0x1FF) return false;
        }
        return true;
    }

    public static void Main()
    {
        var puzzle = Parse(
            "53..7....", "6..195...", ".98....6.",
            "8...6...3", "4..8.3..1", "7...2...6",
            ".6....28.", "...419..5", "....8..79");

        Console.WriteLine(Solve(puzzle));
        Console.WriteLine(IsValidSolution(puzzle));
        Console.WriteLine(new string(puzzle[0]));
        Console.WriteLine(new string(puzzle[8]));

        // Contradictory givens: two 5s in the first row. Detected before searching.
        var broken = Parse(
            "55.......", ".........", ".........",
            ".........", ".........", ".........",
            ".........", ".........", ".........");
        Console.WriteLine(Solve(broken));
    }
}
