True
False
True
```

`ABCB` is the case that matters: the letters are all present, but reaching the final B would mean visiting the same cell twice.

**Approach**

Backtracking over cut positions, with a precomputed palindrome table so the test inside the recursion is a lookup rather than a scan.

**Logic**

From the current index, try every prefix; when it is a palindrome, take it as one part and recurse on the remainder. Reaching the end means the accumulated parts form a complete partition.

The palindrome table is built with an interval DP: a range is a palindrome when its ends match and the interior is one, which requires the inner range to be computed first, so the start index iterates downward.

The output can be exponential, so no polynomial bound exists; the precomputation removes an O(n) factor from every node of the tree.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static IList<IList<string>> Partition(string s)
    {
        var result = new List<IList<string>>();
        if (string.IsNullOrEmpty(s)) return result;

        int n = s.Length;
        var isPalindrome = new bool[n, n];

        // Downward, so the shorter inner range is already computed.
        for (int start = n - 1; start >= 0; start--)
            for (int end = start; end < n; end++)
                isPalindrome[start, end] = s[start] == s[end]
                    && (end - start < 2 || isPalindrome[start + 1, end - 1]);

        Backtrack(s, 0, isPalindrome, new List<string>(), result);
        return result;
    }

    private static void Backtrack(string s, int start, bool[,] isPalindrome,
                                  List<string> current, IList<IList<string>> result)
    {
        if (start == s.Length) { result.Add(new List<string>(current)); return; }

        for (int end = start; end < s.Length; end++)
        {
            if (!isPalindrome[start, end]) continue;   // O(1) lookup

            current.Add(s[start..(end + 1)]);
            Backtrack(s, end + 1, isPalindrome, current, result);
            current.RemoveAt(current.Count - 1);
        }
    }

    private static string Render(IList<IList<string>> r) =>
        r.Count == 0 ? "(none)" : string.Join(" ", r.Select(p => "[" + string.Join(",", p) + "]"));

    public static void Main()
    {
        Console.WriteLine(Render(Partition("aab")));
        Console.WriteLine(Render(Partition("a")));
        Console.WriteLine(Render(Partition("ab")));
        Console.WriteLine(Render(Partition("aaa")));
        Console.WriteLine(Partition("aaaaa").Count);   // 2^(n-1) for all-equal input
        Console.WriteLine(Render(Partition("")));
    }
}
```

