**Approach**

Backtracking over three cut positions, with the validity rules pruning aggressively.

**Logic**

An IPv4 address has exactly four segments, each 1 to 3 digits, each between 0 and 255, and none with a leading zero unless the segment is exactly "0".

The leading-zero rule is the one people miss: "01" is invalid even though it parses to 1. Without it, "0000" produces several spurious answers.

Length pruning helps: with `parts` segments already placed and `remaining` digits left, the remainder must fit in the remaining segments, so anything outside 1 to 3 digits per segment can be rejected immediately.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<string> RestoreIpAddresses(string s)
    {
        var result = new List<string>();
        if (s == null || s.Length < 4 || s.Length > 12) return result;   // impossible lengths

        Backtrack(s, 0, new List<string>(), result);
        return result;
    }

    private static void Backtrack(string s, int start, List<string> parts, IList<string> result)
    {
        if (parts.Count == 4)
        {
            if (start == s.Length) result.Add(string.Join(".", parts));
            return;
        }

        for (int length = 1; length <= 3 && start + length <= s.Length; length++)
        {
            string segment = s.Substring(start, length);

            if (!IsValidSegment(segment)) continue;

            // Prune: the rest must fit in the remaining segments.
            int remainingSegments = 3 - parts.Count;
            int remainingDigits = s.Length - start - length;
            if (remainingDigits > remainingSegments * 3) continue;
            if (remainingDigits < remainingSegments) continue;

            parts.Add(segment);
            Backtrack(s, start + length, parts, result);
            parts.RemoveAt(parts.Count - 1);
        }
    }

    private static bool IsValidSegment(string segment)
    {
        // "01" is invalid even though it parses to 1.
        if (segment.Length > 1 && segment[0] == '0') return false;
        return int.Parse(segment) <= 255;
    }

    private static string Show(IList<string> r)
    {
        if (r.Count == 0) return "(none)";
        var copy = new List<string>(r);
        copy.Sort(StringComparer.Ordinal);
        return string.Join(" ", copy);
    }

    public static void Main()
    {
        Console.WriteLine(Show(RestoreIpAddresses("25525511135")));
        Console.WriteLine(Show(RestoreIpAddresses("0000")));       // only one valid form
        Console.WriteLine(Show(RestoreIpAddresses("101023")));
        Console.WriteLine(Show(RestoreIpAddresses("1111")));
        Console.WriteLine(Show(RestoreIpAddresses("1")));          // too short
        Console.WriteLine(Show(RestoreIpAddresses("1111111111111")));  // too long
    }
}
```

