**Logic**

Split the array in half, sort each half recursively, then merge the two sorted halves by repeatedly taking the smaller front element. Always O(n log n), regardless of the input, because the split is always even.

It needs O(n) auxiliary space for the merge, which is its main cost against quicksort. In exchange it is stable, provided the merge takes from the left half when the two fronts are equal, and its predictable access pattern makes it the basis of external sorting for data larger than memory.

**Program**

```csharp
using System;

public class Solution
{
    public static void MergeSort(int[] nums)
    {
        if (nums == null || nums.Length < 2) return;

        // One scratch buffer reused throughout, rather than allocating per merge.
        var buffer = new int[nums.Length];
        Sort(nums, buffer, 0, nums.Length - 1);
    }

    private static void Sort(int[] nums, int[] buffer, int low, int high)
    {
        if (low >= high) return;

        int mid = low + (high - low) / 2;
        Sort(nums, buffer, low, mid);
        Sort(nums, buffer, mid + 1, high);

        // Already in order: skip the merge entirely. Makes sorted input O(n).
        if (nums[mid] <= nums[mid + 1]) return;

        Merge(nums, buffer, low, mid, high);
    }

    private static void Merge(int[] nums, int[] buffer, int low, int mid, int high)
    {
        Array.Copy(nums, low, buffer, low, high - low + 1);

        int i = low, j = mid + 1;

        for (int k = low; k <= high; k++)
        {
            if (i > mid) nums[k] = buffer[j++];
            else if (j > high) nums[k] = buffer[i++];
            else if (buffer[j] < buffer[i]) nums[k] = buffer[j++];
            else nums[k] = buffer[i++];    // <= takes from the LEFT: this is stability
        }
    }

    private static string Sorted(int[] a)
    {
        var copy = (int[])a.Clone();
        MergeSort(copy);
        return string.Join(",", copy);
    }

    public static void Main()
    {
        Console.WriteLine(Sorted(new[] { 5, 2, 9, 1, 5, 6 }));
        Console.WriteLine(Sorted(new[] { 1, 2, 3, 4, 5 }));
        Console.WriteLine(Sorted(new[] { 5, 4, 3, 2, 1 }));
        Console.WriteLine(Sorted(new[] { 2, 2, 1, 1 }));
        Console.WriteLine(Sorted(new[] { 42 }));
        Console.WriteLine(Sorted(new int[0]));
    }
}
```

