**Logic**

An elastic window with a count per character. Expand right; while the number of distinct characters exceeds k, shrink from the left, decrementing counts and removing entries that reach zero. Track the widest window seen.

Removing the entry when its count hits zero is essential: leaving a zero-count key in the dictionary makes `Count` overstate the distinct total and the window shrinks further than it should.

O(n) time, O(k) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int LongestSubstringKDistinct(string s, int k)
    {
        if (string.IsNullOrEmpty(s) || k <= 0) return 0;

        var counts = new Dictionary<char, int>();
        int left = 0, best = 0;

        for (int right = 0; right < s.Length; right++)
        {
            char entering = s[right];
            counts[entering] = counts.TryGetValue(entering, out int c) ? c + 1 : 1;

            while (counts.Count > k)
            {
                char leaving = s[left++];

                // Remove at zero, or Count keeps counting characters no longer present.
                if (--counts[leaving] == 0) counts.Remove(leaving);
            }

            best = Math.Max(best, right - left + 1);
        }

        return best;
    }

    public static void Main()
    {
        Console.WriteLine(LongestSubstringKDistinct("eceba", 2));    // "ece"
        Console.WriteLine(LongestSubstringKDistinct("aa", 1));
        Console.WriteLine(LongestSubstringKDistinct("abcdef", 3));
        Console.WriteLine(LongestSubstringKDistinct("a", 0));        // k of zero
        Console.WriteLine(LongestSubstringKDistinct("aabbcc", 10));  // k exceeds distinct
        Console.WriteLine(LongestSubstringKDistinct("", 2));
    }
}
```

