1
0
32
3
3
```

**Logic**

XOR everything together. Because `a ^ a == 0` and `a ^ 0 == a`, every paired value cancels itself and only the unpaired one survives. XOR is commutative and associative, so the order of the array does not matter.

O(n) time, O(1) space, which beats both the hash-set approach at O(n) space and the sort-and-scan at O(n log n) time.

**Program**

```csharp
using System;

public class Solution
{
    public static int SingleNumber(int[] nums)
    {
        int result = 0;
        foreach (int n in nums) result ^= n;   // pairs cancel, the lone value remains
        return result;
    }

    // Two values appear once, the rest twice. Partition by a differing bit.
    public static int[] TwoSingleNumbers(int[] nums)
    {
        int xorOfBoth = 0;
        foreach (int n in nums) xorOfBoth ^= n;

        // Any set bit here is a bit where the two answers differ.
        int differingBit = xorOfBoth & -xorOfBoth;   // isolates the lowest set bit

        int a = 0, b = 0;
        foreach (int n in nums)
        {
            if ((n & differingBit) != 0) a ^= n;
            else b ^= n;
        }

        return new[] { Math.Min(a, b), Math.Max(a, b) };
    }

    public static void Main()
    {
        Console.WriteLine(SingleNumber(new[] { 2, 2, 1 }));
        Console.WriteLine(SingleNumber(new[] { 4, 1, 2, 1, 2 }));
        Console.WriteLine(SingleNumber(new[] { 1 }));
        Console.WriteLine(SingleNumber(new[] { -3, -3, 7 }));       // negatives are fine
        Console.WriteLine(string.Join(",", TwoSingleNumbers(new[] { 1, 2, 1, 3, 2, 5 })));
        Console.WriteLine(string.Join(",", TwoSingleNumbers(new[] { -1, 0 })));
    }
}
```

