**Logic**

The straightforward version shifts the result left, takes the input's lowest bit, and shifts the input right, 32 times. That is O(1) since the width is fixed.

The divide-and-conquer version is far faster: swap adjacent bits, then adjacent pairs, then nibbles, then bytes, then halves, using masks. Five steps instead of thirty-two, and it is how real implementations do it.

Use `uint` throughout. Right-shifting a negative `int` in C# is arithmetic, filling with ones, so the loop would never clear and the result would be wrong.

**Program**

```csharp
using System;

public class Solution
{
    // 32 iterations, one bit at a time.
    public static uint ReverseBits(uint n)
    {
        uint result = 0;

        for (int i = 0; i < 32; i++)
        {
            result = (result << 1) | (n & 1);   // take the lowest bit of n
            n >>= 1;
        }

        return result;
    }

    // Divide and conquer: swap bits, pairs, nibbles, bytes, halves. Five steps.
    public static uint ReverseBitsFast(uint n)
    {
        n = ((n & 0xAAAAAAAA) >> 1) | ((n & 0x55555555) << 1);   // adjacent bits
        n = ((n & 0xCCCCCCCC) >> 2) | ((n & 0x33333333) << 2);   // pairs
        n = ((n & 0xF0F0F0F0) >> 4) | ((n & 0x0F0F0F0F) << 4);   // nibbles
        n = ((n & 0xFF00FF00) >> 8) | ((n & 0x00FF00FF) << 8);   // bytes
        n = (n >> 16) | (n << 16);                               // halves
        return n;
    }

    private static string Bin(uint n) => System.Convert.ToString(n, 2).PadLeft(32, '0');

    public static void Main()
    {
        Console.WriteLine(ReverseBits(43261596));
        Console.WriteLine(ReverseBitsFast(43261596));
        Console.WriteLine(ReverseBits(0));
        Console.WriteLine(ReverseBits(uint.MaxValue));
        Console.WriteLine(ReverseBits(1));              // becomes the top bit
        Console.WriteLine(Bin(ReverseBitsFast(1)));
    }
}
```

