**Logic**

Calling a popcount routine n times is O(n log n). Dynamic programming makes it O(n), by observing that every number relates to a smaller one whose answer is already known.

The cleanest recurrence uses `i & (i - 1)`, which clears the lowest set bit and therefore yields a strictly smaller number with exactly one fewer set bit. So `bits[i] = bits[i & (i - 1)] + 1`.

An equivalent formulation uses `i >> 1` plus the lowest bit, since shifting right drops one bit whose value is `i & 1`.

**Program**

```csharp
using System;

public class Solution
{
    public static int[] CountBits(int n)
    {
        if (n < 0) throw new ArgumentOutOfRangeException(nameof(n));

        var bits = new int[n + 1];

        // i & (i-1) clears the lowest set bit, giving a smaller, already-solved number.
        for (int i = 1; i <= n; i++)
            bits[i] = bits[i & (i - 1)] + 1;

        return bits;
    }

    // Equivalent: drop the lowest bit by shifting, then add it back.
    public static int[] CountBitsShift(int n)
    {
        var bits = new int[n + 1];
        for (int i = 1; i <= n; i++)
            bits[i] = bits[i >> 1] + (i & 1);
        return bits;
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(",", CountBits(5)));
        Console.WriteLine(string.Join(",", CountBitsShift(5)));
        Console.WriteLine(string.Join(",", CountBits(0)));
        Console.WriteLine(string.Join(",", CountBits(1)));
        Console.WriteLine(string.Join(",", CountBits(8)));
        Console.WriteLine(CountBits(1000)[1000]);
    }
}
```

