0,1,1,2,1,2
0
0,1
0,1,1,2,1,2,2,3,1
6
```

Combine a dictionary for O(1) lookup with a doubly linked list that keeps entries in recency order: most recent at the head, least recent at the tail. `Get` moves the node to the head, `Put` inserts at the head and evicts from the tail when capacity is exceeded. The list must be doubly linked so a node can be unlinked in O(1) given only the node itself.

```csharp
public class LruCache<TKey, TValue>
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<(TKey Key, TValue Value)>> _map;
    private readonly LinkedList<(TKey Key, TValue Value)> _order = new();

    public LruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _capacity = capacity;
        _map = new Dictionary<TKey, LinkedListNode<(TKey, TValue)>>(capacity);
    }

    public bool TryGet(TKey key, out TValue value)
    {
        if (!_map.TryGetValue(key, out var node)) { value = default!; return false; }
        _order.Remove(node);          // O(1): we hold the node, not an index
        _order.AddFirst(node);
        value = node.Value.Value;
        return true;
    }

    public void Put(TKey key, TValue value)
    {
        if (_map.TryGetValue(key, out var existing))
        {
            _order.Remove(existing);
            _map.Remove(key);
        }
        else if (_map.Count >= _capacity)
        {
            var lru = _order.Last!;   // tail is the least recently used
            _order.RemoveLast();
            _map.Remove(lru.Value.Key);
        }
        _map[key] = _order.AddFirst((key, value));
    }
}
```

Storing the key inside the node value is what makes eviction possible: on eviction you have the node but still need its key to remove the dictionary entry.

**Logic**

LFU evicts the least *frequently* used item, breaking ties by least recently used. Achieving O(1) for both get and put needs three structures working together.

A map from key to node holds the data. A map from frequency to a doubly linked list holds all keys at that frequency, in recency order. And a single `minFrequency` counter tracks which list to evict from.

The insight that makes `minFrequency` maintainable in O(1): it only ever increases by one when the item at the minimum frequency is promoted and its list empties, and it resets to 1 whenever a new item is inserted.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class LfuCache
{
    private sealed class Entry
    {
        public int Key;
        public int Value;
        public int Frequency;
    }

    private readonly int _capacity;
    private readonly Dictionary<int, LinkedListNode<Entry>> _entries = new();
    private readonly Dictionary<int, LinkedList<Entry>> _byFrequency = new();
    private int _minFrequency;

    public LfuCache(int capacity)
    {
        if (capacity < 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _capacity = capacity;
    }

    public int Get(int key)
    {
        if (!_entries.TryGetValue(key, out var node)) return -1;

        Promote(node);
        return node.Value.Value;
    }

    public void Put(int key, int value)
    {
        if (_capacity == 0) return;

        if (_entries.TryGetValue(key, out var existing))
        {
            existing.Value.Value = value;
            Promote(existing);
            return;
        }

        if (_entries.Count >= _capacity) Evict();

        var entry = new Entry { Key = key, Value = value, Frequency = 1 };
        _entries[key] = GetList(1).AddFirst(entry);
        _minFrequency = 1;                  // a brand new item is always the minimum
    }

    // Move a node from its frequency list to the next one up.
    private void Promote(LinkedListNode<Entry> node)
    {
        int oldFrequency = node.Value.Frequency;
        var oldList = _byFrequency[oldFrequency];
        oldList.Remove(node);

        // If that emptied the minimum list, the minimum has moved up by exactly one.
        if (oldList.Count == 0 && _minFrequency == oldFrequency) _minFrequency++;

        node.Value.Frequency = oldFrequency + 1;
        _entries[node.Value.Key] = GetList(node.Value.Frequency).AddFirst(node.Value);
    }

    private void Evict()
    {
        var list = _byFrequency[_minFrequency];
        var victim = list.Last;             // least recently used among the least frequent
        list.RemoveLast();
        _entries.Remove(victim.Value.Key);
    }

    private LinkedList<Entry> GetList(int frequency)
    {
        if (!_byFrequency.TryGetValue(frequency, out var list))
            _byFrequency[frequency] = list = new LinkedList<Entry>();
        return list;
    }
}

public class Solution
{
    public static void Main()
    {
        var cache = new LfuCache(2);

        cache.Put(1, 1);
        cache.Put(2, 2);
        Console.WriteLine(cache.Get(1));      // 1 now has frequency 2

        cache.Put(3, 3);                      // evicts key 2, the least frequent
        Console.WriteLine(cache.Get(2));      // gone
        Console.WriteLine(cache.Get(3));

        cache.Put(4, 4);                      // 1 and 3 both at 2; 1 is older, so it goes
        Console.WriteLine(cache.Get(1));
        Console.WriteLine(cache.Get(4));

        var zero = new LfuCache(0);
        zero.Put(1, 1);
        Console.WriteLine(zero.Get(1));       // capacity 0 stores nothing
    }
}
