A bucket holds up to `capacity` tokens and refills at a fixed rate. Each request takes a token; if none are available the request is rejected or delayed. Refill is computed lazily from elapsed time rather than by a background timer, which keeps it cheap and correct across idle periods.

```csharp
public sealed class TokenBucket
{
    private readonly double _capacity;
    private readonly double _refillPerSecond;
    private readonly object _gate = new();
    private double _tokens;
    private long _lastTicks;

    public TokenBucket(double capacity, double refillPerSecond)
    {
        _capacity = capacity;
        _refillPerSecond = refillPerSecond;
        _tokens = capacity;                    // start full so a cold client is not penalised
        _lastTicks = Stopwatch.GetTimestamp(); // monotonic; DateTime.UtcNow can jump
    }

    public bool TryConsume(double tokens = 1)
    {
        lock (_gate)
        {
            long now = Stopwatch.GetTimestamp();
            double elapsed = (now - _lastTicks) / (double)Stopwatch.Frequency;
            _lastTicks = now;

            _tokens = Math.Min(_capacity, _tokens + elapsed * _refillPerSecond);
            if (_tokens < tokens) return false;
            _tokens -= tokens;
            return true;
        }
    }
}
```

Two details matter: `Stopwatch.GetTimestamp` rather than `DateTime.UtcNow`, because a wall-clock adjustment would otherwise grant or destroy tokens; and clamping at `_capacity`, which is what bounds the burst an idle client can accumulate.

**Logic**

Random selection needs contiguous indexing, which an array gives, but arbitrary removal from an array is O(n) because of the shifting. The trick removes the shifting: swap the doomed element with the last one, then remove from the end.

A dictionary from value to index makes lookup O(1), and it must be updated for the element that was swapped into the vacated slot. Forgetting that update is the classic bug and leaves a stale index behind.

All three operations are O(1), with O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class RandomisedSet
{
    private readonly List<int> _items = new();
    private readonly Dictionary<int, int> _indexOf = new();
    private readonly Random _rng;

    public RandomisedSet(int seed = 42) => _rng = new Random(seed);

    public bool Insert(int value)
    {
        if (_indexOf.ContainsKey(value)) return false;

        _indexOf[value] = _items.Count;
        _items.Add(value);
        return true;
    }

    public bool Remove(int value)
    {
        if (!_indexOf.TryGetValue(value, out int index)) return false;

        int lastIndex = _items.Count - 1;
        int lastValue = _items[lastIndex];

        // Move the last element into the hole, then trim. No shifting.
        _items[index] = lastValue;
        _indexOf[lastValue] = index;       // the moved element has a new index

        _items.RemoveAt(lastIndex);
        _indexOf.Remove(value);

        return true;
    }

    public int GetRandom()
    {
        if (_items.Count == 0) throw new InvalidOperationException("set is empty");
        return _items[_rng.Next(_items.Count)];
    }

    public int Count => _items.Count;
}

public class Solution
{
    public static void Main()
    {
        var set = new RandomisedSet();

        Console.WriteLine(set.Insert(1));      // true
        Console.WriteLine(set.Insert(1));      // already present
        Console.WriteLine(set.Remove(2));      // not present

        set.Insert(2);
        set.Insert(3);
        Console.WriteLine(set.Count);

        // Removing the element that is NOT last exercises the swap.
        Console.WriteLine(set.Remove(1));
        Console.WriteLine(set.Count);

        // Whatever comes back must still be a member.
        int drawn = set.GetRandom();
        Console.WriteLine(drawn == 2 || drawn == 3);

        set.Remove(2); set.Remove(3);
        try { set.GetRandom(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
```

