```
True
False
False
3
True
2
True
set is empty
```

**Logic**

A trie over the stored phrases, where each node caches the top k completions beneath it. Walking the prefix is O(prefix length), and the answer is then read straight from the node rather than searched for.

The alternative, walking the prefix and then traversing the whole subtree to collect and rank candidates, is correct but slow when a common prefix has thousands of descendants. Caching at each node moves that cost to insertion time, which is the right trade when reads vastly outnumber writes.

Tie-breaking must be defined: here by descending frequency, then alphabetically, so results are deterministic.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Autocomplete
{
    private sealed class Node
    {
        public readonly Dictionary<char, Node> Children = new();
        // Cached top suggestions beneath this node, best first.
        public readonly List<(string Phrase, int Count)> Top = new();
    }

    private readonly Node _root = new();
    private readonly Dictionary<string, int> _counts = new();
    private readonly int _k;

    public Autocomplete(int k = 3) => _k = k;

    public void Add(string phrase, int times = 1)
    {
        if (string.IsNullOrEmpty(phrase)) return;

        _counts[phrase] = _counts.TryGetValue(phrase, out int c) ? c + times : times;
        int total = _counts[phrase];

        var node = _root;
        UpdateTop(node, phrase, total);

        foreach (char ch in phrase)
        {
            if (!node.Children.TryGetValue(ch, out var next))
                node.Children[ch] = next = new Node();
            node = next;

            UpdateTop(node, phrase, total);
        }
    }

    // Keep each node's cached list sorted and capped at k.
    private void UpdateTop(Node node, string phrase, int count)
    {
        int existing = node.Top.FindIndex(t => t.Phrase == phrase);
        if (existing >= 0) node.Top.RemoveAt(existing);

        node.Top.Add((phrase, count));

        // Frequency descending, then alphabetical: deterministic ties.
        node.Top.Sort((a, b) => b.Count != a.Count
            ? b.Count.CompareTo(a.Count)
            : string.CompareOrdinal(a.Phrase, b.Phrase));

        if (node.Top.Count > _k) node.Top.RemoveAt(node.Top.Count - 1);
    }

    public IList<string> Suggest(string prefix)
    {
        var node = _root;

        foreach (char ch in prefix)
            if (!node.Children.TryGetValue(ch, out node)) return Array.Empty<string>();

        return node.Top.Select(t => t.Phrase).ToList();   // already ranked
    }
}

public class Solution
{
    public static void Main()
    {
        var ac = new Autocomplete(3);

        ac.Add("cat", 5);
        ac.Add("car", 8);
        ac.Add("card", 2);
        ac.Add("care", 9);
        ac.Add("dog", 4);

        Console.WriteLine(string.Join(",", ac.Suggest("ca")));
        Console.WriteLine(string.Join(",", ac.Suggest("car")));
        Console.WriteLine(string.Join(",", ac.Suggest("d")));
        Console.WriteLine(string.Join(",", ac.Suggest("z")).Length);   // no match

        ac.Add("cat", 10);                                  // now the most frequent
        Console.WriteLine(string.Join(",", ac.Suggest("ca")));
        Console.WriteLine(string.Join(",", ac.Suggest("")));
    }
}
