**Logic**

A single tracked minimum fails, because popping the minimum must restore the *previous* minimum, which requires history. So keep a parallel stack whose top is always the minimum of everything currently stored.

The space-efficient refinement pushes onto the auxiliary stack only when the incoming value is less than or equal to the current minimum, and pops only when the removed value equals the top. The `equal to` in both conditions is essential: with two copies of the minimum, tracking only one would report a stale minimum after the first pop.

All operations are O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class MinMaxStack
{
    private readonly Stack<int> _values = new();
    private readonly Stack<int> _minima = new();
    private readonly Stack<int> _maxima = new();

    public void Push(int value)
    {
        _values.Push(value);

        // <= and >= so duplicates of the extremum are each recorded.
        if (_minima.Count == 0 || value <= _minima.Peek()) _minima.Push(value);
        if (_maxima.Count == 0 || value >= _maxima.Peek()) _maxima.Push(value);
    }

    public int Pop()
    {
        if (_values.Count == 0) throw new InvalidOperationException("stack is empty");

        int value = _values.Pop();

        if (_minima.Count > 0 && value == _minima.Peek()) _minima.Pop();
        if (_maxima.Count > 0 && value == _maxima.Peek()) _maxima.Pop();

        return value;
    }

    public int Peek() => _values.Count > 0
        ? _values.Peek()
        : throw new InvalidOperationException("stack is empty");

    public int Min() => _minima.Count > 0
        ? _minima.Peek()
        : throw new InvalidOperationException("stack is empty");

    public int Max() => _maxima.Count > 0
        ? _maxima.Peek()
        : throw new InvalidOperationException("stack is empty");

    public int Count => _values.Count;
}

public class Solution
{
    public static void Main()
    {
        var s = new MinMaxStack();
        s.Push(5); s.Push(2); s.Push(8); s.Push(2);

        Console.WriteLine($"{s.Min()} {s.Max()}");

        s.Pop();                       // removes one of the two 2s
        Console.WriteLine(s.Min());    // still 2: the duplicate was recorded

        s.Pop();                       // removes the 8
        Console.WriteLine(s.Max());

        s.Pop();                       // removes the other 2
        Console.WriteLine($"{s.Min()} {s.Max()}");

        Console.WriteLine(s.Count);

        s.Pop();
        try { s.Min(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
```

