**Logic**

The feed is the interesting part: the ten most recent tweets from a user and everyone they follow, merged by time. That is merging k sorted lists, so a heap over each followee's most recent tweets gives O(k log k) rather than gathering and sorting everything.

A global counter as the timestamp avoids clock resolution problems: two tweets in the same millisecond would otherwise tie and order non-deterministically.

Storing each user's tweets newest-first means the heap only needs the head of each list, pulling the next one lazily as tweets are consumed.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Twitter
{
    private const int FeedSize = 10;

    private int _clock;   // monotonic counter, not a wall clock

    private readonly Dictionary<int, List<(int Time, int TweetId)>> _tweets = new();
    private readonly Dictionary<int, HashSet<int>> _following = new();

    public void PostTweet(int userId, int tweetId)
    {
        if (!_tweets.TryGetValue(userId, out var list))
            _tweets[userId] = list = new List<(int, int)>();

        list.Add((_clock++, tweetId));
    }

    public IList<int> GetNewsFeed(int userId)
    {
        // The user's own tweets plus everyone they follow.
        var sources = new HashSet<int> { userId };
        if (_following.TryGetValue(userId, out var followed)) sources.UnionWith(followed);

        // Max-heap on time, seeded with each source's most recent tweet.
        var heap = new PriorityQueue<(int UserId, int Index), int>();

        foreach (int source in sources)
            if (_tweets.TryGetValue(source, out var list) && list.Count > 0)
            {
                int last = list.Count - 1;
                heap.Enqueue((source, last), -list[last].Time);
            }

        var feed = new List<int>(FeedSize);

        while (heap.Count > 0 && feed.Count < FeedSize)
        {
            var (source, index) = heap.Dequeue();
            feed.Add(_tweets[source][index].TweetId);

            if (index > 0)   // pull that user's next-most-recent tweet lazily
                heap.Enqueue((source, index - 1), -_tweets[source][index - 1].Time);
        }

        return feed;
    }

    public void Follow(int followerId, int followeeId)
    {
        if (followerId == followeeId) return;             // following yourself is implicit

        if (!_following.TryGetValue(followerId, out var set))
            _following[followerId] = set = new HashSet<int>();

        set.Add(followeeId);
    }

    public void Unfollow(int followerId, int followeeId)
    {
        if (_following.TryGetValue(followerId, out var set)) set.Remove(followeeId);
    }
}

public class Solution
{
    public static void Main()
    {
        var t = new Twitter();

        t.PostTweet(1, 5);
        Console.WriteLine(string.Join(",", t.GetNewsFeed(1)));

        t.Follow(1, 2);
        t.PostTweet(2, 6);
        Console.WriteLine(string.Join(",", t.GetNewsFeed(1)));   // newest first

        t.Unfollow(1, 2);
        Console.WriteLine(string.Join(",", t.GetNewsFeed(1)));

        Console.WriteLine(string.Join(",", t.GetNewsFeed(99)).Length);   // unknown user

        // The feed is capped at ten.
        for (int i = 0; i < 15; i++) t.PostTweet(3, 100 + i);
        Console.WriteLine(t.GetNewsFeed(3).Count);
        Console.WriteLine(t.GetNewsFeed(3)[0]);                  // the most recent
    }
}
