**Logic**

Mark multiples rather than testing divisibility. Start at 2 and cross off every multiple; the next unmarked number is prime, and the process repeats.

Two standard optimisations. Stop the outer loop at the square root of n, because any composite below n has a factor at or below that. And start crossing off at p squared rather than 2p, since smaller multiples were already handled by smaller primes.

O(n log log n) time, O(n) space, which is close enough to linear that it is the standard method.

**Program**

```csharp
using System;

public class Solution
{
    public static int CountPrimes(int n)
    {
        if (n < 3) return 0;                  // no primes below 2

        var composite = new bool[n];          // composite[i] == true means "not prime"
        int count = 0;

        for (int p = 2; (long)p * p < n; p++)
        {
            if (composite[p]) continue;       // already crossed off: not prime

            // Start at p*p: smaller multiples had a smaller prime factor.
            for (long multiple = (long)p * p; multiple < n; multiple += p)
                composite[(int)multiple] = true;
        }

        for (int i = 2; i < n; i++) if (!composite[i]) count++;
        return count;
    }

    public static void Main()
    {
        Console.WriteLine(CountPrimes(10));       // 2,3,5,7
        Console.WriteLine(CountPrimes(2));        // strictly below 2
        Console.WriteLine(CountPrimes(3));        // just 2
        Console.WriteLine(CountPrimes(0));
        Console.WriteLine(CountPrimes(100));
        Console.WriteLine(CountPrimes(1000000));
    }
}
```

