**Logic**

Exponentiation by squaring. Halving the exponent squares the base, so `x^n` becomes `(x^2)^(n/2)` for even n, and one extra factor of x for odd n. That reduces n multiplications to log n.

Two traps. A negative exponent means taking the reciprocal, and negating `int.MinValue` overflows, so widen to `long` before negating. And the loop must accumulate the odd factors rather than only squaring.

O(log n) time, O(1) space iteratively.

**Program**

```csharp
using System;

public class Solution
{
    public static double MyPow(double x, int n)
    {
        // Widen BEFORE negating: -int.MinValue overflows an int.
        long exponent = n;

        if (exponent < 0)
        {
            x = 1 / x;
            exponent = -exponent;
        }

        double result = 1;

        while (exponent > 0)
        {
            if ((exponent & 1) == 1) result *= x;   // odd: take one factor out
            x *= x;                                  // square the base
            exponent >>= 1;                          // halve the exponent
        }

        return result;
    }

    // Modular version: the shape used constantly in cryptography.
    public static long PowMod(long baseValue, long exponent, long modulus)
    {
        long result = 1;
        baseValue %= modulus;

        while (exponent > 0)
        {
            if ((exponent & 1) == 1) result = result * baseValue % modulus;
            baseValue = baseValue * baseValue % modulus;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        Console.WriteLine(MyPow(2, 10));
        Console.WriteLine(MyPow(2, -2));
        Console.WriteLine(MyPow(2, 0));
        Console.WriteLine(MyPow(1, int.MinValue));     // the overflow case
        Console.WriteLine(MyPow(0.5, 3));
        Console.WriteLine(PowMod(2, 100, 1000000007));
    }
}
```

