-321
21
0
0
0
```

**Logic**

Excel columns look like base 26 but are not: there is no zero digit. A runs to Z, then AA follows Z, so the system is bijective base 26 with digits 1 to 26 rather than 0 to 25.

That is why converting a number subtracts one before each modulo: it shifts the range from 1-26 down to 0-25 so the remainder maps onto a letter. Forgetting it makes 26 render as A@ or similar nonsense instead of Z.

The reverse direction is ordinary positional accumulation, multiplying by 26 and adding the letter's value.

**Program**

```csharp
using System;
using System.Text;

public class Solution
{
    public static string ToTitle(int columnNumber)
    {
        if (columnNumber <= 0) throw new ArgumentOutOfRangeException(nameof(columnNumber));

        var sb = new StringBuilder();

        while (columnNumber > 0)
        {
            columnNumber--;                                  // shift 1..26 to 0..25
            sb.Insert(0, (char)('A' + columnNumber % 26));
            columnNumber /= 26;
        }

        return sb.ToString();
    }

    public static int ToNumber(string title)
    {
        if (string.IsNullOrEmpty(title)) throw new ArgumentException("empty title");

        int result = 0;

        foreach (char c in title)
        {
            if (c < 'A' || c > 'Z') throw new ArgumentException($"bad character '{c}'");
            result = result * 26 + (c - 'A' + 1);            // digits are 1..26
        }

        return result;
    }

    public static void Main()
    {
        Console.WriteLine(ToTitle(1));
        Console.WriteLine(ToTitle(26));      // Z, not A@
        Console.WriteLine(ToTitle(27));      // AA
        Console.WriteLine(ToTitle(701));     // ZY
        Console.WriteLine(ToNumber("AB"));
        Console.WriteLine($"{ToNumber(ToTitle(12345))} round trip");
    }
}
