**Logic**

A one-to-one correspondence needs mapping in both directions. Walk the strings together maintaining two maps: one from s to t and one from t to s. At each position, either both mappings are absent, in which case record them, or both must already agree with the current pair.

One map alone is not enough. Mapping a to x and b to x satisfies a forward check but is not a bijection, so "ab" and "xx" would wrongly pass. The reverse map is what rejects that.

O(n) time, O(alphabet) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static bool IsIsomorphic(string s, string t)
    {
        if (s == null || t == null) return s == t;
        if (s.Length != t.Length) return false;

        var forward = new Dictionary<char, char>();
        var backward = new Dictionary<char, char>();

        for (int i = 0; i < s.Length; i++)
        {
            char a = s[i], b = t[i];

            bool hasForward = forward.TryGetValue(a, out char mappedTo);
            bool hasBackward = backward.TryGetValue(b, out char mappedFrom);

            if (hasForward != hasBackward) return false;       // one-sided mapping
            if (hasForward && (mappedTo != b || mappedFrom != a)) return false;

            forward[a] = b;
            backward[b] = a;
        }

        return true;
    }

    public static void Main()
    {
        Console.WriteLine(IsIsomorphic("egg", "add"));
        Console.WriteLine(IsIsomorphic("foo", "bar"));
        Console.WriteLine(IsIsomorphic("paper", "title"));
        Console.WriteLine(IsIsomorphic("ab", "xx"));     // not one-to-one
        Console.WriteLine(IsIsomorphic("", ""));
        Console.WriteLine(IsIsomorphic("ab", "abc"));    // different lengths
    }
}
```

