**Logic**

Two pointers: a read pointer scanning runs and a write pointer laying down the compressed form. For each run, write the character, then write its count as digits only when the count exceeds one.

The write pointer can never overtake the read pointer, because a run of length one writes one character and consumes one, and longer runs always write fewer characters than they consume. That invariant is what makes it safe in place.

Counts of ten or more take several characters, so the digits must be written individually rather than as a single char. O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int Compress(char[] chars)
    {
        if (chars == null || chars.Length == 0) return 0;

        int write = 0, read = 0;

        while (read < chars.Length)
        {
            char current = chars[read];
            int runLength = 0;

            while (read < chars.Length && chars[read] == current) { read++; runLength++; }

            chars[write++] = current;

            if (runLength > 1)
            {
                // A count of 12 is two characters, not one: write the digits.
                foreach (char digit in runLength.ToString())
                    chars[write++] = digit;
            }
        }

        return write;   // the compressed length
    }

    private static string Show(string input)
    {
        var chars = input.ToCharArray();
        int length = Compress(chars);
        return new string(chars, 0, length) + " (" + length + ")";
    }

    public static void Main()
    {
        Console.WriteLine(Show("aabbccc"));
        Console.WriteLine(Show("a"));                    // no count for a single
        Console.WriteLine(Show("abc"));                  // longer than the input
        Console.WriteLine(Show(new string('a', 12)));    // two-digit count
        Console.WriteLine(Show("aabbbbbbbbbbbb"));
        Console.WriteLine(Show(""));
    }
}
```

