**Logic**

Simulate the walk rather than computing positions with a formula. Keep one buffer per row, a current row index and a direction. Append each character to its row, then move the row index by the direction, flipping the direction at the top and bottom rows.

Concatenating the rows at the end gives the answer. O(n) time and space.

The single-row case must be handled, otherwise the direction never flips and the walk runs off the end. That is the case most implementations forget.

**Program**

```csharp
using System;
using System.Text;

public class Solution
{
    public static string Convert(string s, int numRows)
    {
        if (string.IsNullOrEmpty(s) || numRows <= 1) return s;   // one row: no zigzag
        if (numRows >= s.Length) return s;                        // never turns around

        var rows = new StringBuilder[numRows];
        for (int i = 0; i < numRows; i++) rows[i] = new StringBuilder();

        int row = 0, direction = 1;   // +1 going down, -1 going up

        foreach (char c in s)
        {
            rows[row].Append(c);

            // Flip at the top and bottom edges.
            if (row == 0) direction = 1;
            else if (row == numRows - 1) direction = -1;

            row += direction;
        }

        var sb = new StringBuilder(s.Length);
        foreach (var r in rows) sb.Append(r);
        return sb.ToString();
    }

    public static void Main()
    {
        Console.WriteLine(Convert("PAYPALISHIRING", 3));
        Console.WriteLine(Convert("PAYPALISHIRING", 4));
        Console.WriteLine(Convert("AB", 1));          // one row: unchanged
        Console.WriteLine(Convert("ABC", 5));         // more rows than characters
        Console.WriteLine(Convert("", 3));
        Console.WriteLine(Convert("ABCDE", 2));
    }
}
```

