**Logic**

Long multiplication, digit by digit. The key placement fact is that multiplying the digit at index i of one number by the digit at index j of the other contributes to positions i+j and i+j+1 of the result, counting from the left.

So allocate `m + n` slots, accumulate every product into its low position, and carry into the high one. Because the carry is folded in as you go, no value ever exceeds what a single int can hold.

Finally strip leading zeros, and handle an all-zero result as "0". O(m × n) time.

**Program**

```csharp
using System;
using System.Text;

public class Solution
{
    public static string Multiply(string a, string b)
    {
        if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b)) return "0";
        if (a == "0" || b == "0") return "0";       // avoids a string of zeros

        int m = a.Length, n = b.Length;
        var digits = new int[m + n];                 // the product never needs more

        for (int i = m - 1; i >= 0; i--)
            for (int j = n - 1; j >= 0; j--)
            {
                int product = (a[i] - '0') * (b[j] - '0');

                int low = i + j + 1;                 // units position of this product
                int high = i + j;                    // carry position

                int sum = product + digits[low];
                digits[low] = sum % 10;
                digits[high] += sum / 10;            // carry folded in immediately
            }

        var sb = new StringBuilder();
        foreach (int d in digits)
        {
            if (sb.Length == 0 && d == 0) continue;  // skip leading zeros
            sb.Append(d);
        }

        return sb.Length == 0 ? "0" : sb.ToString();
    }

    public static void Main()
    {
        Console.WriteLine(Multiply("2", "3"));
        Console.WriteLine(Multiply("123", "456"));
        Console.WriteLine(Multiply("0", "52"));
        Console.WriteLine(Multiply("999", "999"));
        Console.WriteLine(Multiply("123456789", "987654321"));   // exceeds int range
        Console.WriteLine(Multiply("9", "99"));
    }
}
```

