**Logic**

School addition in base two. Walk both strings from the right, adding the digits plus a carry; the output bit is the sum modulo two and the new carry is the sum divided by two. Continue while either string has digits left or a carry remains, so a final carry produces one more bit.

Building the result in reverse and reversing once at the end avoids repeatedly inserting at the front, which would be quadratic.

O(max(m, n)) time.

**Program**

```csharp
using System;
using System.Text;

public class Solution
{
    public static string AddBinary(string a, string b)
    {
        if (string.IsNullOrEmpty(a)) return b ?? "0";
        if (string.IsNullOrEmpty(b)) return a;

        var sb = new StringBuilder();
        int i = a.Length - 1, j = b.Length - 1, carry = 0;

        // The carry is part of the condition, so a final carry emits a bit.
        while (i >= 0 || j >= 0 || carry != 0)
        {
            int sum = carry;
            if (i >= 0) sum += a[i--] - '0';
            if (j >= 0) sum += b[j--] - '0';

            sb.Append((char)('0' + (sum % 2)));
            carry = sum / 2;
        }

        // Built backwards, so one reverse rather than n front-insertions.
        var chars = sb.ToString().ToCharArray();
        Array.Reverse(chars);
        return new string(chars);
    }

    public static void Main()
    {
        Console.WriteLine(AddBinary("11", "1"));
        Console.WriteLine(AddBinary("1010", "1011"));
        Console.WriteLine(AddBinary("0", "0"));
        Console.WriteLine(AddBinary("1", "1"));          // carry creates a new bit
        Console.WriteLine(AddBinary("1111", "1"));       // cascading carry
        Console.WriteLine(AddBinary("100", "110010"));   // different lengths
    }
}
