**Logic**

For integer to Roman, list the values in descending order *including* the six subtractive forms (900, 400, 90, 40, 9, 4) as if they were ordinary symbols. Then a plain greedy loop, repeatedly subtracting the largest value that fits, produces the canonical numeral with no special cases at all.

For Roman to integer, scan left to right: if a symbol's value is less than the next one's, it is subtractive, so subtract it; otherwise add it. That single rule covers every valid numeral.

Both are O(1) in practice, since numerals are bounded.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    // Subtractive forms are listed as values, so the greedy needs no exceptions.
    private static readonly (int Value, string Symbol)[] Table =
    {
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"),  (90, "XC"),  (50, "L"),  (40, "XL"),
        (10, "X"),   (9, "IX"),   (5, "V"),   (4, "IV"), (1, "I"),
    };

    public static string ToRoman(int number)
    {
        if (number <= 0 || number > 3999)
            throw new ArgumentOutOfRangeException(nameof(number), "Roman numerals cover 1..3999");

        var sb = new StringBuilder();

        foreach (var (value, symbol) in Table)
            while (number >= value)
            {
                sb.Append(symbol);
                number -= value;
            }

        return sb.ToString();
    }

    private static readonly Dictionary<char, int> Values = new()
    {
        ['I'] = 1, ['V'] = 5, ['X'] = 10, ['L'] = 50,
        ['C'] = 100, ['D'] = 500, ['M'] = 1000,
    };

    public static int FromRoman(string roman)
    {
        if (string.IsNullOrEmpty(roman)) return 0;

        int total = 0;

        for (int i = 0; i < roman.Length; i++)
        {
            int current = Values[roman[i]];

            // Smaller before larger means subtractive: IV is 4, VI is 6.
            bool subtractive = i + 1 < roman.Length && current < Values[roman[i + 1]];

            total += subtractive ? -current : current;
        }

        return total;
    }

    public static void Main()
    {
        Console.WriteLine(ToRoman(3));
        Console.WriteLine(ToRoman(58));
        Console.WriteLine(ToRoman(1994));
        Console.WriteLine(FromRoman("MCMXCIV"));
        Console.WriteLine(FromRoman("LVIII"));
        Console.WriteLine(ToRoman(3999) + " -> " + FromRoman(ToRoman(3999)));
    }
}
```

**Output**

```
III
LVIII
MCMXCIV
1994
