**Approach**

Greedy line packing, then a separate distribution pass. Fit as many words on a line as possible, then spread the leftover spaces between them.

**Logic**

A word fits if the current length plus one space plus the word does not exceed the width. Once the line is full, distribute.

The distribution rule is where this is won or lost. With `gaps` gaps and `spaces` characters to distribute, each gap gets `spaces / gaps`, and the first `spaces % gaps` gaps get one extra. That puts the wider gaps on the left, which is what the specification requires.

Two lines are special: the last line is left-justified with single spaces, and a line holding one word is left-justified with the padding on the right.

O(total characters) time.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    public static IList<string> FullJustify(string[] words, int maxWidth)
    {
        var result = new List<string>();
        int i = 0;

        while (i < words.Length)
        {
            // Greedily pack: length so far + a space + the next word must fit.
            int last = i, lineLength = words[i].Length;
            while (last + 1 < words.Length && lineLength + 1 + words[last + 1].Length <= maxWidth)
            {
                lineLength += 1 + words[last + 1].Length;
                last++;
            }

            int wordCount = last - i + 1;
            int letters = 0;
            for (int w = i; w <= last; w++) letters += words[w].Length;

            var sb = new StringBuilder();
            bool isLastLine = last == words.Length - 1;

            if (isLastLine || wordCount == 1)
            {
                // Left-justified, single spaces, pad the right.
                for (int w = i; w <= last; w++)
                {
                    if (w > i) sb.Append(' ');
                    sb.Append(words[w]);
                }
                sb.Append(new string(' ', maxWidth - sb.Length));
            }
            else
            {
                int gaps = wordCount - 1;
                int spaces = maxWidth - letters;
                int even = spaces / gaps;
                int extra = spaces % gaps;      // the leftmost gaps take the remainder

                for (int w = i; w <= last; w++)
                {
                    sb.Append(words[w]);
                    if (w == last) break;

                    sb.Append(new string(' ', even + (w - i < extra ? 1 : 0)));
                }
            }

            result.Add(sb.ToString());
            i = last + 1;
        }

        return result;
    }

    private static string Show(IList<string> lines, int width)
    {
        foreach (string l in lines)
            if (l.Length != width) return $"BROKEN: line is {l.Length}, expected {width}";

        return string.Join("|", lines);
    }

    public static void Main()
    {
        Console.WriteLine(Show(FullJustify(
            new[] { "This", "is", "an", "example", "of", "text", "justification." }, 16), 16));

        Console.WriteLine(Show(FullJustify(
            new[] { "What", "must", "be", "acknowledgment", "shall", "be" }, 16), 16));

        Console.WriteLine(Show(FullJustify(new[] { "single" }, 10), 10));
        Console.WriteLine(Show(FullJustify(new[] { "a", "b", "c" }, 3), 3));
    }
}
```

**Output**

```
