**Logic**

Two prefix sums with the same remainder modulo k bound a subarray whose sum is a multiple of k, since the difference of the two prefixes has remainder zero. So count how many times each remainder has been seen and add that count as each new prefix arrives.

The trap is negative remainders. In C# `-3 % 5` is -2, not 3, so the two representations of the same residue class would never match. Normalising with `((r % k) + k) % k` fixes it.

Seed the count for remainder 0 with one, representing the empty prefix. O(n) time, O(k) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int SubarraysDivByK(int[] nums, int k)
    {
        if (nums == null || nums.Length == 0 || k == 0) return 0;

        var seen = new int[Math.Abs(k)];
        seen[0] = 1;                 // the empty prefix has remainder 0

        int sum = 0, count = 0;

        foreach (int n in nums)
        {
            sum += n;

            // C# % follows the dividend's sign, so normalise into 0..k-1.
            int remainder = ((sum % k) + k) % k;

            count += seen[remainder];   // every earlier prefix with this remainder
            seen[remainder]++;
        }

        return count;
    }

    public static void Main()
    {
        Console.WriteLine(SubarraysDivByK(new[] { 4, 5, 0, -2, -3, 1 }, 5));
        Console.WriteLine(SubarraysDivByK(new[] { 5 }, 9));
        Console.WriteLine(SubarraysDivByK(new[] { -1, 2, 9 }, 2));
        Console.WriteLine(SubarraysDivByK(new[] { 0, 0, 0 }, 1));    // every subarray
        Console.WriteLine(SubarraysDivByK(new[] { 2, -2, 2, -4 }, 6));
        Console.WriteLine(SubarraysDivByK(new[] { -5, 5 }, 5));
    }
}
```

