**Logic**

For each character, record the last index at which it occurs. Then sweep, extending the current part's boundary to the furthest last-occurrence seen so far. When the scan position reaches that boundary, every character inside the part has all its occurrences contained, so the part can close.

Greedy and correct because closing at the earliest possible boundary maximises the number of parts. O(n) time, O(1) space for a fixed alphabet.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<int> PartitionLabels(string s)
    {
        var result = new List<int>();
        if (string.IsNullOrEmpty(s)) return result;

        // Last index of every character.
        var lastIndex = new int[26];
        for (int i = 0; i < s.Length; i++) lastIndex[s[i] - 'a'] = i;

        int partStart = 0, partEnd = 0;

        for (int i = 0; i < s.Length; i++)
        {
            // The part cannot close before the last occurrence of anything inside it.
            partEnd = Math.Max(partEnd, lastIndex[s[i] - 'a']);

            if (i == partEnd)
            {
                result.Add(partEnd - partStart + 1);
                partStart = i + 1;
            }
        }

        return result;
    }

    private static string Show(string s) =>
        PartitionLabels(s) is var r && r.Count == 0 ? "(none)" : string.Join(",", r);

    public static void Main()
    {
        Console.WriteLine(Show("ababcbacadefegdehijhklij"));
        Console.WriteLine(Show("eccbbbbdec"));      // one part: e wraps everything
        Console.WriteLine(Show("abc"));             // all distinct
        Console.WriteLine(Show("aaaa"));
        Console.WriteLine(Show("a"));
        Console.WriteLine(Show(""));
    }
}
