**Approach**

A difference array over the route. Each trip adds passengers at its start and removes them at its end; sweeping the prefix sum gives the occupancy at every point.

**Logic**

Rather than incrementing every location in a trip's range, add the count at the start index and subtract it at the end index. The running sum of that difference array is the actual occupancy, computed in one pass.

The subtlety is that passengers leave *at* the drop-off point, so a trip ending where another begins does not overlap. Subtracting at the end index rather than after it encodes that.

O(locations + trips) time, O(locations) space.

**Program**

```csharp
using System;

public class Solution
{
    // trips[i] = [passengers, from, to]
    public static bool CarPooling(int[][] trips, int capacity)
    {
        if (trips == null || trips.Length == 0) return true;

        int furthest = 0;
        foreach (var t in trips) furthest = Math.Max(furthest, t[2]);

        var delta = new int[furthest + 1];

        foreach (var t in trips)
        {
            delta[t[1]] += t[0];    // board here
            delta[t[2]] -= t[0];    // alight here, so this point does not overlap
        }

        int onboard = 0;
        foreach (int change in delta)
        {
            onboard += change;
            if (onboard > capacity) return false;
        }

        return true;
    }

    public static void Main()
    {
        Console.WriteLine(CarPooling(new[] {
            new[] { 2, 1, 5 }, new[] { 3, 3, 7 } }, 4));     // overlap of 5 exceeds 4

        Console.WriteLine(CarPooling(new[] {
            new[] { 2, 1, 5 }, new[] { 3, 3, 7 } }, 5));

        // Back to back: the first ends exactly where the second begins.
        Console.WriteLine(CarPooling(new[] {
            new[] { 3, 2, 7 }, new[] { 3, 7, 9 } }, 3));

        Console.WriteLine(CarPooling(new[] { new[] { 5, 0, 1 } }, 4));
        Console.WriteLine(CarPooling(Array.Empty<int[]>(), 1));
        Console.WriteLine(CarPooling(new[] { new[] { 1, 0, 1 } }, 1));
    }
}
