**Logic**

Sort by end coordinate and sweep. Fire an arrow at the end of the first balloon, which bursts every balloon that starts at or before that point. Skip all of those, then fire again at the end of the next unburst balloon.

Shooting at the earliest end is optimal because that point is inside every balloon overlapping the first one, so no better position exists. It is the same exchange argument as activity selection, with the count inverted: there you maximise non-overlapping intervals, here you count overlapping groups.

O(n log n) for the sort, then one pass.

**Program**

```csharp
using System;
using System.Linq;

public class Solution
{
    public static int FindMinArrows(int[][] points)
    {
        if (points == null || points.Length == 0) return 0;

        // Sort by END: the earliest finisher fixes the best arrow position.
        var sorted = points.OrderBy(p => p[1]).ToArray();

        int arrows = 1;
        long arrowAt = sorted[0][1];

        foreach (var balloon in sorted)
        {
            // Already burst if it starts at or before the current arrow.
            if (balloon[0] <= arrowAt) continue;

            arrows++;
            arrowAt = balloon[1];
        }

        return arrows;
    }

    public static void Main()
    {
        Console.WriteLine(FindMinArrows(new[] {
            new[] { 10, 16 }, new[] { 2, 8 }, new[] { 1, 6 }, new[] { 7, 12 } }));

        Console.WriteLine(FindMinArrows(new[] {
            new[] { 1, 2 }, new[] { 3, 4 }, new[] { 5, 6 }, new[] { 7, 8 } }));   // disjoint

        Console.WriteLine(FindMinArrows(new[] {
            new[] { 1, 2 }, new[] { 2, 3 }, new[] { 3, 4 }, new[] { 4, 5 } }));   // touching

        Console.WriteLine(FindMinArrows(new[] { new[] { 1, 10 } }));
        Console.WriteLine(FindMinArrows(new[] {
            new[] { 1, 10 }, new[] { 2, 3 }, new[] { 4, 5 } }));                  // nested
        Console.WriteLine(FindMinArrows(Array.Empty<int[]>()));
    }
}
