**Logic**

Two passes. Give everyone one sweet. Sweep left to right: whenever a child outranks the one on their left, give them one more than that neighbour. Then sweep right to left applying the mirror rule, taking the maximum of the existing count and the neighbour's plus one.

One pass cannot work, because each child is constrained from both sides and a single direction only satisfies one of them. Taking the maximum in the second pass is what preserves the first pass's work rather than overwriting it.

O(n) time, O(n) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int Candy(int[] ratings)
    {
        if (ratings == null || ratings.Length == 0) return 0;

        int n = ratings.Length;
        var sweets = new int[n];
        Array.Fill(sweets, 1);            // everyone gets at least one

        // Left to right: satisfy the left-neighbour constraint.
        for (int i = 1; i < n; i++)
            if (ratings[i] > ratings[i - 1]) sweets[i] = sweets[i - 1] + 1;

        // Right to left: satisfy the right-neighbour constraint without
        // undoing the first pass, hence the Max.
        for (int i = n - 2; i >= 0; i--)
            if (ratings[i] > ratings[i + 1])
                sweets[i] = Math.Max(sweets[i], sweets[i + 1] + 1);

        long total = 0;
        foreach (int s in sweets) total += s;
        return (int)total;
    }

    public static void Main()
    {
        Console.WriteLine(Candy(new[] { 1, 0, 2 }));      // 2,1,2
        Console.WriteLine(Candy(new[] { 1, 2, 2 }));      // 1,2,1 - equal needs no more
        Console.WriteLine(Candy(new[] { 1, 2, 3, 4 }));
        Console.WriteLine(Candy(new[] { 4, 3, 2, 1 }));
        Console.WriteLine(Candy(new[] { 1, 3, 2, 2, 1 }));
        Console.WriteLine(Candy(new[] { 5 }));
    }
}
