**Logic**

A monotonic increasing stack. Scanning left to right, whenever the incoming digit is smaller than the stack top and removals remain, pop: removing a larger digit from a more significant position always lowers the value more than removing anything later.

Three details finish it. If removals remain after the scan, drop them from the end, since the remainder is non-decreasing and the last digits are the least significant. Strip leading zeros. And an empty result means zero.

O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    public static string RemoveKDigits(string num, int k)
    {
        if (string.IsNullOrEmpty(num)) return "0";
        if (k >= num.Length) return "0";      // everything removed

        var stack = new List<char>(num.Length);   // used as a stack, kept in order

        foreach (char digit in num)
        {
            // A bigger digit in a more significant place is always worth removing.
            while (k > 0 && stack.Count > 0 && stack[^1] > digit)
            {
                stack.RemoveAt(stack.Count - 1);
                k--;
            }

            stack.Add(digit);
        }

        // Still removals left: the remainder is non-decreasing, so drop from the end.
        while (k > 0) { stack.RemoveAt(stack.Count - 1); k--; }

        // Strip leading zeros.
        int start = 0;
        while (start < stack.Count - 1 && stack[start] == '0') start++;

        var sb = new StringBuilder();
        for (int i = start; i < stack.Count; i++) sb.Append(stack[i]);

        return sb.Length == 0 ? "0" : sb.ToString();
    }

    public static void Main()
    {
        Console.WriteLine(RemoveKDigits("1432219", 3));
        Console.WriteLine(RemoveKDigits("10200", 1));     // leading zero appears
        Console.WriteLine(RemoveKDigits("10", 2));        // everything goes
        Console.WriteLine(RemoveKDigits("112", 1));       // already increasing
        Console.WriteLine(RemoveKDigits("9", 1));
        Console.WriteLine(RemoveKDigits("100", 1));
    }
}
