**Logic**

Every cell's next state depends on the *current* state of its neighbours, so updating in place naively corrupts the computation for cells not yet visited.

The in-place trick uses a second bit. Keep bit 0 as the current state and write the next state into bit 1, so a cell reads as its old value under `& 1` while carrying its new value. After the whole grid is computed, shift every cell right by one to promote the new state.

O(rows × cols) time, O(1) extra space.

**Program**

```csharp
using System;

public class Solution
{
    public static void GameOfLife(int[][] board)
    {
        if (board == null || board.Length == 0) return;

        int rows = board.Length, cols = board[0].Length;

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                int live = CountLiveNeighbours(board, r, c, rows, cols);
                int current = board[r][c] & 1;             // bit 0 is still the old state

                // Survives with 2 or 3 neighbours; a dead cell is born with exactly 3.
                int next = current == 1
                    ? (live == 2 || live == 3 ? 1 : 0)
                    : (live == 3 ? 1 : 0);

                board[r][c] |= next << 1;                  // stash the new state in bit 1
            }

        // Promote bit 1 to bit 0 once every cell has been computed.
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                board[r][c] >>= 1;
    }

    private static int CountLiveNeighbours(int[][] board, int r, int c, int rows, int cols)
    {
        int live = 0;

        for (int dr = -1; dr <= 1; dr++)
            for (int dc = -1; dc <= 1; dc++)
            {
                if (dr == 0 && dc == 0) continue;
                int nr = r + dr, nc = c + dc;
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;

                live += board[nr][nc] & 1;                 // read the OLD state only
            }

        return live;
    }

    private static string Render(int[][] m) =>
        string.Join(" / ", Array.ConvertAll(m, r => string.Join(",", r)));

    public static void Main()
    {
        var blinker = new[] {
            new[] { 0, 1, 0 },
            new[] { 0, 1, 0 },
            new[] { 0, 1, 0 } };
        GameOfLife(blinker);
        Console.WriteLine(Render(blinker));      // oscillates to horizontal

        var block = new[] {
            new[] { 1, 1 },
            new[] { 1, 1 } };
        GameOfLife(block);
        Console.WriteLine(Render(block));        // still life: unchanged

        var dead = new[] { new[] { 0, 0 }, new[] { 0, 0 } };
        GameOfLife(dead);
        Console.WriteLine(Render(dead));

        var lonely = new[] { new[] { 1, 0 }, new[] { 0, 0 } };
        GameOfLife(lonely);
        Console.WriteLine(Render(lonely));       // dies of underpopulation
    }
}
