**Logic**

Three constraint sets: each row, each column and each 3x3 box must contain no repeated digit. Empty cells are ignored, and the board need not be solvable, only free of conflicts.

One pass suffices with 27 sets, or with three arrays of nine. The box index is the neat part: `(row / 3) * 3 + col / 3` maps each cell to its box number 0 through 8.

O(1) overall, since the board is a fixed 81 cells, though it is O(n²) in the general n×n case.

**Program**

```csharp
using System;

public class Solution
{
    public static bool IsValidSudoku(char[][] board)
    {
        // Bitmask per row, column and box: bit d set means digit d is present.
        var rows = new int[9];
        var cols = new int[9];
        var boxes = new int[9];

        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++)
            {
                char value = board[r][c];
                if (value == '.') continue;               // empty cells are fine

                int bit = 1 << (value - '1');
                int box = (r / 3) * 3 + c / 3;            // maps a cell to its 3x3 box

                if ((rows[r] & bit) != 0) return false;
                if ((cols[c] & bit) != 0) return false;
                if ((boxes[box] & bit) != 0) return false;

                rows[r] |= bit;
                cols[c] |= bit;
                boxes[box] |= bit;
            }

        return true;
    }

    private static char[][] Parse(params string[] rows)
    {
        var b = new char[9][];
        for (int i = 0; i < 9; i++) b[i] = rows[i].ToCharArray();
        return b;
    }

    public static void Main()
    {
        var valid = Parse(
            "53..7....", "6..195...", ".98....6.",
            "8...6...3", "4..8.3..1", "7...2...6",
            ".6....28.", "...419..5", "....8..79");
        Console.WriteLine(IsValidSudoku(valid));

        var duplicateInBox = Parse(
            "83..7....", "6..195...", ".98....6.",
            "8...6...3", "4..8.3..1", "7...2...6",
            ".6....28.", "...419..5", "....8..79");
        Console.WriteLine(IsValidSudoku(duplicateInBox));   // two 8s in the top-left box

        var empty = Parse(
            ".........", ".........", ".........",
            ".........", ".........", ".........",
            ".........", ".........", ".........");
        Console.WriteLine(IsValidSudoku(empty));

        var duplicateInRow = Parse(
            "55.......", ".........", ".........",
            ".........", ".........", ".........",
            ".........", ".........", ".........");
        Console.WriteLine(IsValidSudoku(duplicateInRow));
    }
}
