**Logic**

Multi-source BFS. Seed the queue with every zero cell at distance 0, then expand outward; the first time a cell is reached is by the shortest path from the nearest zero, because BFS explores in distance order.

Running a separate search from each one-cell would be far slower, and a naive per-cell scan is worse still. Starting from all sources at once computes every answer in a single traversal.

O(rows × cols) time and space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int[][] UpdateMatrix(int[][] matrix)
    {
        int rows = matrix.Length, cols = matrix[0].Length;
        var distance = new int[rows][];
        var queue = new Queue<(int r, int c)>();

        for (int r = 0; r < rows; r++)
        {
            distance[r] = new int[cols];
            for (int c = 0; c < cols; c++)
            {
                if (matrix[r][c] == 0) queue.Enqueue((r, c));   // every zero is a source
                else distance[r][c] = -1;                        // -1 marks "not yet reached"
            }
        }

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (queue.Count > 0)
        {
            var (r, c) = queue.Dequeue();

            for (int d = 0; d < 4; d++)
            {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (distance[nr][nc] != -1) continue;            // already reached, and sooner

                distance[nr][nc] = distance[r][c] + 1;
                queue.Enqueue((nr, nc));
            }
        }

        return distance;
    }

    private static string Render(int[][] m) =>
        string.Join(" / ", Array.ConvertAll(m, r => string.Join(",", r)));

    public static void Main()
    {
        Console.WriteLine(Render(UpdateMatrix(new[] {
            new[] { 0, 0, 0 }, new[] { 0, 1, 0 }, new[] { 0, 0, 0 } })));

        Console.WriteLine(Render(UpdateMatrix(new[] {
            new[] { 0, 0, 0 }, new[] { 0, 1, 0 }, new[] { 1, 1, 1 } })));

        Console.WriteLine(Render(UpdateMatrix(new[] { new[] { 0 } })));
        Console.WriteLine(Render(UpdateMatrix(new[] { new[] { 0, 1, 1, 1, 1 } })));
    }
}
```

