```

**Logic**

A traversal from the starting pixel, recolouring every orthogonally connected cell that shares the original colour. BFS or DFS both work since every step costs the same.

The essential guard is the case where the new colour equals the original. Without it, recoloured cells still match the target colour, so the traversal revisits them forever. An early return handles it.

Recolouring on enqueue rather than on dequeue prevents a cell from entering the queue several times.

O(rows × cols) time.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int[][] FloodFill(int[][] image, int startRow, int startCol, int newColour)
    {
        if (image == null || image.Length == 0) return image;

        int original = image[startRow][startCol];

        // Without this, recoloured cells still match and the traversal never ends.
        if (original == newColour) return image;

        int rows = image.Length, cols = image[0].Length;
        var queue = new Queue<(int r, int c)>();

        image[startRow][startCol] = newColour;
        queue.Enqueue((startRow, startCol));

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (queue.Count > 0)
        {
            var (r, c) = queue.Dequeue();

            for (int d = 0; d < 4; d++)
            {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (image[nr][nc] != original) continue;

                image[nr][nc] = newColour;   // recolour on enqueue
                queue.Enqueue((nr, nc));
            }
        }

        return image;
    }

    private static string Render(int[][] m) =>
        string.Join(" / ", Array.ConvertAll(m, r => string.Join(",", r)));

    public static void Main()
    {
        Console.WriteLine(Render(FloodFill(new[] {
            new[] { 1, 1, 1 }, new[] { 1, 1, 0 }, new[] { 1, 0, 1 } }, 1, 1, 2)));

        // Same colour: must return immediately rather than loop forever.
        Console.WriteLine(Render(FloodFill(new[] {
            new[] { 0, 0 }, new[] { 0, 0 } }, 0, 0, 0)));

        Console.WriteLine(Render(FloodFill(new[] { new[] { 1 } }, 0, 0, 5)));

        // Diagonals do not connect.
        Console.WriteLine(Render(FloodFill(new[] {
            new[] { 1, 0 }, new[] { 0, 1 } }, 0, 0, 3)));
    }
}
```

