**Approach**

A stack holding the leftmost spine. Pushing all left children from a node gives the next in-order element at the top, and advancing means popping and pushing the spine of the right subtree.

**Logic**

Materialising the whole in-order traversal in a list would be O(n) space and would have to be rebuilt if the tree changed. The stack holds only the current path, so space is O(h) — logarithmic for a balanced tree.

Each node is pushed exactly once and popped exactly once across the whole traversal, so although a single `Next` can push a long spine, the amortised cost is O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class BstIterator
{
    private readonly Stack<TreeNode> _stack = new();

    public BstIterator(TreeNode root) => PushLeftSpine(root);

    private void PushLeftSpine(TreeNode node)
    {
        for (; node != null; node = node.Left) _stack.Push(node);
    }

    public bool HasNext => _stack.Count > 0;

    public int Next()
    {
        if (_stack.Count == 0) throw new InvalidOperationException("no more elements");

        var node = _stack.Pop();
        PushLeftSpine(node.Right);    // the next in-order element lives in here

        return node.Val;
    }
}

public class Solution
{
    public static void Main()
    {
        //     7
        //    / \
        //   3   15
        //      /  \
        //     9    20
        var root = new TreeNode(7,
            new TreeNode(3),
            new TreeNode(15, new TreeNode(9), new TreeNode(20)));

        var it = new BstIterator(root);
        var visited = new List<int>();
        while (it.HasNext) visited.Add(it.Next());
        Console.WriteLine(string.Join(",", visited));

        // Interleaving HasNext and Next behaves the same.
        var it2 = new BstIterator(root);
        Console.WriteLine($"{it2.Next()} {it2.HasNext} {it2.Next()} {it2.Next()}");

        var empty = new BstIterator(null);
        Console.WriteLine(empty.HasNext);

        try { empty.Next(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }

        // A left-leaning chain: the spine is the whole tree.
        var chain = new TreeNode(3, new TreeNode(2, new TreeNode(1)));
        var it3 = new BstIterator(chain);
        var chainOrder = new List<int>();
        while (it3.HasNext) chainOrder.Add(it3.Next());
        Console.WriteLine(string.Join(",", chainOrder));
    }
}
```

**Output**

```
3,7,9,15,20
3 True 7 9
False
no more elements
1,2,3
```

**Approach**

Search down to the node, then handle three cases by child count. The only interesting one is a node with two children.

**Logic**

A leaf is removed outright. A node with one child is replaced by that child. A node with two children cannot simply be removed, because its position must be filled by a value that preserves the BST ordering — and exactly two values qualify: the in-order predecessor, the largest in the left subtree, or the in-order successor, the smallest in the right.

Taking the successor, copy its value into the node and then delete the successor from the right subtree. That recursive delete is guaranteed to hit an easier case, because the smallest node in a subtree has no left child.

O(h) time.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static TreeNode DeleteNode(TreeNode root, int key)
    {
        if (root == null) return null;

        if (key < root.Val) { root.Left = DeleteNode(root.Left, key); return root; }
        if (key > root.Val) { root.Right = DeleteNode(root.Right, key); return root; }

        // Found it.
        if (root.Left == null) return root.Right;    // 0 or 1 child
        if (root.Right == null) return root.Left;

        // Two children: take the in-order successor, the smallest on the right.
        var successor = root.Right;
        while (successor.Left != null) successor = successor.Left;

        root.Val = successor.Val;

        // That successor has no left child, so this recursion hits an easy case.
        root.Right = DeleteNode(root.Right, successor.Val);

        return root;
    }

    private static string InOrder(TreeNode node)
    {
        var values = new List<int>();
        void Walk(TreeNode n)
        {
            if (n == null) return;
            Walk(n.Left); values.Add(n.Val); Walk(n.Right);
        }
        Walk(node);
        return values.Count == 0 ? "(empty)" : string.Join(",", values);
    }

    private static TreeNode Build(params int[] values)
    {
        TreeNode root = null;
        foreach (int v in values) root = Insert(root, v);
        return root;
    }

    private static TreeNode Insert(TreeNode node, int value)
    {
        if (node == null) return new TreeNode(value);
        if (value < node.Val) node.Left = Insert(node.Left, value);
        else node.Right = Insert(node.Right, value);
        return node;
    }

    public static void Main()
    {
        Console.WriteLine(InOrder(DeleteNode(Build(5, 3, 6, 2, 4, 7), 3)));   // two children
        Console.WriteLine(InOrder(DeleteNode(Build(5, 3, 6, 2, 4, 7), 2)));   // leaf
        Console.WriteLine(InOrder(DeleteNode(Build(5, 3, 6, 7), 6)));         // one child
        Console.WriteLine(InOrder(DeleteNode(Build(5), 5)));                  // the root
        Console.WriteLine(InOrder(DeleteNode(Build(5, 3), 99)));              // absent
        Console.WriteLine(InOrder(DeleteNode(null, 1)));
    }
}
```

**Output**

```
2,4,5,6,7
3,4,5,6,7
3,5,7
(empty)
3,5
(empty)
```

**Approach**

Prefix sums along the current root-to-node path, with a hash map of counts — exactly the subarray-sum-equals-k technique applied to a tree.

**Logic**

As the traversal descends, maintain the running sum from the root. A path ending at the current node with the target sum exists wherever an ancestor's prefix equals `running - target`, so the count of such prefixes is added.

The step that makes it correct is removing the current node's prefix from the map as the recursion unwinds. Without it, sums leak across sibling branches and paths are counted that do not exist, since a path must be a single downward chain.

O(n) time, O(h) space, against O(n²) for the naive per-node traversal.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int PathSum(TreeNode root, int target)
    {
        // {0: 1} is the empty prefix: it makes a path starting at the root countable.
        var prefixCounts = new Dictionary<long, int> { [0] = 1 };
        return Count(root, 0, target, prefixCounts);
    }

    private static int Count(TreeNode node, long running, int target,
                             Dictionary<long, int> prefixCounts)
    {
        if (node == null) return 0;

        running += node.Val;

        // Every ancestor prefix equal to running - target closes a qualifying path.
        prefixCounts.TryGetValue(running - target, out int found);

        prefixCounts[running] = prefixCounts.GetValueOrDefault(running) + 1;

        found += Count(node.Left, running, target, prefixCounts);
        found += Count(node.Right, running, target, prefixCounts);

        // Unwind: this prefix is not an ancestor of a sibling branch.
        prefixCounts[running]--;

        return found;
    }

    public static void Main()
    {
        //        10
        //       /  \
        //      5   -3
        //     / \    \
        //    3   2    11
        //   / \   \
        //  3  -2   1
        var root = new TreeNode(10,
            new TreeNode(5,
                new TreeNode(3, new TreeNode(3), new TreeNode(-2)),
                new TreeNode(2, null, new TreeNode(1))),
            new TreeNode(-3, null, new TreeNode(11)));

        Console.WriteLine(PathSum(root, 8));

        Console.WriteLine(PathSum(new TreeNode(1), 1));
        Console.WriteLine(PathSum(null, 0));
        Console.WriteLine(PathSum(new TreeNode(0, new TreeNode(0)), 0));   // zeros
        Console.WriteLine(PathSum(new TreeNode(1, new TreeNode(2)), 3));
        Console.WriteLine(PathSum(new TreeNode(5, new TreeNode(-3)), 2));
    }
}
```

**Output**

```
3
1
0
3
1
1
```

**Approach**

Post-order traversal returning two values per node: the best total if this node is taken, and the best if it is not. The parent combines them.

**Logic**

If a node is robbed, its children cannot be, so the total is its value plus both children's not-robbed totals. If it is not robbed, each child is independently free to be robbed or not, so take the better of each child's two options.

Returning a pair rather than a single number is what avoids recomputation. A version returning only the best would need to re-examine grandchildren, making it exponential.

O(n) time, O(h) stack space.

**Program**

```csharp
using System;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int Rob(TreeNode root)
    {
        var (robbed, skipped) = Best(root);
        return Math.Max(robbed, skipped);
    }

    // Returns (best if this node IS robbed, best if it is NOT).
    private static (int Robbed, int Skipped) Best(TreeNode node)
    {
        if (node == null) return (0, 0);

        var left = Best(node.Left);
        var right = Best(node.Right);

        // Robbing here forbids both children.
        int robbed = node.Val + left.Skipped + right.Skipped;

        // Skipping here leaves each child free to choose independently.
        int skipped = Math.Max(left.Robbed, left.Skipped)
                    + Math.Max(right.Robbed, right.Skipped);

        return (robbed, skipped);
    }

    public static void Main()
    {
        //    3
        //   / \
        //  2   3
        //   \    \
        //    3    1        best is 3 + 3 + 1 = 7
        Console.WriteLine(Rob(new TreeNode(3,
            new TreeNode(2, null, new TreeNode(3)),
            new TreeNode(3, null, new TreeNode(1)))));

        //      3
        //     / \
        //    4   5
        //   / \   \
        //  1   3   1      best is 4 + 5 = 9
        Console.WriteLine(Rob(new TreeNode(3,
            new TreeNode(4, new TreeNode(1), new TreeNode(3)),
            new TreeNode(5, null, new TreeNode(1)))));

        Console.WriteLine(Rob(new TreeNode(1)));
        Console.WriteLine(Rob(null));
        Console.WriteLine(Rob(new TreeNode(0, new TreeNode(0))));
        Console.WriteLine(Rob(new TreeNode(2, new TreeNode(1), new TreeNode(3))));
    }
}
```

