9
1
0
0
4
```

**Approach**

A binary tree has no parent pointers, so distance can only travel downward. Build a parent map first, which turns the tree into an undirected graph, then BFS from the target.

**Logic**

One pass records each node's parent. After that, every node has up to three neighbours: left child, right child and parent. BFS outward level by level, and the nodes at level k are the answer.

A visited set is essential, since with parent links the graph has cycles in the traversal sense — stepping to a parent and back would loop forever.

O(n) time and space.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static IList<int> DistanceK(TreeNode root, TreeNode target, int k)
    {
        var parents = new Dictionary<TreeNode, TreeNode>();
        MapParents(root, null, parents);

        var visited = new HashSet<TreeNode>();
        var queue = new Queue<TreeNode>();

        queue.Enqueue(target);
        visited.Add(target);

        int distance = 0;

        while (queue.Count > 0)
        {
            if (distance == k)
                return queue.Select(n => n.Val).ToList();

            int levelSize = queue.Count;

            for (int i = 0; i < levelSize; i++)
            {
                var node = queue.Dequeue();

                // Three possible neighbours now that parents are known.
                foreach (var next in new[] { node.Left, node.Right, parents.GetValueOrDefault(node) })
                    if (next != null && visited.Add(next)) queue.Enqueue(next);
            }

            distance++;
        }

        return new List<int>();
    }

    private static void MapParents(TreeNode node, TreeNode parent,
                                   Dictionary<TreeNode, TreeNode> parents)
    {
        if (node == null) return;

        parents[node] = parent;
        MapParents(node.Left, node, parents);
        MapParents(node.Right, node, parents);
    }

    private static string Show(IList<int> r)
    {
        if (r.Count == 0) return "(none)";
        var copy = new List<int>(r);
        copy.Sort();
        return string.Join(",", copy);
    }

    public static void Main()
    {
        //        3
        //       / \
        //      5   1
        //     / \  / \
        //    6  2 0   8
        //      / \
        //     7   4
        var seven = new TreeNode(7);
        var four = new TreeNode(4);
        var two = new TreeNode(2, seven, four);
        var five = new TreeNode(5, new TreeNode(6), two);
        var one = new TreeNode(1, new TreeNode(0), new TreeNode(8));
        var root = new TreeNode(3, five, one);

        Console.WriteLine(Show(DistanceK(root, five, 2)));   // upward and downward
        Console.WriteLine(Show(DistanceK(root, five, 0)));   // the node itself
        Console.WriteLine(Show(DistanceK(root, five, 1)));
        Console.WriteLine(Show(DistanceK(root, seven, 3)));
        Console.WriteLine(Show(DistanceK(root, root, 99)));  // beyond the tree
        Console.WriteLine(Show(DistanceK(root, root, 1)));
    }
}
```

