```

**Approach**

Assign each node a column, decrementing going left and incrementing going right, then group by column. The ordering rule within a column is what makes this harder than it looks.

**Logic**

Nodes are ordered by column first, then by row, and — critically — by *value* when two nodes share both. That last rule means a plain BFS insertion order is not sufficient; the entries must be sorted.

Collect every node as a (column, row, value) triple in one traversal, then sort by all three keys and group. Sorting explicitly is clearer than trying to arrange the traversal to produce the order naturally.

O(n log n) for the sort.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static IList<IList<int>> VerticalTraversal(TreeNode root)
    {
        var entries = new List<(int Column, int Row, int Value)>();
        Collect(root, 0, 0, entries);

        // Column, then row, then VALUE - the third key is the one people miss.
        return entries
            .OrderBy(e => e.Column).ThenBy(e => e.Row).ThenBy(e => e.Value)
            .GroupBy(e => e.Column)
            .Select(g => (IList<int>)g.Select(e => e.Value).ToList())
            .ToList();
    }

    private static void Collect(TreeNode node, int column, int row,
                                List<(int, int, int)> entries)
    {
        if (node == null) return;

        entries.Add((column, row, node.Val));
        Collect(node.Left, column - 1, row + 1, entries);
        Collect(node.Right, column + 1, row + 1, entries);
    }

    private static string Render(IList<IList<int>> r) =>
        r.Count == 0 ? "(empty)" : string.Join(" ", r.Select(c => "[" + string.Join(",", c) + "]"));

    public static void Main()
    {
        //     3
        //    / \
        //   9   20
        //      /  \
        //     15   7
        Console.WriteLine(Render(VerticalTraversal(new TreeNode(3,
            new TreeNode(9),
            new TreeNode(20, new TreeNode(15), new TreeNode(7))))));

        // Two nodes share a column AND a row: 5 and 6 must be ordered by value.
        //      1
        //     / \
        //    2   3
        //   / \ / \
        //  4  6 5  7
        Console.WriteLine(Render(VerticalTraversal(new TreeNode(1,
            new TreeNode(2, new TreeNode(4), new TreeNode(6)),
            new TreeNode(3, new TreeNode(5), new TreeNode(7))))));

        Console.WriteLine(Render(VerticalTraversal(new TreeNode(1))));
        Console.WriteLine(Render(VerticalTraversal(null)));
    }
}
```

