**Approach**

Reverse in-order traversal — right, node, left — visits values in descending order, so a running total accumulated along the way is exactly the sum of everything greater.

**Logic**

A normal in-order walk gives ascending order. Reversing it gives descending, which means every node is visited after all larger values and before all smaller ones. Adding the node's value to a running sum and then writing the sum back gives the required result in one pass.

The order of those two operations matters: the node's own value must be added to the total before the total is written, because the definition is sum of all greater values *plus itself* in the usual phrasing of this problem.

O(n) time, O(h) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static TreeNode ConvertBst(TreeNode root)
    {
        int running = 0;
        Walk(root, ref running);
        return root;
    }

    // Right, node, left: descending order, so everything larger is seen first.
    private static void Walk(TreeNode node, ref int running)
    {
        if (node == null) return;

        Walk(node.Right, ref running);

        running += node.Val;
        node.Val = running;

        Walk(node.Left, ref running);
    }

    private static string InOrder(TreeNode node)
    {
        var values = new List<int>();
        void Go(TreeNode n) { if (n == null) return; Go(n.Left); values.Add(n.Val); Go(n.Right); }
        Go(node);
        return values.Count == 0 ? "(empty)" : string.Join(",", values);
    }

    private static TreeNode Build(params int[] values)
    {
        TreeNode root = null;
        foreach (int v in values) root = Insert(root, v);
        return root;
    }

    private static TreeNode Insert(TreeNode n, int v)
    {
        if (n == null) return new TreeNode(v);
        if (v < n.Val) n.Left = Insert(n.Left, v); else n.Right = Insert(n.Right, v);
        return n;
    }

    public static void Main()
    {
        // 1,2,3,4,5 becomes 15,14,12,9,5
        Console.WriteLine(InOrder(ConvertBst(Build(3, 2, 4, 1, 5))));

        Console.WriteLine(InOrder(ConvertBst(Build(1))));
        Console.WriteLine(InOrder(ConvertBst(null)));
        Console.WriteLine(InOrder(ConvertBst(Build(2, 1))));
        Console.WriteLine(InOrder(ConvertBst(Build(1, 2, 3))));   // right-leaning chain
        Console.WriteLine(InOrder(ConvertBst(Build(0, -1, 1))));  // negatives: -1 becomes 0, 0 becomes 1, 1 stays 1
    }
}
```

**Output**

```
