**Approach**

A weighted graph. Each equation `a / b = k` is an edge from a to b with weight k and from b to a with weight 1/k. A query is then a path search, multiplying weights along the way.

**Logic**

DFS from the numerator to the denominator, carrying the product so far. Reaching the target gives the answer; exhausting the search means the two are not connected and the answer is -1.

Two cases need care. A variable divided by itself is 1, but only if the variable appears in the input at all — an unknown variable has no answer even for `x / x`. And unconnected components mean no path exists, which is different from a path of weight zero.

O(queries × edges).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static double[] CalcEquation(IList<IList<string>> equations, double[] values,
                                        IList<IList<string>> queries)
    {
        var graph = new Dictionary<string, List<(string To, double Weight)>>();

        for (int i = 0; i < equations.Count; i++)
        {
            string a = equations[i][0], b = equations[i][1];

            graph.TryAdd(a, new List<(string, double)>());
            graph.TryAdd(b, new List<(string, double)>());

            graph[a].Add((b, values[i]));          // a / b = k
            graph[b].Add((a, 1.0 / values[i]));    // so b / a = 1/k
        }

        var results = new double[queries.Count];

        for (int i = 0; i < queries.Count; i++)
        {
            string from = queries[i][0], to = queries[i][1];

            // An unknown variable has no answer, even for x / x.
            if (!graph.ContainsKey(from) || !graph.ContainsKey(to)) { results[i] = -1; continue; }

            results[i] = Search(graph, from, to, 1.0, new HashSet<string>());
        }

        return results;
    }

    private static double Search(Dictionary<string, List<(string To, double Weight)>> graph,
                                 string current, string target, double product,
                                 HashSet<string> visited)
    {
        if (current == target) return product;
        if (!visited.Add(current)) return -1;

        foreach (var (next, weight) in graph[current])
        {
            double result = Search(graph, next, target, product * weight, visited);
            if (result > 0) return result;
        }

        return -1;
    }

    public static void Main()
    {
        var equations = new List<IList<string>>
        {
            new List<string> { "a", "b" },
            new List<string> { "b", "c" },
        };
        var values = new[] { 2.0, 3.0 };

        var queries = new List<IList<string>>
        {
            new List<string> { "a", "c" },   // 2 * 3
            new List<string> { "b", "a" },   // 1/2
            new List<string> { "a", "e" },   // unknown variable
            new List<string> { "a", "a" },   // known, so 1
            new List<string> { "x", "x" },   // unknown, so -1
            new List<string> { "c", "a" },
        };

        foreach (double r in CalcEquation(equations, values, queries))
            Console.WriteLine(Math.Round(r, 5));
    }
}
```

