JFK->ATL->JFK->SFO->ATL->SFO
JFK->NRT->JFK->KUL
JFK->AAA
```

**Approach**

Tarjan's bridge-finding algorithm. A DFS assigns each node a discovery time and computes the earliest discovery time reachable from its subtree via a back edge. An edge is a bridge when the child's reachable minimum is strictly greater than the parent's discovery time.

**Logic**

If a child's subtree can reach no node discovered before the parent, then removing the edge disconnects that subtree — so the edge is critical.

The parent edge must be excluded when computing the minimum, or every tree edge would look like a back edge to its own parent and no bridge would ever be found.

O(V + E) time.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static IList<IList<int>> CriticalConnections(int n, IList<IList<int>> connections)
    {
        var adjacency = new List<int>[n];
        for (int i = 0; i < n; i++) adjacency[i] = new List<int>();

        foreach (var c in connections)
        {
            adjacency[c[0]].Add(c[1]);
            adjacency[c[1]].Add(c[0]);
        }

        var discovered = new int[n];
        var lowest = new int[n];
        Array.Fill(discovered, -1);

        var bridges = new List<IList<int>>();
        int timer = 0;

        void Dfs(int node, int parent)
        {
            discovered[node] = lowest[node] = timer++;

            foreach (int next in adjacency[node])
            {
                if (next == parent) continue;    // never count the edge we arrived on

                if (discovered[next] == -1)
                {
                    Dfs(next, node);
                    lowest[node] = Math.Min(lowest[node], lowest[next]);

                    // The subtree cannot reach back past this node: the edge is critical.
                    if (lowest[next] > discovered[node])
                        bridges.Add(new List<int> { node, next });
                }
                else
                {
                    lowest[node] = Math.Min(lowest[node], discovered[next]);
                }
            }
        }

        for (int i = 0; i < n; i++)
            if (discovered[i] == -1) Dfs(i, -1);

        return bridges;
    }

    private static IList<IList<int>> Edges(params int[][] pairs) =>
        pairs.Select(p => (IList<int>)new List<int> { p[0], p[1] }).ToList();

    private static string Show(IList<IList<int>> r)
    {
        if (r.Count == 0) return "(none)";
        var rendered = r.Select(e => $"[{Math.Min(e[0], e[1])},{Math.Max(e[0], e[1])}]").ToList();
        rendered.Sort(StringComparer.Ordinal);
        return string.Join(" ", rendered);
    }

    public static void Main()
    {
        Console.WriteLine(Show(CriticalConnections(4, Edges(
            new[] { 0, 1 }, new[] { 1, 2 }, new[] { 2, 0 }, new[] { 1, 3 }))));

        // A cycle has no bridges at all.
        Console.WriteLine(Show(CriticalConnections(3, Edges(
            new[] { 0, 1 }, new[] { 1, 2 }, new[] { 2, 0 }))));

        // A path: every edge is critical.
        Console.WriteLine(Show(CriticalConnections(3, Edges(
            new[] { 0, 1 }, new[] { 1, 2 }))));

        Console.WriteLine(Show(CriticalConnections(2, Edges(new[] { 0, 1 }))));
        Console.WriteLine(Show(CriticalConnections(1, Edges())));
    }
}
```

