**Approach**

Sort by length, then for each word try removing each character and look up the result. The best chain ending at a word is one more than the best ending at any of its predecessors.

**Logic**

Sorting by length guarantees that when a word is processed, every possible predecessor — which must be exactly one character shorter — has already been solved.

Generating the predecessors by deletion is the efficient direction: a word of length L has L predecessors, which is far fewer than comparing against every other word. That turns an O(n²·L) comparison into O(n·L²) with dictionary lookups.

O(n log n + n·L²).

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int LongestStrChain(string[] words)
    {
        if (words == null || words.Length == 0) return 0;

        // Shortest first, so every predecessor is solved before its successors.
        var sorted = words.OrderBy(w => w.Length).ToArray();

        var best = new Dictionary<string, int>();
        int longest = 1;

        foreach (string word in sorted)
        {
            int chain = 1;

            // A predecessor is this word with exactly one character removed.
            for (int i = 0; i < word.Length; i++)
            {
                string predecessor = word.Remove(i, 1);

                if (best.TryGetValue(predecessor, out int previous))
                    chain = Math.Max(chain, previous + 1);
            }

            best[word] = Math.Max(best.GetValueOrDefault(word), chain);
            longest = Math.Max(longest, best[word]);
        }

        return longest;
    }

    public static void Main()
    {
        Console.WriteLine(LongestStrChain(new[] { "a", "b", "ba", "bca", "bda", "bdca" }));
        Console.WriteLine(LongestStrChain(new[] { "xbc", "pcxbcf", "xb", "cxbc", "pcxbc" }));
        Console.WriteLine(LongestStrChain(new[] { "abcd", "dbqca" }));   // not a chain
        Console.WriteLine(LongestStrChain(new[] { "a" }));
        Console.WriteLine(LongestStrChain(new[] { "a", "ab", "abc", "abcd" }));
        Console.WriteLine(LongestStrChain(Array.Empty<string>()));
    }
}
```

