**Approach**

Row-by-row DP. The cheapest way to reach a cell is its own value plus the cheapest of the three cells above it — directly above, above-left, and above-right.

**Logic**

Processing top to bottom means the previous row is always complete when the current one is computed. Edge columns have only two predecessors rather than three, which the bounds checks handle.

The answer is the minimum across the final row, not the last cell, because the path may end anywhere along the bottom.

O(n²) time, O(n) space with a rolling row.

**Program**

```csharp
using System;
using System.Linq;

public class Solution
{
    public static int MinFallingPathSum(int[][] matrix)
    {
        if (matrix == null || matrix.Length == 0) return 0;

        int n = matrix.Length, m = matrix[0].Length;
        var previous = (int[])matrix[0].Clone();

        for (int r = 1; r < n; r++)
        {
            var current = new int[m];

            for (int c = 0; c < m; c++)
            {
                int best = previous[c];
                if (c > 0) best = Math.Min(best, previous[c - 1]);
                if (c < m - 1) best = Math.Min(best, previous[c + 1]);

                current[c] = matrix[r][c] + best;
            }

            previous = current;
        }

        // The path may end anywhere along the bottom row.
        return previous.Min();
    }

    private static int[][] Grid(params int[][] rows) => rows;

    public static void Main()
    {
        Console.WriteLine(MinFallingPathSum(Grid(
            new[] { 2, 1, 3 }, new[] { 6, 5, 4 }, new[] { 7, 8, 9 })));

        Console.WriteLine(MinFallingPathSum(Grid(
            new[] { -19, 57 }, new[] { -40, -5 })));

        Console.WriteLine(MinFallingPathSum(Grid(new[] { -48 })));
        Console.WriteLine(MinFallingPathSum(Grid(
            new[] { 1, 2, 3 }, new[] { 4, 5, 6 }, new[] { 7, 8, 9 })));
        Console.WriteLine(MinFallingPathSum(Grid(
            new[] { 100, 1 }, new[] { 1, 100 })));       // must move diagonally
    }
}
```

