**Logic**

A list plus a current index, rather than two stacks. The list holds the whole history in order and the index marks where you are, so back and forward are just index moves and are O(1).

The rule that defines browser behaviour: visiting a new page from anywhere but the end discards the entire forward history. That is why a plain stack pair is awkward and an index into a list is natural, since truncation is a single operation.

Back and forward take a step count and must clamp rather than throw when the requested number of steps exceeds what is available.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class BrowserHistory
{
    private readonly List<string> _pages = new();
    private int _current;

    public BrowserHistory(string homepage)
    {
        _pages.Add(homepage);
        _current = 0;
    }

    public void Visit(string url)
    {
        // Everything ahead of the current page is discarded.
        if (_current < _pages.Count - 1)
            _pages.RemoveRange(_current + 1, _pages.Count - _current - 1);

        _pages.Add(url);
        _current = _pages.Count - 1;
    }

    public string Back(int steps)
    {
        _current = Math.Max(0, _current - steps);   // clamp, do not throw
        return _pages[_current];
    }

    public string Forward(int steps)
    {
        _current = Math.Min(_pages.Count - 1, _current + steps);
        return _pages[_current];
    }

    public string Current => _pages[_current];
}

public class Solution
{
    public static void Main()
    {
        var h = new BrowserHistory("home");

        h.Visit("a");
        h.Visit("b");
        h.Visit("c");

        Console.WriteLine(h.Back(1));       // b
        Console.WriteLine(h.Back(1));       // a
        Console.WriteLine(h.Forward(1));    // b

        h.Visit("d");                       // discards c
        Console.WriteLine(h.Forward(2));    // nothing ahead: stays on d

        Console.WriteLine(h.Back(7));       // clamps at the homepage
        Console.WriteLine(h.Current);
    }
}
