a
b
d
home
home
```

**Logic**

Two maps. One tracks passengers currently travelling, keyed by card id, holding their entry station and time. The other accumulates, per station pair, the total time and the number of journeys.

Storing the running total and count rather than a list of times keeps memory constant per route and makes the average an O(1) division. Keeping the individual times would grow without bound and buy nothing unless percentiles were needed.

All operations are O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class UndergroundSystem
{
    // Card id -> where and when they entered.
    private readonly Dictionary<int, (string Station, int Time)> _travelling = new();

    // "from->to" -> running total and count. Not a list of times: constant memory.
    private readonly Dictionary<string, (long Total, int Count)> _routes = new();

    public void CheckIn(int cardId, string station, int time)
    {
        if (_travelling.ContainsKey(cardId))
            throw new InvalidOperationException($"card {cardId} is already travelling");

        _travelling[cardId] = (station, time);
    }

    public void CheckOut(int cardId, string station, int time)
    {
        if (!_travelling.TryGetValue(cardId, out var start))
            throw new InvalidOperationException($"card {cardId} never checked in");

        _travelling.Remove(cardId);

        string route = start.Station + "->" + station;
        int duration = time - start.Time;

        var current = _routes.TryGetValue(route, out var r) ? r : (0L, 0);
        _routes[route] = (current.Item1 + duration, current.Item2 + 1);
    }

    public double GetAverageTime(string from, string to)
    {
        string route = from + "->" + to;

        if (!_routes.TryGetValue(route, out var r) || r.Count == 0)
            throw new KeyNotFoundException($"no journeys recorded for {route}");

        return (double)r.Total / r.Count;
    }
}

public class Solution
{
    public static void Main()
    {
        var system = new UndergroundSystem();

        system.CheckIn(45, "Leyton", 3);
        system.CheckOut(45, "Waterloo", 15);          // 12

        system.CheckIn(27, "Leyton", 10);
        system.CheckOut(27, "Waterloo", 20);          // 10

        Console.WriteLine(system.GetAverageTime("Leyton", "Waterloo"));   // 11

        system.CheckIn(10, "Leyton", 24);
        system.CheckOut(10, "Waterloo", 38);          // 14
        Console.WriteLine(system.GetAverageTime("Leyton", "Waterloo"));   // 12

        // Direction matters: the reverse route is separate.
        try { system.GetAverageTime("Waterloo", "Leyton"); }
        catch (KeyNotFoundException) { Console.WriteLine("no data for the reverse route"); }

        try { system.CheckOut(99, "Leyton", 5); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
