**Logic**

The duplicate-free version maps each value to a single index. With duplicates, a value occupies several positions, so the map must hold a *set* of indices per value.

Removal still uses the swap-with-last trick, but now three index sets need care: remove the doomed index from the target's set, move the last element into the hole, and update the moved element's set by removing its old index and adding the new one.

The subtle case is when the element being removed *is* the last one, where the swap is a no-op and doing the updates in the wrong order corrupts the set.

All operations remain O(1) on average.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class RandomisedCollection
{
    private readonly List<int> _items = new();
    private readonly Dictionary<int, HashSet<int>> _indices = new();
    private readonly Random _rng;

    public RandomisedCollection(int seed = 7) => _rng = new Random(seed);

    // Returns true if the value was not already present.
    public bool Insert(int value)
    {
        if (!_indices.TryGetValue(value, out var set))
            _indices[value] = set = new HashSet<int>();

        bool wasAbsent = set.Count == 0;

        set.Add(_items.Count);
        _items.Add(value);

        return wasAbsent;
    }

    public bool Remove(int value)
    {
        if (!_indices.TryGetValue(value, out var set) || set.Count == 0) return false;

        int index = set.First();          // any occurrence will do
        set.Remove(index);

        int lastIndex = _items.Count - 1;

        // Only swap when the victim is not already last; otherwise the set
        // updates below would re-add an index that is about to disappear.
        if (index != lastIndex)
        {
            int lastValue = _items[lastIndex];
            _items[index] = lastValue;

            _indices[lastValue].Remove(lastIndex);
            _indices[lastValue].Add(index);
        }

        _items.RemoveAt(lastIndex);
        if (set.Count == 0) _indices.Remove(value);

        return true;
    }

    public int GetRandom()
    {
        if (_items.Count == 0) throw new InvalidOperationException("collection is empty");
        return _items[_rng.Next(_items.Count)];
    }

    public int Count => _items.Count;
}

public static class SetExtensions
{
    public static int First(this HashSet<int> set)
    {
        foreach (int v in set) return v;
        throw new InvalidOperationException("empty set");
    }
}

public class Solution
{
    public static void Main()
    {
        var c = new RandomisedCollection();

        Console.WriteLine(c.Insert(1));    // newly present
        Console.WriteLine(c.Insert(1));    // duplicate
        Console.WriteLine(c.Insert(2));
        Console.WriteLine(c.Count);

        Console.WriteLine(c.Remove(1));    // removes one of the two 1s
        Console.WriteLine(c.Count);
        Console.WriteLine(c.Remove(1));    // the other one
        Console.WriteLine(c.Remove(1));    // none left

        int drawn = c.GetRandom();
        Console.WriteLine(drawn == 2);
    }
}
```

