**Logic**

A fixed array with a head index and a count. Deriving the tail from head plus count means the two indices can never drift out of sync, and the full-versus-empty ambiguity disappears because the count distinguishes them.

Inserting at the front moves the head backwards with wraparound, which needs the non-negative modulo idiom since subtracting one from index zero must land on the last slot rather than on minus one.

All operations are O(1) with no allocation after construction.

**Program**

```csharp
using System;

public class CircularDeque
{
    private readonly int[] _items;
    private int _head;
    private int _count;

    public CircularDeque(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _items = new int[capacity];
    }

    public bool IsFull => _count == _items.Length;
    public bool IsEmpty => _count == 0;
    public int Count => _count;

    public bool PushFront(int value)
    {
        if (IsFull) return false;

        // Step back with wraparound: -1 must land on the last slot, not on -1.
        _head = (_head - 1 + _items.Length) % _items.Length;
        _items[_head] = value;
        _count++;
        return true;
    }

    public bool PushBack(int value)
    {
        if (IsFull) return false;

        _items[(_head + _count) % _items.Length] = value;   // tail derived, never stored
        _count++;
        return true;
    }

    public bool PopFront(out int value)
    {
        if (IsEmpty) { value = default; return false; }

        value = _items[_head];
        _head = (_head + 1) % _items.Length;
        _count--;
        return true;
    }

    public bool PopBack(out int value)
    {
        if (IsEmpty) { value = default; return false; }

        value = _items[(_head + _count - 1) % _items.Length];
        _count--;
        return true;
    }

    public bool PeekFront(out int value)
    {
        if (IsEmpty) { value = default; return false; }
        value = _items[_head];
        return true;
    }
}

public class Solution
{
    public static void Main()
    {
        var d = new CircularDeque(3);

        Console.WriteLine(d.PushBack(1));
        Console.WriteLine(d.PushBack(2));
        Console.WriteLine(d.PushFront(0));    // wraps the head backwards
        Console.WriteLine(d.PushBack(9));     // full

        d.PeekFront(out int front);
        Console.WriteLine(front);

        d.PopBack(out int back);
        Console.WriteLine(back);

        Console.WriteLine(d.PushBack(3));     // space freed
        Console.WriteLine(d.Count);

        var empty = new CircularDeque(1);
        Console.WriteLine(empty.PopFront(out _));
    }
}
