**Logic**

Each key holds a list of versions, appended in timestamp order. A get asks for the value at or before a given time, which is a binary search for the rightmost entry not exceeding the target.

Because writes arrive with non-decreasing timestamps, the list is already sorted and needs no insertion cost beyond the append. That assumption is what makes set O(1) and get O(log n) rather than requiring a sorted structure.

The binary search is an upper bound minus one: find the first entry strictly after the target, and step back.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TimeMap
{
    // Key -> versions, appended in non-decreasing timestamp order.
    private readonly Dictionary<string, List<(int Time, string Value)>> _store = new();

    public void Set(string key, string value, int timestamp)
    {
        if (!_store.TryGetValue(key, out var versions))
            _store[key] = versions = new List<(int, string)>();

        versions.Add((timestamp, value));   // already ordered, so a plain append
    }

    public string Get(string key, string timestamp)
    {
        throw new NotSupportedException("use the int overload");
    }

    public string Get(string key, int timestamp)
    {
        if (!_store.TryGetValue(key, out var versions)) return "";

        // Rightmost entry with Time <= timestamp.
        int low = 0, high = versions.Count;

        while (low < high)
        {
            int mid = low + (high - low) / 2;

            if (versions[mid].Time <= timestamp) low = mid + 1;   // look further right
            else high = mid;
        }

        return low == 0 ? "" : versions[low - 1].Value;           // step back one
    }
}

public class Solution
{
    public static void Main()
    {
        var map = new TimeMap();

        map.Set("foo", "bar", 1);
        Console.WriteLine(map.Get("foo", 1));
        Console.WriteLine(map.Get("foo", 3));      // nothing newer, so still bar

        map.Set("foo", "bar2", 4);
        Console.WriteLine(map.Get("foo", 4));
        Console.WriteLine(map.Get("foo", 5));

        Console.WriteLine($"[{map.Get("foo", 0)}]");        // before any write
        Console.WriteLine($"[{map.Get("missing", 1)}]");    // unknown key
    }
}
```

