[]
[]
```

**Logic**

A map from message to the earliest timestamp at which it may next print. On arrival, if the current time is at or past that value, print and set the next allowed time; otherwise suppress.

Storing the *next allowed* time rather than the last printed time removes an addition from the hot path and makes the comparison a single check.

O(1) per message, but the map grows without bound, which is the real design issue and the thing an interviewer will push on.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Logger
{
    private const int CooldownSeconds = 10;

    // Message -> the earliest time it may print again.
    private readonly Dictionary<string, int> _nextAllowed = new();

    public bool ShouldPrint(int timestamp, string message)
    {
        if (_nextAllowed.TryGetValue(message, out int allowedAt) && timestamp < allowedAt)
            return false;

        _nextAllowed[message] = timestamp + CooldownSeconds;
        return true;
    }

    // Optional sweep: discard entries whose cooldown has fully expired.
    public int Prune(int timestamp)
    {
        var stale = new List<string>();

        foreach (var (message, allowedAt) in _nextAllowed)
            if (allowedAt <= timestamp) stale.Add(message);

        foreach (string m in stale) _nextAllowed.Remove(m);
        return stale.Count;
    }

    public int TrackedCount => _nextAllowed.Count;
}

public class Solution
{
    public static void Main()
    {
        var logger = new Logger();

        Console.WriteLine(logger.ShouldPrint(1, "foo"));    // first time
        Console.WriteLine(logger.ShouldPrint(2, "bar"));
        Console.WriteLine(logger.ShouldPrint(3, "foo"));    // still in cooldown
        Console.WriteLine(logger.ShouldPrint(8, "bar"));
        Console.WriteLine(logger.ShouldPrint(10, "foo"));   // one second early
        Console.WriteLine(logger.ShouldPrint(11, "foo"));   // exactly 10 seconds later

        Console.WriteLine(logger.TrackedCount);
        Console.WriteLine(logger.Prune(100));               // both expired
        Console.WriteLine(logger.TrackedCount);
    }
}
