**Approach**

Binary search for the *left edge of the answer window* rather than for the target. The answer is always k contiguous elements, so you only need where the window starts.

**Logic**

The key insight is that the result is contiguous: because the array is sorted, the k closest values form a window. So the search space is the possible left indices, from 0 to n-k.

The comparison asks whether the element just past the window is closer than the element at the left edge. If so, the window must slide right. Using subtraction rather than absolute values is safe because the array is sorted.

O(log(n-k) + k).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<int> FindClosestElements(int[] arr, int k, int target)
    {
        int lo = 0, hi = arr.Length - k;   // possible LEFT edges of the window

        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;

            // Is the element just past the window closer than the one at the left edge?
            // Sorted order makes plain subtraction safe here.
            if (target - arr[mid] > arr[mid + k] - target) lo = mid + 1;
            else hi = mid;
        }

        var result = new List<int>(k);
        for (int i = lo; i < lo + k; i++) result.Add(arr[i]);
        return result;
    }

    private static void Show(IList<int> values) => Console.WriteLine(string.Join(",", values));

    public static void Main()
    {
        Show(FindClosestElements(new[] { 1, 2, 3, 4, 5 }, 4, 3));
        Show(FindClosestElements(new[] { 1, 2, 3, 4, 5 }, 4, -1));
        Show(FindClosestElements(new[] { 1, 2, 3, 4, 5 }, 4, 9));
        Show(FindClosestElements(new[] { 1, 1, 1, 10, 10, 10 }, 1, 9));
        Show(FindClosestElements(new[] { 1, 2, 3, 4, 5 }, 5, 3));   // whole array

        // A tie prefers the SMALLER value, so 2 wins over 4.
        Show(FindClosestElements(new[] { 1, 2, 3, 4, 5 }, 1, 3));
        Show(FindClosestElements(new[] { 2, 4 }, 1, 3));
    }
}
```

