**Logic**

"Exactly k" is awkward for a sliding window, because the window cannot decide when to shrink: having fewer than k distinct values is not invalid, it is merely incomplete. "At most k" is easy, since the shrink condition is unambiguous.

So compute `atMost(k) - atMost(k - 1)`, which is exactly k by subtraction. Each helper is a standard elastic window in O(n), giving O(n) overall.

That reformulation is the entire trick, and it recurs across counting problems.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int SubarraysWithKDistinct(int[] nums, int k)
    {
        if (nums == null || k <= 0) return 0;

        // exactly(k) = atMost(k) - atMost(k-1)
        return AtMost(nums, k) - AtMost(nums, k - 1);
    }

    // Number of subarrays containing at most k distinct values.
    private static int AtMost(int[] nums, int k)
    {
        if (k <= 0) return 0;

        var counts = new Dictionary<int, int>();
        int left = 0, total = 0;

        for (int right = 0; right < nums.Length; right++)
        {
            counts[nums[right]] = counts.TryGetValue(nums[right], out int c) ? c + 1 : 1;

            while (counts.Count > k)
            {
                int leaving = nums[left++];
                if (--counts[leaving] == 0) counts.Remove(leaving);
            }

            // Every subarray ending at right and starting anywhere in [left..right].
            total += right - left + 1;
        }

        return total;
    }

    public static void Main()
    {
        Console.WriteLine(SubarraysWithKDistinct(new[] { 1, 2, 1, 2, 3 }, 2));
        Console.WriteLine(SubarraysWithKDistinct(new[] { 1, 2, 1, 3, 4 }, 3));
        Console.WriteLine(SubarraysWithKDistinct(new[] { 1, 1, 1 }, 1));
        Console.WriteLine(SubarraysWithKDistinct(new[] { 1, 2, 3 }, 1));
        Console.WriteLine(SubarraysWithKDistinct(new[] { 1 }, 2));      // impossible
        Console.WriteLine(SubarraysWithKDistinct(new[] { 1, 2 }, 2));
    }
}
