**Approach**

Two parallel Kadane runs: one tracking the best subarray ending here with no deletion, and one with exactly one deletion used.

**Logic**

The deleted-state recurrence is the interesting one. A best-ending-here subarray that has used its deletion either deleted the current element — leaving the no-deletion best from the previous position — or deleted something earlier and now extends by the current element.

The subarray must remain non-empty after the deletion, which is why the deleted state starts as impossible rather than zero, and why an all-negative array returns its largest element rather than zero.

O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int MaximumSum(int[] arr)
    {
        if (arr == null || arr.Length == 0) return 0;

        int keepAll = arr[0];              // best ending here, nothing deleted
        int deletedOne = int.MinValue;     // best ending here, one deletion used
        int best = arr[0];

        for (int i = 1; i < arr.Length; i++)
        {
            // Either delete arr[i] (take the previous undeleted best),
            // or extend a run that already used its deletion.
            int nextDeleted = Math.Max(keepAll,
                deletedOne == int.MinValue ? int.MinValue : deletedOne + arr[i]);

            keepAll = Math.Max(arr[i], keepAll + arr[i]);
            deletedOne = nextDeleted;

            best = Math.Max(best, keepAll);
            if (deletedOne != int.MinValue) best = Math.Max(best, deletedOne);
        }

        return best;
    }

    public static void Main()
    {
        Console.WriteLine(MaximumSum(new[] { 1, -2, 0, 3 }));
        Console.WriteLine(MaximumSum(new[] { 1, -2, -2, 3 }));
        Console.WriteLine(MaximumSum(new[] { -1, -1, -1, -1 }));   // must stay non-empty
        Console.WriteLine(MaximumSum(new[] { 5 }));
        Console.WriteLine(MaximumSum(new[] { 2, 1, -2, -5, -2 }));
        Console.WriteLine(MaximumSum(new[] { -1, 1, 1, -1, -1, 1, 1, 1 }));
    }
}
