**Logic**

Two sweeps. Going left to right, track the running maximum; any element smaller than it is out of place, and the last such position is the right boundary. Going right to left, track the running minimum; any element larger than it is out of place, and the last such position is the left boundary.

If no element is ever out of place, the array is already sorted and the answer is zero. O(n) time, O(1) space, against O(n log n) for the obvious sort-and-compare approach.

**Program**

```csharp
using System;

public class Solution
{
    public static int FindUnsortedSubarray(int[] nums)
    {
        if (nums == null || nums.Length < 2) return 0;

        int n = nums.Length;
        int right = -1, left = -1;

        // Left to right: anything below the running maximum is misplaced.
        int runningMax = nums[0];
        for (int i = 1; i < n; i++)
        {
            if (nums[i] < runningMax) right = i;
            else runningMax = nums[i];
        }

        if (right == -1) return 0;      // already sorted

        // Right to left: anything above the running minimum is misplaced.
        int runningMin = nums[n - 1];
        for (int i = n - 2; i >= 0; i--)
        {
            if (nums[i] > runningMin) left = i;
            else runningMin = nums[i];
        }

        return right - left + 1;
    }

    public static void Main()
    {
        Console.WriteLine(FindUnsortedSubarray(new[] { 2, 6, 4, 8, 10, 9, 15 }));
        Console.WriteLine(FindUnsortedSubarray(new[] { 1, 2, 3, 4 }));      // sorted
        Console.WriteLine(FindUnsortedSubarray(new[] { 1 }));
        Console.WriteLine(FindUnsortedSubarray(new[] { 2, 1 }));
        Console.WriteLine(FindUnsortedSubarray(new[] { 1, 3, 2, 2, 2 }));
        Console.WriteLine(FindUnsortedSubarray(new[] { 5, 4, 3, 2, 1 }));   // entirely unsorted
    }
}
```

