**Logic**

Boyer-Moore generalised. At most two values can each exceed n/3, so track two candidates and two counters. Each element either matches a candidate and increments it, takes an empty slot, or decrements both.

The verification pass is mandatory here, not merely prudent: with two candidates it is entirely possible that only one qualifies, or neither. O(n) time, O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<int> MajorityElement(int[] nums)
    {
        var result = new List<int>();
        if (nums == null || nums.Length == 0) return result;

        // At most two values can exceed n/3, so two slots suffice.
        int first = 0, second = 0, countFirst = 0, countSecond = 0;

        foreach (int n in nums)
        {
            if (countFirst > 0 && n == first) countFirst++;
            else if (countSecond > 0 && n == second) countSecond++;
            else if (countFirst == 0) { first = n; countFirst = 1; }
            else if (countSecond == 0) { second = n; countSecond = 1; }
            else { countFirst--; countSecond--; }     // cancel against both
        }

        // Verify: the voting pass only narrows the field, it proves nothing.
        countFirst = countSecond = 0;
        foreach (int n in nums)
        {
            if (n == first) countFirst++;
            else if (n == second) countSecond++;
        }

        if (countFirst > nums.Length / 3) result.Add(first);
        if (countSecond > nums.Length / 3) result.Add(second);

        return result;
    }

    private static string Show(int[] nums)
    {
        var r = new List<int>(MajorityElement(nums));
        r.Sort();
        return r.Count == 0 ? "(none)" : string.Join(",", r);
    }

    public static void Main()
    {
        Console.WriteLine(Show(new[] { 3, 2, 3 }));
        Console.WriteLine(Show(new[] { 1 }));
        Console.WriteLine(Show(new[] { 1, 2 }));
        Console.WriteLine(Show(new[] { 1, 2, 3, 4, 5, 6 }));     // none qualifies
        Console.WriteLine(Show(new[] { 2, 2, 1, 1, 1, 2, 2 }));
        Console.WriteLine(Show(new[] { 1, 1, 1, 2, 2, 2, 3 }));  // two qualify
    }
}
```

