**Logic**

Two states: holding a share, or not. Each day, the best balance while holding is either yesterday's holding balance or yesterday's cash minus today's price. The best cash balance is either yesterday's cash or yesterday's holding balance plus today's price, minus the fee.

Charging the fee on the sale rather than the purchase is a convention; either works as long as it is applied exactly once per round trip. The fee is what stops the naive every-upward-step strategy from working, because many small gains no longer cover the cost.

O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int MaxProfitWithFee(int[] prices, int fee)
    {
        if (prices == null || prices.Length < 2) return 0;

        int cash = 0;                  // best balance while holding nothing
        int holding = -prices[0];      // best balance while holding a share

        for (int i = 1; i < prices.Length; i++)
        {
            // Sell today: pay the fee once, on the sale.
            cash = Math.Max(cash, holding + prices[i] - fee);

            // Buy today, funded from the best cash position.
            holding = Math.Max(holding, cash - prices[i]);
        }

        return cash;   // never end holding a share
    }

    // No fee: every positive daily step is worth taking.
    public static int MaxProfitNoFee(int[] prices)
    {
        int total = 0;
        for (int i = 1; i < prices.Length; i++)
            total += Math.Max(0, prices[i] - prices[i - 1]);
        return total;
    }

    public static void Main()
    {
        Console.WriteLine(MaxProfitWithFee(new[] { 1, 3, 2, 8, 4, 9 }, 2));
        Console.WriteLine(MaxProfitNoFee(new[] { 1, 3, 2, 8, 4, 9 }));      // same data, no fee
        Console.WriteLine(MaxProfitWithFee(new[] { 1, 3, 7, 5, 10, 3 }, 3));
        Console.WriteLine(MaxProfitWithFee(new[] { 1, 2 }, 5));            // fee exceeds the gain
        Console.WriteLine(MaxProfitWithFee(new[] { 5, 4, 3 }, 1));
        Console.WriteLine(MaxProfitWithFee(new[] { 7 }, 1));
    }
}
```

