**Approach**

Walk both versions segment by segment, treating a missing segment as zero. Parse each segment as a number rather than comparing text.

**Logic**

String comparison is wrong because "10" sorts before "9" lexicographically. Numeric parsing also collapses leading zeros, so "1.01" equals "1.001".

Treating a missing segment as zero is what makes "1.0" equal "1" — the shorter version is padded conceptually rather than being declared smaller.

O(n + m) time with a single scan and no allocation for the splits.

**Program**

```csharp
using System;

public class Solution
{
    public static int CompareVersion(string a, string b)
    {
        int i = 0, j = 0;

        while (i < a.Length || j < b.Length)
        {
            // A missing segment reads as zero, so "1.0" equals "1".
            long left = ReadSegment(a, ref i);
            long right = ReadSegment(b, ref j);

            if (left != right) return left < right ? -1 : 1;
        }

        return 0;
    }

    private static long ReadSegment(string version, ref int index)
    {
        long value = 0;

        while (index < version.Length && version[index] != '.')
        {
            value = value * 10 + (version[index] - '0');   // leading zeros collapse
            index++;
        }

        if (index < version.Length) index++;   // step over the dot
        return value;
    }

    public static void Main()
    {
        Console.WriteLine(CompareVersion("1.2", "1.10"));      // 10 > 2 numerically
        Console.WriteLine(CompareVersion("1.01", "1.001"));    // leading zeros
        Console.WriteLine(CompareVersion("1.0", "1.0.0"));     // trailing zeros
        Console.WriteLine(CompareVersion("0.1", "1.1"));
        Console.WriteLine(CompareVersion("1.0.1", "1"));
        Console.WriteLine(CompareVersion("7.5.2.4", "7.5.3"));
        Console.WriteLine(CompareVersion("1", "1"));
    }
}
