**Approach**

Split the array in half, solve each half, then take the common prefix of the two results. The merge step is a character-by-character comparison of two strings.

**Logic**

The correctness rests on associativity: the common prefix of a set is the common prefix of the prefixes of any partition of it. That is what licenses solving the halves independently.

The recursion bottoms out at a single string, whose common prefix is itself.

Same O(total characters) as the straightforward vertical scan, but the divide-and-conquer form parallelises and is the shape the question asks for.

**Program**

```csharp
using System;

public class Solution
{
    public static string LongestCommonPrefix(string[] words)
    {
        if (words == null || words.Length == 0) return "";
        return Solve(words, 0, words.Length - 1);
    }

    private static string Solve(string[] words, int lo, int hi)
    {
        if (lo == hi) return words[lo];

        int mid = lo + (hi - lo) / 2;

        // The common prefix of a set is the common prefix of any partition's prefixes.
        return CommonPrefix(Solve(words, lo, mid), Solve(words, mid + 1, hi));
    }

    private static string CommonPrefix(string a, string b)
    {
        int limit = Math.Min(a.Length, b.Length), i = 0;

        while (i < limit && a[i] == b[i]) i++;

        return a.Substring(0, i);
    }

    private static void Show(string s) => Console.WriteLine(s.Length == 0 ? "(empty)" : s);

    public static void Main()
    {
        Show(LongestCommonPrefix(new[] { "flower", "flow", "flight" }));
        Show(LongestCommonPrefix(new[] { "dog", "racecar", "car" }));
        Show(LongestCommonPrefix(new[] { "alone" }));
        Show(LongestCommonPrefix(new[] { "", "abc" }));
        Show(LongestCommonPrefix(Array.Empty<string>()));
        Show(LongestCommonPrefix(new[] { "same", "same", "same" }));
        Show(LongestCommonPrefix(new[] { "ab", "abc", "abcd" }));
    }
}
