**Logic**

KMP never moves backwards in the text. It precomputes, for each prefix of the pattern, the length of the longest proper prefix that is also a suffix — the LPS table. On a mismatch, that table says how far the pattern can shift while keeping the characters already matched, so the text pointer stays put.

Building the table is itself a self-match of the pattern against itself, which is why the construction loop looks like the search loop.

O(n + m) time, O(m) space, with no backtracking in the input.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    // lps[i] = length of the longest proper prefix of pattern[0..i] that is also its suffix.
    public static int[] BuildLps(string pattern)
    {
        var lps = new int[pattern.Length];
        int length = 0;

        for (int i = 1; i < pattern.Length; )
        {
            if (pattern[i] == pattern[length]) lps[i++] = ++length;
            else if (length > 0) length = lps[length - 1];   // fall back, do not restart
            else lps[i++] = 0;
        }

        return lps;
    }

    public static IList<int> FindAll(string text, string pattern)
    {
        var matches = new List<int>();
        if (string.IsNullOrEmpty(pattern) || string.IsNullOrEmpty(text)) return matches;
        if (pattern.Length > text.Length) return matches;

        int[] lps = BuildLps(pattern);
        int i = 0, j = 0;

        while (i < text.Length)
        {
            if (text[i] == pattern[j])
            {
                i++; j++;

                if (j == pattern.Length)
                {
                    matches.Add(i - j);
                    j = lps[j - 1];       // continue, allowing overlapping matches
                }
            }
            else if (j > 0) j = lps[j - 1];   // shift the pattern, i never moves back
            else i++;
        }

        return matches;
    }

    private static string Show(IList<int> r) => r.Count == 0 ? "(none)" : string.Join(",", r);

    public static void Main()
    {
        Console.WriteLine(string.Join(",", BuildLps("aabaaac")));
        Console.WriteLine(string.Join(",", BuildLps("abcabcd")));

        Console.WriteLine(Show(FindAll("ababcababcabc", "abc")));
        Console.WriteLine(Show(FindAll("aaaa", "aa")));        // overlapping matches
        Console.WriteLine(Show(FindAll("abcdef", "xyz")));
        Console.WriteLine(Show(FindAll("aaaaab", "aab")));
    }
}
```

