**Approach**

Hash the pattern once, then roll a hash of the same width across the text. On a hash match, verify the characters — hashes collide, so verification is mandatory.

**Logic**

The rolling step is what makes it linear: removing the leading character's contribution and adding the trailing one is O(1), so each window costs constant time rather than O(m).

Removing the leading character requires the base raised to the power m-1 modulo the prime, precomputed once.

Modular arithmetic can go negative in C# after the subtraction, so the result is normalised back into range before use.

O(n + m) expected, O(n·m) worst case if every window collides.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    private const long Base = 256;
    private const long Prime = 1_000_000_007;

    public static IList<int> RabinKarp(string text, string pattern)
    {
        var found = new List<int>();

        if (string.IsNullOrEmpty(pattern) || pattern.Length > text.Length) return found;

        int m = pattern.Length;

        // Base^(m-1) mod Prime, needed to remove the leading character.
        long highOrder = 1;
        for (int i = 0; i < m - 1; i++) highOrder = highOrder * Base % Prime;

        long patternHash = 0, windowHash = 0;

        for (int i = 0; i < m; i++)
        {
            patternHash = (patternHash * Base + pattern[i]) % Prime;
            windowHash = (windowHash * Base + text[i]) % Prime;
        }

        for (int start = 0; start + m <= text.Length; start++)
        {
            // Hashes collide, so a match must always be verified.
            if (windowHash == patternHash &&
                string.CompareOrdinal(text, start, pattern, 0, m) == 0)
                found.Add(start);

            if (start + m < text.Length)
            {
                windowHash = (windowHash - text[start] * highOrder % Prime) % Prime;
                windowHash = (windowHash * Base + text[start + m]) % Prime;

                if (windowHash < 0) windowHash += Prime;   // C# modulo can go negative
            }
        }

        return found;
    }

    private static void Show(IList<int> v) =>
        Console.WriteLine(v.Count == 0 ? "none" : string.Join(",", v));

    public static void Main()
    {
        Show(RabinKarp("abracadabra", "abra"));
        Show(RabinKarp("aaaaa", "aa"));            // overlapping matches
        Show(RabinKarp("hello", "world"));
        Show(RabinKarp("abc", "abc"));
        Show(RabinKarp("abc", "abcd"));            // pattern longer than text
        Show(RabinKarp("mississippi", "issi"));
        Show(RabinKarp("aaa", ""));
    }
}
```

