**Approach**

Weave two sublists in one pass, keeping a head for each, then join the odd tail to the even head.

**Logic**

The loop condition checks the even pointer and its next, because the odd pointer always runs one ahead. Checking the odd pointer instead reads a node that may already be null.

The even head must be captured before any relinking, since it is lost as soon as the first odd node's next is rewritten.

Relative order within each group is preserved because nodes are appended in traversal order.

O(n) time, O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int val;
    public ListNode next;
    public ListNode(int v) { val = v; }
}

public class Solution
{
    public static ListNode OddEvenList(ListNode head)
    {
        if (head == null || head.next == null) return head;

        ListNode odd = head, even = head.next;
        ListNode evenHead = even;   // captured before any relinking loses it

        // Odd runs one ahead, so the even pointer drives the condition.
        while (even != null && even.next != null)
        {
            odd.next = even.next;
            odd = odd.next;

            even.next = odd.next;
            even = even.next;
        }

        odd.next = evenHead;
        return head;
    }

    private static ListNode Build(params int[] values)
    {
        var dummy = new ListNode(0);
        var tail = dummy;
        foreach (int v in values) { tail.next = new ListNode(v); tail = tail.next; }
        return dummy.next;
    }

    private static void Show(ListNode head)
    {
        var parts = new List<string>();
        for (var n = head; n != null; n = n.next) parts.Add(n.val.ToString());
        Console.WriteLine(parts.Count == 0 ? "(empty)" : string.Join(",", parts));
    }

    public static void Main()
    {
        Show(OddEvenList(Build(1, 2, 3, 4, 5)));
        Show(OddEvenList(Build(2, 1, 3, 5, 6, 4, 7)));
        Show(OddEvenList(Build(1)));
        Show(OddEvenList(Build(1, 2)));
        Show(OddEvenList(null));
        Show(OddEvenList(Build(1, 2, 3, 4)));
    }
}
```

