**Approach**

Prefix sums with a map from running sum to node. If the same running sum appears twice, everything between those two points sums to zero and is removed.

**Logic**

The map must store the *last* node seen at each prefix sum, and a second pass is needed. Recording the first occurrence and splicing greedily fails when removals nest or overlap.

The standard two-pass form: the first pass records the final node at each prefix sum, the second walks again and jumps straight to that node, skipping everything in between.

A dummy head is essential because the removal may include the original head.

O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int val;
    public ListNode next;
    public ListNode(int v) { val = v; }
}

public class Solution
{
    public static ListNode RemoveZeroSumSublists(ListNode head)
    {
        var dummy = new ListNode(0) { next = head };   // the head itself may be removed

        // Pass 1: record the LAST node reaching each prefix sum.
        var lastAt = new Dictionary<int, ListNode>();
        int sum = 0;

        for (var node = dummy; node != null; node = node.next)
        {
            sum += node.val;
            lastAt[sum] = node;
        }

        // Pass 2: jump straight to that last node, dropping everything between.
        sum = 0;

        for (var node = dummy; node != null; node = node.next)
        {
            sum += node.val;
            node.next = lastAt[sum].next;
        }

        return dummy.next;
    }

    private static ListNode Build(params int[] values)
    {
        var dummy = new ListNode(0);
        var tail = dummy;
        foreach (int v in values) { tail.next = new ListNode(v); tail = tail.next; }
        return dummy.next;
    }

    private static void Show(ListNode head)
    {
        var parts = new List<string>();
        for (var n = head; n != null; n = n.next) parts.Add(n.val.ToString());
        Console.WriteLine(parts.Count == 0 ? "(empty)" : string.Join(",", parts));
    }

    public static void Main()
    {
        Show(RemoveZeroSumSublists(Build(1, 2, -3, 3, 1)));
        Show(RemoveZeroSumSublists(Build(1, 2, 3, -3, 4)));
        Show(RemoveZeroSumSublists(Build(1, 2, 3, -3, -2)));
        Show(RemoveZeroSumSublists(Build(1, -1)));            // everything goes
        Show(RemoveZeroSumSublists(Build(0)));
        Show(RemoveZeroSumSublists(Build(5)));
        Show(RemoveZeroSumSublists(Build(1, 3, 2, -3, -2, 5, 5, -5, 1)));
    }
}
