[] [] []
[1]
```

**Approach**

Walk the ring once looking for the insertion point. Three cases: a normal ordered slot, the pivot where the list wraps, and a full loop with no slot found.

**Logic**

The pivot is the one place where the next value is smaller than the current — the maximum-to-minimum wrap. A value above the maximum or below the minimum belongs exactly there, which is why that single check covers both extremes.

The third case is a list of all-equal values, where no slot ever satisfies either condition. Detecting a completed loop and inserting anywhere is what stops an infinite walk.

An empty list must become a self-referencing single node.

O(n) time.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Node
{
    public int val;
    public Node next;
    public Node(int v) { val = v; }
}

public class Solution
{
    public static Node Insert(Node head, int value)
    {
        var inserted = new Node(value);

        if (head == null) { inserted.next = inserted; return inserted; }   // self-loop

        var current = head;

        while (true)
        {
            if (current.val <= value && value <= current.next.val) break;        // ordered slot

            if (current.val > current.next.val &&                                 // the pivot
                (value >= current.val || value <= current.next.val)) break;

            current = current.next;

            if (current == head) break;   // all values equal: anywhere is correct
        }

        inserted.next = current.next;
        current.next = inserted;
        return head;
    }

    private static Node BuildRing(params int[] values)
    {
        if (values.Length == 0) return null;

        var head = new Node(values[0]);
        var tail = head;

        for (int i = 1; i < values.Length; i++) { tail.next = new Node(values[i]); tail = tail.next; }
        tail.next = head;
        return head;
    }

    private static void Show(Node head)
    {
        if (head == null) { Console.WriteLine("(empty)"); return; }

        var parts = new List<string>();
        var n = head;
        do { parts.Add(n.val.ToString()); n = n.next; } while (n != head);

        Console.WriteLine(string.Join(",", parts));
    }

    public static void Main()
    {
        Show(Insert(BuildRing(3, 4, 1), 2));
        Show(Insert(null, 1));
        Show(Insert(BuildRing(1), 0));
        Show(Insert(BuildRing(3, 4, 1), 5));    // above the maximum: at the pivot
        Show(Insert(BuildRing(3, 4, 1), 0));    // below the minimum: same place
        Show(Insert(BuildRing(2, 2, 2), 3));    // all equal
    }
}
```

