1
1,0
3,4,5,1
3,4,0,1
2,3,2,2
```

**Approach**

Level-order traversal carrying a heap-style index with each node: a node at index i has children at 2i and 2i+1. The width of a level is the last index minus the first plus one.

**Logic**

The indices encode the positions the missing nodes would occupy, which is what "including nulls" means — you never materialise them.

The indices double every level, so on a deep skewed tree they overflow. Normalising each level by subtracting its first index keeps them small, and using long gives extra headroom. Both are applied here.

O(n) time.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int val;
    public TreeNode left, right;
    public TreeNode(int v) { val = v; }
}

public class Solution
{
    public static int WidthOfBinaryTree(TreeNode root)
    {
        if (root == null) return 0;

        var queue = new Queue<(TreeNode Node, long Index)>();
        queue.Enqueue((root, 0L));

        long widest = 0;

        while (queue.Count > 0)
        {
            int levelSize = queue.Count;
            long first = 0, last = 0;

            for (int i = 0; i < levelSize; i++)
            {
                var (node, index) = queue.Dequeue();

                if (i == 0) first = index;
                last = index;

                // Normalise by the level's first index so the numbers stay small.
                long normalised = index - first;

                if (node.left != null) queue.Enqueue((node.left, normalised * 2));
                if (node.right != null) queue.Enqueue((node.right, normalised * 2 + 1));
            }

            widest = Math.Max(widest, last - first + 1);
        }

        return (int)widest;
    }

    private static TreeNode Build(params int?[] level)
    {
        if (level.Length == 0 || level[0] == null) return null;

        var root = new TreeNode(level[0].Value);
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);

        int i = 1;
        while (queue.Count > 0 && i < level.Length)
        {
            var node = queue.Dequeue();

            if (i < level.Length && level[i] != null) { node.left = new TreeNode(level[i].Value); queue.Enqueue(node.left); }
            i++;
            if (i < level.Length && level[i] != null) { node.right = new TreeNode(level[i].Value); queue.Enqueue(node.right); }
            i++;
        }

        return root;
    }

    public static void Main()
    {
        Console.WriteLine(WidthOfBinaryTree(Build(1, 3, 2, 5, 3, null, 9)));
        Console.WriteLine(WidthOfBinaryTree(Build(1, 3, 2, 5, null, null, 9, 6, null, 7)));
        Console.WriteLine(WidthOfBinaryTree(Build(1, 3, 2, 5)));
        Console.WriteLine(WidthOfBinaryTree(Build(1)));
        Console.WriteLine(WidthOfBinaryTree(null));
    }
}
