**Approach**

DFS carrying the number built so far. At each node the running value becomes ten times the parent's value plus this node's digit; at a leaf that value is added to the total.

**Logic**

Building the number on the way down rather than collecting digits and reconstructing avoids any string work and keeps the state a single integer.

The leaf test is both children null — not one child null. A node with exactly one child is not a leaf, and treating it as one would count an incomplete number and then count the full path again.

O(n) time, O(height) stack.

**Program**

```csharp
using System;

public class TreeNode
{
    public int val;
    public TreeNode left, right;
    public TreeNode(int v) { val = v; }
}

public class Solution
{
    public static int SumNumbers(TreeNode root) => Walk(root, 0);

    private static int Walk(TreeNode node, int running)
    {
        if (node == null) return 0;

        running = running * 10 + node.val;   // extend the number on the way down

        // A leaf has BOTH children null; one-child nodes are not leaves.
        if (node.left == null && node.right == null) return running;

        return Walk(node.left, running) + Walk(node.right, running);
    }

    public static void Main()
    {
        var a = new TreeNode(1) { left = new TreeNode(2), right = new TreeNode(3) };
        Console.WriteLine(SumNumbers(a));    // 12 + 13

        var b = new TreeNode(4)
        {
            left = new TreeNode(9) { left = new TreeNode(5), right = new TreeNode(1) },
            right = new TreeNode(0)
        };
        Console.WriteLine(SumNumbers(b));    // 495 + 491 + 40

        Console.WriteLine(SumNumbers(new TreeNode(7)));
        Console.WriteLine(SumNumbers(null));

        // A chain: one number only, not one per node.
        var chain = new TreeNode(1) { left = new TreeNode(2) { left = new TreeNode(3) } };
        Console.WriteLine(SumNumbers(chain));

        var zeros = new TreeNode(0) { left = new TreeNode(0), right = new TreeNode(1) };
        Console.WriteLine(SumNumbers(zeros));
    }
}
```

