```

**Approach**

Preorder with an explicit child count after each value. Unlike a binary tree, arity is not fixed, so the structure must be recorded rather than inferred.

**Logic**

Writing the number of children immediately after each value makes the format self-delimiting: the reader knows exactly how many subtrees to consume before returning, so no sentinel or lookahead is needed.

The alternative — null markers closing each child list — also works but produces a longer string and needs the reader to distinguish a marker from a value, which means the marker cannot be a legal value.

Both directions are O(n).

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class NaryNode
{
    public int val;
    public IList<NaryNode> children = new List<NaryNode>();
    public NaryNode(int v) { val = v; }
}

public class Codec
{
    public string Serialise(NaryNode root)
    {
        var sb = new StringBuilder();
        Write(root, sb);
        return sb.ToString();
    }

    private void Write(NaryNode node, StringBuilder sb)
    {
        if (node == null) return;

        // Value then child count: self-delimiting, so no sentinel is needed.
        if (sb.Length > 0) sb.Append(' ');
        sb.Append(node.val).Append(' ').Append(node.children.Count);

        foreach (var child in node.children) Write(child, sb);
    }

    public NaryNode Deserialise(string data)
    {
        if (string.IsNullOrEmpty(data)) return null;

        var tokens = data.Split(' ');
        int index = 0;
        return Read(tokens, ref index);
    }

    private NaryNode Read(string[] tokens, ref int index)
    {
        var node = new NaryNode(int.Parse(tokens[index++]));
        int childCount = int.Parse(tokens[index++]);

        for (int i = 0; i < childCount; i++) node.children.Add(Read(tokens, ref index));

        return node;
    }
}

public class Solution
{
    // Compare structure and values, not object identity.
    private static bool Same(NaryNode a, NaryNode b)
    {
        if (a == null || b == null) return a == null && b == null;
        if (a.val != b.val || a.children.Count != b.children.Count) return false;

        for (int i = 0; i < a.children.Count; i++)
            if (!Same(a.children[i], b.children[i])) return false;

        return true;
    }

    private static NaryNode Node(int v, params NaryNode[] children)
    {
        var n = new NaryNode(v);
        foreach (var c in children) n.children.Add(c);
        return n;
    }

    public static void Main()
    {
        var codec = new Codec();

        var tree = Node(1,
            Node(3, Node(5), Node(6)),
            Node(2),
            Node(4));

        string encoded = codec.Serialise(tree);
        Console.WriteLine(encoded);
        Console.WriteLine(Same(tree, codec.Deserialise(encoded)));

        var single = Node(7);
        Console.WriteLine(codec.Serialise(single));
        Console.WriteLine(Same(single, codec.Deserialise(codec.Serialise(single))));

        Console.WriteLine(codec.Serialise(null) == "");
        Console.WriteLine(codec.Deserialise("") == null);

        var deep = Node(1, Node(2, Node(3, Node(4))));
        Console.WriteLine(Same(deep, codec.Deserialise(codec.Serialise(deep))));
    }
}
