**Logic**

Fisher-Yates. Walk from the last index down, swapping each element with a uniformly chosen index from 0 up to and including the current position. Every permutation is then equally likely, and it runs in O(n) with no extra allocation.

The classic bug is choosing the swap partner from the whole array rather than from the unshuffled prefix. That produces n^n equally likely execution paths mapping onto n! permutations, and since n^n is not divisible by n! the distribution is measurably biased.

Sorting with a random comparator is also wrong, and additionally violates the comparer contract.

**Program**

```csharp
using System;

public class Solution
{
    public static void Shuffle(int[] array, Random rng)
    {
        for (int i = array.Length - 1; i > 0; i--)
        {
            // Range is 0..i INCLUSIVE: an element may stay where it is.
            int j = rng.Next(i + 1);
            (array[i], array[j]) = (array[j], array[i]);
        }
    }

    public static void Main()
    {
        var rng = new Random(42);   // fixed seed: reproducible output

        var a = new[] { 1, 2, 3, 4, 5 };
        Shuffle(a, rng);

        // Assert it is a permutation, not one specific order: the output of a
        // seeded Random is an implementation detail and is not guaranteed
        // stable across .NET versions.
        var sorted = (int[])a.Clone();
        Array.Sort(sorted);
        Console.WriteLine(string.Join(",", sorted));

        // Distribution check: with 6 permutations of 3 elements and 60,000 trials,
        // each should appear roughly 10,000 times.
        var counts = new System.Collections.Generic.Dictionary<string, int>();
        var check = new Random(1);

        for (int t = 0; t < 60000; t++)
        {
            var arr = new[] { 1, 2, 3 };
            Shuffle(arr, check);
            string key = string.Join("", arr);
            counts[key] = counts.TryGetValue(key, out int c) ? c + 1 : 1;
        }

        Console.WriteLine(counts.Count);                       // all 6 permutations seen

        int min = int.MaxValue, max = 0;
        foreach (var (_, c) in counts) { min = Math.Min(min, c); max = Math.Max(max, c); }

        // Within 10% of the expected 10,000 each: consistent with uniformity.
        Console.WriteLine(min > 9000 && max < 11000);

        var single = new[] { 7 };
        Shuffle(single, rng);
        Console.WriteLine(string.Join(",", single));

        var empty = Array.Empty<int>();
        Shuffle(empty, rng);
        Console.WriteLine(empty.Length);
    }
}
