1
2
6
0
249999999997
```

**Logic**

Scanning the board after each move is O(n²) for an n×n grid. Instead keep running sums: one per row, one per column, and one for each diagonal. A move by player one adds one to the relevant sums, a move by player two subtracts one.

A sum reaching plus or minus n means that line is complete, so the winner is known immediately. That makes each move O(1) regardless of board size.

The anti-diagonal condition is `row + col == n - 1`, which is the pairing that is easiest to get wrong.

**Program**

```csharp
using System;

public class TicTacToe
{
    private readonly int _size;
    private readonly int[] _rows;
    private readonly int[] _cols;
    private int _diagonal;
    private int _antiDiagonal;

    public TicTacToe(int size)
    {
        if (size <= 0) throw new ArgumentOutOfRangeException(nameof(size));
        _size = size;
        _rows = new int[size];
        _cols = new int[size];
    }

    // Returns 0 for no winner yet, or the player number that has just won.
    public int Move(int row, int col, int player)
    {
        if (player != 1 && player != 2) throw new ArgumentException("player must be 1 or 2");

        int delta = player == 1 ? 1 : -1;

        _rows[row] += delta;
        _cols[col] += delta;

        if (row == col) _diagonal += delta;
        if (row + col == _size - 1) _antiDiagonal += delta;   // the easy one to get wrong

        int target = _size * delta;

        if (_rows[row] == target || _cols[col] == target ||
            _diagonal == target || _antiDiagonal == target)
            return player;

        return 0;
    }
}

public class Solution
{
    public static void Main()
    {
        var game = new TicTacToe(3);

        Console.WriteLine(game.Move(0, 0, 1));   // 0
        Console.WriteLine(game.Move(0, 2, 2));   // 0
        Console.WriteLine(game.Move(2, 2, 1));   // 0
        Console.WriteLine(game.Move(1, 1, 2));   // 0
        Console.WriteLine(game.Move(2, 0, 1));   // 0
        Console.WriteLine(game.Move(1, 0, 2));   // 0
        Console.WriteLine(game.Move(2, 1, 1));   // completes the bottom row

        // Anti-diagonal win for player 2 on a fresh board.
        var anti = new TicTacToe(3);
        anti.Move(0, 2, 2);
        anti.Move(1, 1, 2);
        Console.WriteLine(anti.Move(2, 0, 2));
    }
}
