**Logic**

Two structures. A deque holds the snake's body in order, so moving is an O(1) push at the head and pop at the tail. A hash set of occupied cells makes the self-collision check O(1) instead of scanning the body.

The subtlety that catches people: the tail must be removed *before* testing whether the new head collides with the body, because the tail cell is vacated in the same tick. Testing first wrongly ends the game when the snake follows its own tail.

Eating food skips the tail removal, which is what makes the snake grow.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class SnakeGame
{
    private readonly int _width, _height;
    private readonly Queue<(int r, int c)> _body = new();
    private readonly HashSet<(int r, int c)> _occupied = new();
    private readonly Queue<(int r, int c)> _food = new();
    private int _score;

    public SnakeGame(int width, int height, IEnumerable<(int r, int c)> food)
    {
        _width = width;
        _height = height;
        _body.Enqueue((0, 0));
        _occupied.Add((0, 0));
        foreach (var f in food) _food.Enqueue(f);
    }

    // Returns the score, or -1 when the game is over.
    public int Move(char direction)
    {
        var head = PeekHead();

        var next = direction switch
        {
            'U' => (head.r - 1, head.c),
            'D' => (head.r + 1, head.c),
            'L' => (head.r, head.c - 1),
            'R' => (head.r, head.c + 1),
            _ => throw new ArgumentException($"bad direction '{direction}'"),
        };

        if (next.Item1 < 0 || next.Item1 >= _height ||
            next.Item2 < 0 || next.Item2 >= _width) return -1;   // hit a wall

        bool eating = _food.Count > 0 && _food.Peek() == next;

        if (eating) { _food.Dequeue(); _score++; }
        else
        {
            // Free the tail BEFORE the collision test: following your own tail is legal.
            var tail = _body.Dequeue();
            _occupied.Remove(tail);
        }

        if (_occupied.Contains(next)) return -1;                 // hit itself

        _body.Enqueue(next);
        _occupied.Add(next);

        return _score;
    }

    private (int r, int c) PeekHead()
    {
        (int r, int c) last = default;
        foreach (var cell in _body) last = cell;
        return last;
    }
}

public class Solution
{
    public static void Main()
    {
        var game = new SnakeGame(3, 2, new[] { (1, 2), (0, 1) });

        Console.WriteLine(game.Move('R'));   // 0
        Console.WriteLine(game.Move('D'));   // 0
        Console.WriteLine(game.Move('R'));   // eats: 1
        Console.WriteLine(game.Move('U'));   // 1
        Console.WriteLine(game.Move('L'));   // eats: 2
        Console.WriteLine(game.Move('U'));   // hits the wall
    }
}
```

