**Logic**

A tree of nodes, each either a directory holding named children or a file holding content. A single node type with a nullable content field keeps it simple; the presence of content distinguishes a file from a directory.

Path resolution walks the components, and `mkdir` creates missing directories along the way, which is the recursive behaviour the problem specifies.

`ls` returns the sorted children of a directory, or the file name itself if the path is a file, which is a small asymmetry worth noting.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public class FileSystem
{
    private sealed class Node
    {
        public readonly SortedDictionary<string, Node> Children = new(StringComparer.Ordinal);
        public StringBuilder Content;                  // non-null means this is a file
        public bool IsFile => Content != null;
    }

    private readonly Node _root = new();

    private static string[] Split(string path) =>
        path.Split('/', StringSplitOptions.RemoveEmptyEntries);

    public IList<string> Ls(string path)
    {
        var node = Resolve(path, create: false);
        if (node == null) return Array.Empty<string>();

        // A file lists itself; a directory lists its children.
        if (node.IsFile)
        {
            var parts = Split(path);
            return new List<string> { parts[^1] };
        }

        return node.Children.Keys.ToList();             // SortedDictionary: already ordered
    }

    public void Mkdir(string path) => Resolve(path, create: true);

    public void AddContentToFile(string path, string content)
    {
        var node = Resolve(path, create: true);
        node.Content ??= new StringBuilder();
        node.Content.Append(content);                   // append, not overwrite
    }

    public string ReadContentFromFile(string path)
    {
        var node = Resolve(path, create: false);

        if (node == null || !node.IsFile)
            throw new InvalidOperationException($"'{path}' is not a file");

        return node.Content.ToString();
    }

    private Node Resolve(string path, bool create)
    {
        var node = _root;

        foreach (string part in Split(path))
        {
            if (!node.Children.TryGetValue(part, out var next))
            {
                if (!create) return null;
                node.Children[part] = next = new Node();
            }
            node = next;
        }

        return node;
    }
}

public class Solution
{
    public static void Main()
    {
        var fs = new FileSystem();

        Console.WriteLine(string.Join(",", fs.Ls("/")).Length);     // empty root

        fs.Mkdir("/a/b/c");                                         // creates all levels
        fs.AddContentToFile("/a/b/c/d", "hello");

        Console.WriteLine(string.Join(",", fs.Ls("/")));
        Console.WriteLine(string.Join(",", fs.Ls("/a/b/c")));
        Console.WriteLine(fs.ReadContentFromFile("/a/b/c/d"));

        fs.AddContentToFile("/a/b/c/d", " world");                  // appends
        Console.WriteLine(fs.ReadContentFromFile("/a/b/c/d"));

        Console.WriteLine(string.Join(",", fs.Ls("/a/b/c/d")));     // a file lists itself

        try { fs.ReadContentFromFile("/a/b"); }
        catch (InvalidOperationException) { Console.WriteLine("not a file"); }
    }
}
