**Logic**

The naive design keeps a dictionary of player to score and sorts on every `top` call, which is O(n log n) per query. That is acceptable when scores change far more often than the leaderboard is read.

The better structure keeps a sorted set ordered by score descending, so `top` is a prefix walk in O(k) and `addScore` removes and reinserts in O(log n). The removal before the update is essential, because mutating a key that a sorted structure is ordering by corrupts it.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Leaderboard
{
    private readonly Dictionary<int, int> _scores = new();

    // Ordered by score descending, then by id for a deterministic tie-break.
    private readonly SortedSet<(int Score, int PlayerId)> _ranked =
        new(Comparer<(int Score, int PlayerId)>.Create((a, b) =>
            b.Score != a.Score ? b.Score.CompareTo(a.Score) : a.PlayerId.CompareTo(b.PlayerId)));

    public void AddScore(int playerId, int points)
    {
        if (_scores.TryGetValue(playerId, out int existing))
            _ranked.Remove((existing, playerId));   // remove BEFORE the key changes

        int updated = existing + points;
        _scores[playerId] = updated;
        _ranked.Add((updated, playerId));
    }

    public int Top(int k)
    {
        int total = 0, taken = 0;

        foreach (var (score, _) in _ranked)
        {
            if (taken++ == k) break;
            total += score;
        }

        return total;
    }

    public void Reset(int playerId)
    {
        if (!_scores.TryGetValue(playerId, out int score)) return;

        _ranked.Remove((score, playerId));
        _scores.Remove(playerId);
    }

    public IList<int> TopPlayers(int k) =>
        _ranked.Take(k).Select(e => e.PlayerId).ToList();
}

public class Solution
{
    public static void Main()
    {
        var board = new Leaderboard();

        board.AddScore(1, 73);
        board.AddScore(2, 56);
        board.AddScore(3, 39);
        board.AddScore(4, 51);

        Console.WriteLine(board.Top(1));
        Console.WriteLine(board.Top(3));
        Console.WriteLine(string.Join(",", board.TopPlayers(2)));

        board.AddScore(2, 30);                 // 2 overtakes 1
        Console.WriteLine(string.Join(",", board.TopPlayers(2)));

        board.Reset(2);
        Console.WriteLine(board.Top(1));
        Console.WriteLine(board.Top(10));       // k larger than the population
    }
}
```

