2,1
73
163
```

**Logic**

Random selection needs contiguous indexing; arbitrary removal needs a lookup. A list gives the first, a dictionary the second, and the pairing gives both.

Removal avoids the O(n) shift by swapping the doomed element with the last one and trimming the end. The dictionary entry for the element that moved must be updated to its new index, which is the step most implementations forget.

All three operations are O(1) on average, bounded by the dictionary's hashing.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class RandomisedSet
{
    private readonly List<int> _items = new();
    private readonly Dictionary<int, int> _indexOf = new();
    private readonly Random _rng;

    public RandomisedSet(int seed = 11) => _rng = new Random(seed);

    public bool Insert(int value)
    {
        if (_indexOf.ContainsKey(value)) return false;

        _indexOf[value] = _items.Count;
        _items.Add(value);
        return true;
    }

    public bool Remove(int value)
    {
        if (!_indexOf.TryGetValue(value, out int index)) return false;

        int lastIndex = _items.Count - 1;

        if (index != lastIndex)
        {
            int moved = _items[lastIndex];
            _items[index] = moved;
            _indexOf[moved] = index;      // the moved element's index must follow it
        }

        _items.RemoveAt(lastIndex);       // O(1): removing from the end never shifts
        _indexOf.Remove(value);

        return true;
    }

    public int GetRandom() => _items.Count > 0
        ? _items[_rng.Next(_items.Count)]
        : throw new InvalidOperationException("empty");

    public bool Contains(int value) => _indexOf.ContainsKey(value);
    public int Count => _items.Count;
}

public class Solution
{
    public static void Main()
    {
        var set = new RandomisedSet();

        Console.WriteLine(set.Insert(10));
        Console.WriteLine(set.Insert(20));
        Console.WriteLine(set.Insert(30));
        Console.WriteLine(set.Insert(10));    // duplicate rejected

        Console.WriteLine(set.Remove(10));    // not the last element: exercises the swap
        Console.WriteLine(set.Contains(10));
        Console.WriteLine(set.Contains(30));  // the moved element is still findable
        Console.WriteLine(set.Count);

        // Every draw must be a current member.
        bool allValid = true;
        for (int i = 0; i < 100; i++)
        {
            int drawn = set.GetRandom();
            if (drawn != 20 && drawn != 30) allValid = false;
        }
        Console.WriteLine(allValid);
    }
}
