**Logic**

The underlying iterator can only move forward, so peeking means fetching the next element and holding it in a buffer until the caller actually consumes it.

The state is a single cached element plus a flag saying whether it is occupied. `Peek` fills the buffer if empty and returns it without clearing; `Next` returns the buffered value and clears the flag, or falls through to the underlying iterator when nothing is buffered.

The flag is necessary rather than using a null check, because the element type may legitimately be null or a value type with no free sentinel.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class PeekingIterator<T>
{
    private readonly IEnumerator<T> _source;
    private T _buffered;
    private bool _hasBuffered;
    private bool _sourceExhausted;

    public PeekingIterator(IEnumerable<T> source)
    {
        _source = source.GetEnumerator();
        _sourceExhausted = !_source.MoveNext();
    }

    public bool HasNext => _hasBuffered || !_sourceExhausted;

    public T Peek()
    {
        if (!HasNext) throw new InvalidOperationException("no more elements");

        if (!_hasBuffered)
        {
            _buffered = _source.Current;
            _hasBuffered = true;
            _sourceExhausted = !_source.MoveNext();
        }

        return _buffered;   // peek does NOT clear the buffer
    }

    public T Next()
    {
        if (!HasNext) throw new InvalidOperationException("no more elements");

        if (_hasBuffered)
        {
            _hasBuffered = false;      // consume the peeked value
            return _buffered;
        }

        T current = _source.Current;
        _sourceExhausted = !_source.MoveNext();
        return current;
    }
}

public class Solution
{
    public static void Main()
    {
        var it = new PeekingIterator<int>(new[] { 1, 2, 3 });

        Console.WriteLine(it.Next());     // 1
        Console.WriteLine(it.Peek());     // 2, not consumed
        Console.WriteLine(it.Peek());     // 2 again: peeking is idempotent
        Console.WriteLine(it.Next());     // 2
        Console.WriteLine(it.HasNext);
        Console.WriteLine(it.Next());     // 3
        Console.WriteLine(it.HasNext);

        // Peeking a null element must work: that is why a flag is used, not a null check.
        var strings = new PeekingIterator<string>(new string[] { null, "x" });
        Console.WriteLine(strings.Peek() == null);
        Console.WriteLine(strings.Next() == null);
        Console.WriteLine(strings.Next());

        try { new PeekingIterator<int>(Array.Empty<int>()).Peek(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
