**Logic**

Four state variables tracked in one pass: the best balance after the first buy, after the first sell, after the second buy and after the second sell. Each is derived from the previous state, so the whole thing is a chain.

The buy states hold a negative balance, being money spent, which lets each sell state simply add the current price. Updating them in order within a single loop is valid because each state's new value legitimately uses the same day's earlier state, which corresponds to buying and selling on the same day for zero profit.

O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int MaxProfitTwoTransactions(int[] prices)
    {
        if (prices == null || prices.Length < 2) return 0;

        // Balances, not profits: a buy state is negative.
        int firstBuy = int.MinValue, firstSell = 0;
        int secondBuy = int.MinValue, secondSell = 0;

        foreach (int price in prices)
        {
            firstBuy = Math.Max(firstBuy, -price);                 // spend
            firstSell = Math.Max(firstSell, firstBuy + price);     // recover
            secondBuy = Math.Max(secondBuy, firstSell - price);    // spend again
            secondSell = Math.Max(secondSell, secondBuy + price);
        }

        return secondSell;
    }

    // The general k-transaction version, for comparison.
    public static int MaxProfitK(int[] prices, int k)
    {
        if (prices == null || prices.Length < 2 || k <= 0) return 0;

        // With k large enough, it degenerates to unlimited transactions.
        if (k >= prices.Length / 2)
        {
            int total = 0;
            for (int i = 1; i < prices.Length; i++)
                total += Math.Max(0, prices[i] - prices[i - 1]);
            return total;
        }

        var buy = new int[k + 1];
        var sell = new int[k + 1];
        Array.Fill(buy, int.MinValue);

        foreach (int price in prices)
            for (int t = 1; t <= k; t++)
            {
                buy[t] = Math.Max(buy[t], sell[t - 1] - price);
                sell[t] = Math.Max(sell[t], buy[t] + price);
            }

        return sell[k];
    }

    public static void Main()
    {
        Console.WriteLine(MaxProfitTwoTransactions(new[] { 3, 3, 5, 0, 0, 3, 1, 4 }));
        Console.WriteLine(MaxProfitTwoTransactions(new[] { 1, 2, 3, 4, 5 }));   // one run
        Console.WriteLine(MaxProfitTwoTransactions(new[] { 7, 6, 4, 3, 1 }));   // only falls
        Console.WriteLine(MaxProfitTwoTransactions(new[] { 1 }));
        Console.WriteLine(MaxProfitK(new[] { 3, 2, 6, 5, 0, 3 }, 2));
        Console.WriteLine(MaxProfitK(new[] { 2, 4, 1 }, 100));                  // unlimited
    }
}
```

