**Logic**

A palindrome mirrors around its centre, so every character must appear an even number of times, except that a single character may appear an odd number of times and sit exactly in the middle. So the test is simply that at most one character has an odd count.

Counting is O(n). The neat variant toggles a bit per character in a bitmask and checks that the result has at most one bit set, which uses a single integer instead of a counting structure.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static bool CanFormPalindrome(string s)
    {
        if (string.IsNullOrEmpty(s)) return true;

        var counts = new Dictionary<char, int>();
        foreach (char c in s) counts[c] = counts.TryGetValue(c, out int n) ? n + 1 : 1;

        int odd = 0;
        foreach (var (_, count) in counts)
            if (count % 2 == 1 && ++odd > 1) return false;

        return true;
    }

    // Bitmask: toggle a bit per character, then check at most one bit survives.
    // Assumes lowercase ASCII.
    public static bool CanFormPalindromeBitmask(string s)
    {
        int mask = 0;
        foreach (char c in s) mask ^= 1 << (c - 'a');

        // n & (n-1) clears the lowest set bit; zero afterwards means 0 or 1 bits set.
        return (mask & (mask - 1)) == 0;
    }

    public static void Main()
    {
        Console.WriteLine(CanFormPalindrome("civic"));        // already one
        Console.WriteLine(CanFormPalindrome("ivicc"));        // rearranges to civic
        Console.WriteLine(CanFormPalindrome("hello"));
        Console.WriteLine(CanFormPalindrome("aab"));
        Console.WriteLine(CanFormPalindrome(""));
        Console.WriteLine(CanFormPalindromeBitmask("carerac"));
    }
}
