**Logic**

Two pointers walking forward. Advance through the longer string always; advance through the candidate only when the characters match. If the candidate pointer reaches its end, every character was found in order.

Greedy matching at the earliest opportunity is optimal: taking the first available match never rules out a later one, because any match found by skipping could also be found after taking the earlier one. O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static bool IsSubsequence(string candidate, string text)
    {
        if (string.IsNullOrEmpty(candidate)) return true;   // empty is always a subsequence
        if (string.IsNullOrEmpty(text)) return false;

        int i = 0;   // index into candidate

        foreach (char c in text)
        {
            // Take the earliest match: greedy is safe here.
            if (c == candidate[i] && ++i == candidate.Length) return true;
        }

        return false;
    }

    public static void Main()
    {
        Console.WriteLine(IsSubsequence("abc", "ahbgdc"));
        Console.WriteLine(IsSubsequence("axc", "ahbgdc"));
        Console.WriteLine(IsSubsequence("", "anything"));
        Console.WriteLine(IsSubsequence("abc", ""));
        Console.WriteLine(IsSubsequence("abc", "abc"));
        Console.WriteLine(IsSubsequence("aaa", "aa"));       // not enough copies
    }
}
