**Logic**

A map from a submission's identity to the time it was last accepted. A new submission is a duplicate when its key is present and the elapsed time is within the window.

The identity must be derived from the content that matters, not from the whole request, since a retry may differ in headers or a timestamp while representing the same intent. Hashing the significant fields gives a stable key.

The map grows without bound unless entries are expired, which is the real design question. A time-bucketed sweep keeps cleanup O(1) amortised rather than scanning everything.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class DuplicateDetector
{
    private readonly int _windowSeconds;
    private readonly Dictionary<string, int> _lastSeen = new();

    // Keys grouped by the second they expire, so cleanup never scans the whole map.
    private readonly SortedDictionary<int, List<string>> _expiryBuckets = new();

    public DuplicateDetector(int windowSeconds = 60) => _windowSeconds = windowSeconds;

    public bool IsDuplicate(string key, int now)
    {
        Expire(now);

        if (_lastSeen.TryGetValue(key, out int seenAt) && now - seenAt < _windowSeconds)
            return true;

        _lastSeen[key] = now;

        int expiresAt = now + _windowSeconds;
        if (!_expiryBuckets.TryGetValue(expiresAt, out var bucket))
            _expiryBuckets[expiresAt] = bucket = new List<string>();
        bucket.Add(key);

        return false;
    }

    // Drop whole buckets whose expiry time has passed.
    private void Expire(int now)
    {
        while (_expiryBuckets.Count > 0)
        {
            var first = default(KeyValuePair<int, List<string>>);
            foreach (var kv in _expiryBuckets) { first = kv; break; }

            if (first.Key > now) break;

            foreach (string key in first.Value)
                if (_lastSeen.TryGetValue(key, out int seenAt) && now - seenAt >= _windowSeconds)
                    _lastSeen.Remove(key);

            _expiryBuckets.Remove(first.Key);
        }
    }

    public int TrackedCount => _lastSeen.Count;
}

public class Solution
{
    public static void Main()
    {
        var d = new DuplicateDetector(windowSeconds: 10);

        Console.WriteLine(d.IsDuplicate("order-1", 0));    // first time
        Console.WriteLine(d.IsDuplicate("order-1", 5));    // within the window
        Console.WriteLine(d.IsDuplicate("order-2", 5));    // different key
        Console.WriteLine(d.IsDuplicate("order-1", 10));   // window has passed
        Console.WriteLine(d.IsDuplicate("order-1", 12));   // new window started at 10

        Console.WriteLine(d.TrackedCount);
        d.IsDuplicate("order-3", 100);                      // expiry sweep runs
        Console.WriteLine(d.TrackedCount);
    }
}
