**Logic**

A trie over the sentences with each node caching its top k completions. Walking the prefix is O(prefix length) and the answer is read from the node rather than computed, which matters because a short prefix can have an enormous subtree.

The session variant, where input arrives character by character and a hash character ends the sentence, needs a current node pointer that advances with each keystroke and resets on completion. If the walk ever falls off the trie, no suggestions exist and the node stays null until the sentence ends.

Ranking is by frequency descending, then lexicographically, so ties are deterministic.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public class AutocompleteSystem
{
    private sealed class Node
    {
        public readonly Dictionary<char, Node> Children = new();
        public readonly List<(string Sentence, int Count)> Top = new();
    }

    private const int K = 3;

    private readonly Node _root = new();
    private readonly Dictionary<string, int> _counts = new();

    private Node _current;
    private readonly StringBuilder _typed = new();

    public AutocompleteSystem(IEnumerable<(string Sentence, int Count)> history)
    {
        foreach (var (sentence, count) in history) Record(sentence, count);
        _current = _root;
    }

    private void Record(string sentence, int times)
    {
        _counts[sentence] = _counts.TryGetValue(sentence, out int c) ? c + times : times;
        int total = _counts[sentence];

        var node = _root;
        foreach (char ch in sentence)
        {
            if (!node.Children.TryGetValue(ch, out var next))
                node.Children[ch] = next = new Node();
            node = next;

            UpdateTop(node, sentence, total);
        }
    }

    private static void UpdateTop(Node node, string sentence, int count)
    {
        int existing = node.Top.FindIndex(t => t.Sentence == sentence);
        if (existing >= 0) node.Top.RemoveAt(existing);

        node.Top.Add((sentence, count));
        node.Top.Sort((a, b) => b.Count != a.Count
            ? b.Count.CompareTo(a.Count)
            : string.CompareOrdinal(a.Sentence, b.Sentence));

        if (node.Top.Count > K) node.Top.RemoveAt(node.Top.Count - 1);
    }

    public IList<string> Input(char c)
    {
        if (c == '#')
        {
            Record(_typed.ToString(), 1);      // the sentence is complete
            _typed.Clear();
            _current = _root;
            return Array.Empty<string>();
        }

        _typed.Append(c);

        // Once the walk falls off the trie it stays off until the sentence ends.
        if (_current != null && !_current.Children.TryGetValue(c, out _current))
            _current = null;

        return _current?.Top.Select(t => t.Sentence).ToList() ?? (IList<string>)Array.Empty<string>();
    }
}

public class Solution
{
    public static void Main()
    {
        var system = new AutocompleteSystem(new[]
        {
            ("i love you", 5), ("island", 3), ("iroman", 2), ("i love leetcode", 2),
        });

        Console.WriteLine(string.Join("|", system.Input('i')));
        Console.WriteLine(string.Join("|", system.Input(' ')));
        Console.WriteLine(string.Join("|", system.Input('a')));   // falls off the trie
        Console.WriteLine(string.Join("|", system.Input('#')).Length);

        // "i a" was just recorded, so it now appears.
        Console.WriteLine(string.Join("|", system.Input('i')));
    }
}
