**Logic**

A prefix-sum array answers range queries in O(1) but needs O(n) to rebuild after an update. A plain array is the reverse: O(1) updates, O(n) queries. A Fenwick tree, also called a binary indexed tree, gives O(log n) for both.

The structure exploits binary representation: index i is responsible for a range whose length is the lowest set bit of i. Moving to the parent during a query clears that bit; moving during an update adds it.

That `i & -i` idiom, isolating the lowest set bit, is the whole mechanism.

**Program**

```csharp
using System;

public class FenwickTree
{
    private readonly long[] _tree;   // 1-based internally
    private readonly int[] _values;  // the original values, for point assignment

    public FenwickTree(int[] values)
    {
        _values = new int[values.Length];
        _tree = new long[values.Length + 1];

        // Add, not Update: _values must be populated too, or Set would
        // compute its delta against zero rather than the real value.
        for (int i = 0; i < values.Length; i++) Add(i, values[i]);
    }

    // Add delta at index i.
    public void Add(int index, int delta)
    {
        _values[index] += delta;
        Update(index, delta);
    }

    // Set index i to an absolute value.
    public void Set(int index, int value) => Add(index, value - _values[index]);

    private void Update(int index, long delta)
    {
        for (int i = index + 1; i < _tree.Length; i += i & -i)   // add the lowest set bit
            _tree[i] += delta;
    }

    // Sum of [0..index].
    private long PrefixSum(int index)
    {
        long total = 0;
        for (int i = index + 1; i > 0; i -= i & -i)              // clear the lowest set bit
            total += _tree[i];
        return total;
    }

    // Sum of [left..right] inclusive.
    public long RangeSum(int left, int right)
    {
        if (left > right) return 0;
        return PrefixSum(right) - (left == 0 ? 0 : PrefixSum(left - 1));
    }
}

public class Solution
{
    public static void Main()
    {
        var tree = new FenwickTree(new[] { 1, 3, 5, 7, 9, 11 });

        Console.WriteLine(tree.RangeSum(0, 5));    // whole array
        Console.WriteLine(tree.RangeSum(1, 3));    // 3+5+7
        Console.WriteLine(tree.RangeSum(2, 2));    // single element

        tree.Set(1, 10);                            // 3 becomes 10
        Console.WriteLine(tree.RangeSum(1, 3));
        Console.WriteLine(tree.RangeSum(0, 5));

        tree.Add(5, -11);                           // zero out the last element
        Console.WriteLine(tree.RangeSum(0, 5));
    }
}
```

