**Logic**

A token bucket. The bucket holds up to `capacity` tokens and refills at a fixed rate. Each request consumes one; if none are available it is rejected. Capacity sets the burst size, refill rate sets the sustained throughput, and the two are tuned independently.

Refill lazily from elapsed time rather than with a background timer, which keeps it cheap and correct across idle periods. Use a monotonic clock, because a wall-clock adjustment would otherwise create or destroy tokens.

All operations are O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

public sealed class TokenBucket
{
    private readonly double _capacity;
    private readonly double _refillPerSecond;
    private readonly object _gate = new();

    private double _tokens;
    private double _lastRefill;      // seconds, from an injectable clock

    private readonly Func<double> _clock;

    public TokenBucket(double capacity, double refillPerSecond, Func<double> clock)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));

        _capacity = capacity;
        _refillPerSecond = refillPerSecond;
        _clock = clock;
        _tokens = capacity;          // start full: a cold client is not penalised
        _lastRefill = clock();
    }

    public bool TryConsume(double tokens = 1)
    {
        lock (_gate)
        {
            Refill();

            if (_tokens < tokens) return false;

            _tokens -= tokens;
            return true;
        }
    }

    // How long until the given number of tokens is available.
    public double RetryAfterSeconds(double tokens = 1)
    {
        lock (_gate)
        {
            Refill();
            double shortfall = tokens - _tokens;
            return shortfall <= 0 ? 0 : shortfall / _refillPerSecond;
        }
    }

    private void Refill()
    {
        double now = _clock();
        double elapsed = now - _lastRefill;
        _lastRefill = now;

        // Clamp at capacity: that is what bounds the burst an idle client accrues.
        _tokens = Math.Min(_capacity, _tokens + elapsed * _refillPerSecond);
    }
}

public class Solution
{
    public static void Main()
    {
        double now = 0;
        var bucket = new TokenBucket(capacity: 3, refillPerSecond: 1, clock: () => now);

        // A burst of three is allowed immediately.
        Console.WriteLine($"{bucket.TryConsume()} {bucket.TryConsume()} {bucket.TryConsume()}");
        Console.WriteLine(bucket.TryConsume());      // bucket empty

        Console.WriteLine(bucket.RetryAfterSeconds());

        now = 1;                                      // one second passes, one token
        Console.WriteLine(bucket.TryConsume());
        Console.WriteLine(bucket.TryConsume());

        now = 100;                                    // long idle: refills but caps at 3
        Console.WriteLine($"{bucket.TryConsume()} {bucket.TryConsume()} {bucket.TryConsume()}");
        Console.WriteLine(bucket.TryConsume());
    }
}
