**Logic**

Comparing the query against every stored word is O(n × length). Grouping by length narrows the candidates, since a one-character *substitution* preserves length, but still scans within a length bucket.

The better approach indexes wildcard variants. For each stored word, generate every version with one position replaced by a wildcard, and map each to the words producing it. A query does the same and looks up each variant, so a match means the two words differ in at most that one position.

Build is O(n × length), query is O(length) lookups.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class MagicDictionary
{
    // "c*t" -> the words that produce it, e.g. cat, cot, cut.
    private readonly Dictionary<string, List<string>> _byWildcard = new();
    private readonly HashSet<string> _words = new();

    public void Build(IEnumerable<string> words)
    {
        foreach (string word in words)
        {
            _words.Add(word);

            foreach (string variant in Variants(word))
            {
                if (!_byWildcard.TryGetValue(variant, out var list))
                    _byWildcard[variant] = list = new List<string>();
                list.Add(word);
            }
        }
    }

    // Exactly one character must differ, so an identical word does not count.
    public bool Search(string query)
    {
        foreach (string variant in Variants(query))
        {
            if (!_byWildcard.TryGetValue(variant, out var candidates)) continue;

            foreach (string candidate in candidates)
                if (candidate != query) return true;   // differs in exactly that position
        }

        return false;
    }

    private static IEnumerable<string> Variants(string word)
    {
        var buffer = new StringBuilder(word);

        for (int i = 0; i < word.Length; i++)
        {
            char original = buffer[i];
            buffer[i] = '*';
            yield return buffer.ToString();
            buffer[i] = original;
        }
    }
}

public class Solution
{
    public static void Main()
    {
        var dict = new MagicDictionary();
        dict.Build(new[] { "hello", "leetcode", "hallo" });

        Console.WriteLine(dict.Search("hello"));    // exact match does not count
        Console.WriteLine(dict.Search("hhllo"));    // one substitution
        Console.WriteLine(dict.Search("hell"));     // different length
        Console.WriteLine(dict.Search("leetcoded"));
        Console.WriteLine(dict.Search("hallo"));    // matches hello by one change
        Console.WriteLine(dict.Search("world"));
    }
}
