window is empty
```

**Logic**

A frequency map from value to count. `Find` scans the distinct keys and checks whether the complement is present, which is O(distinct) per query with O(1) adds.

The case that must be handled explicitly is a value that is exactly half the target: the complement is the value itself, so it only qualifies if at least two copies exist. Missing that reports a false positive whenever the target is double a stored value.

The alternative design precomputes every pairwise sum, making `Find` O(1) but `Add` O(n). Which is right depends entirely on the call ratio.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TwoSumStructure
{
    private readonly Dictionary<int, int> _counts = new();

    public void Add(int number) =>
        _counts[number] = _counts.TryGetValue(number, out int c) ? c + 1 : 1;

    public bool Find(int target)
    {
        foreach (var (value, count) in _counts)
        {
            int complement = target - value;

            if (complement == value)
            {
                // Pairing a value with itself needs two copies.
                if (count >= 2) return true;
            }
            else if (_counts.ContainsKey(complement))
            {
                return true;
            }
        }

        return false;
    }
}

// The opposite trade: O(n) add, O(1) find.
public class TwoSumPrecomputed
{
    private readonly List<int> _numbers = new();
    private readonly HashSet<int> _sums = new();

    public void Add(int number)
    {
        foreach (int existing in _numbers) _sums.Add(existing + number);
        _numbers.Add(number);
    }

    public bool Find(int target) => _sums.Contains(target);
}

public class Solution
{
    public static void Main()
    {
        var s = new TwoSumStructure();
        s.Add(1); s.Add(3); s.Add(5);

        Console.WriteLine(s.Find(4));    // 1 + 3
        Console.WriteLine(s.Find(7));    // no pair
        Console.WriteLine(s.Find(2));    // would need two 1s

        s.Add(1);
        Console.WriteLine(s.Find(2));    // now there are two

        var p = new TwoSumPrecomputed();
        p.Add(0); p.Add(0);
        Console.WriteLine(p.Find(0));    // 0 + 0
        Console.WriteLine(p.Find(1));
    }
}
```

**Output**

```
True
False
False
True
True
False
```

**Logic**

Copying the array on every snapshot is O(n) per snapshot and O(n × snapshots) memory, which is hopeless when snapshots are frequent and changes are sparse.

Instead store, per index, a list of (snapshot id, value) pairs recording only the versions where that index actually changed. A read at a given snapshot binary searches that index's history for the latest entry at or before it.

Set is O(1) amortised, get is O(log changes), and memory is proportional to the number of writes rather than to array size times snapshot count.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class SnapshotArray
{
    // Per index: the snapshot ids at which it changed, and the values it took.
    private readonly List<(int SnapId, int Value)>[] _history;
    private int _currentSnap;

    public SnapshotArray(int length)
    {
        _history = new List<(int, int)>[length];
        for (int i = 0; i < length; i++)
            _history[i] = new List<(int, int)> { (0, 0) };   // everything starts at 0
    }

    public void Set(int index, int value)
    {
        var list = _history[index];

        // Several writes within one snapshot overwrite rather than append.
        if (list[^1].SnapId == _currentSnap) list[^1] = (_currentSnap, value);
        else list.Add((_currentSnap, value));
    }

    public int Snap() => _currentSnap++;   // returns the id of the snapshot just taken

    public int Get(int index, int snapId)
    {
        var list = _history[index];

        // Rightmost entry with SnapId <= snapId.
        int low = 0, high = list.Count;

        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (list[mid].SnapId <= snapId) low = mid + 1;
            else high = mid;
        }

        return list[low - 1].Value;
    }
}

public class Solution
{
    public static void Main()
    {
        var array = new SnapshotArray(3);

        array.Set(0, 5);
        Console.WriteLine(array.Snap());      // snapshot 0
        array.Set(0, 6);
        Console.WriteLine(array.Get(0, 0));   // still 5 in snapshot 0
        Console.WriteLine(array.Get(0, 1));

        Console.WriteLine(array.Snap());      // snapshot 1
        array.Set(1, 9);
        Console.WriteLine(array.Get(1, 1));   // unset in snapshot 1, so 0
        Console.WriteLine(array.Get(1, 2));
        Console.WriteLine(array.Get(2, 0));   // never written
    }
}
```

**Output**

```
0
5
6
1
0
9
0
```

**Logic**

A bounded min-heap of size k. Push each arriving element; once the heap exceeds k, remove the smallest. What remains is the k largest seen so far, and the root is the kth largest.

A min-heap is used for the *largest* k because you need cheap access to the weakest member of the winning set, which is the one to evict. A max-heap would surface the element you never want to remove.

Each element costs O(log k) and memory is O(k) regardless of stream length, which is what makes it work for unbounded input.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TopKStream
{
    private readonly int _k;
    private readonly PriorityQueue<int, int> _heap = new();   // min-heap

    public TopKStream(int k)
    {
        if (k <= 0) throw new ArgumentOutOfRangeException(nameof(k));
        _k = k;
    }

    public void Add(int value)
    {
        _heap.Enqueue(value, value);

        // Evict the smallest once the set is over size: the root is the weakest member.
        if (_heap.Count > _k) _heap.Dequeue();
    }

    // The kth largest so far, or throws if fewer than k have been seen.
    public int KthLargest() => _heap.Count == _k
        ? _heap.Peek()
        : throw new InvalidOperationException($"only {_heap.Count} of {_k} elements seen");

    // The current top k, largest first. O(k log k), and non-destructive.
    public IList<int> Top()
    {
        var snapshot = new List<int>();
        var buffer = new List<(int Value, int Priority)>();

        while (_heap.Count > 0)
        {
            _heap.TryDequeue(out int v, out int p);
            snapshot.Add(v);
            buffer.Add((v, p));
        }

        foreach (var (v, p) in buffer) _heap.Enqueue(v, p);   // restore

        snapshot.Reverse();   // the heap pops ascending
        return snapshot;
    }

    public int Count => _heap.Count;
}

public class Solution
{
    public static void Main()
    {
        var top = new TopKStream(3);

        foreach (int v in new[] { 4, 5, 8, 2 }) top.Add(v);
        Console.WriteLine(top.KthLargest());            // 4
        Console.WriteLine(string.Join(",", top.Top()));

        top.Add(3);
        Console.WriteLine(top.KthLargest());

        top.Add(10);
        Console.WriteLine(string.Join(",", top.Top()));
        Console.WriteLine(top.Count);                    // never exceeds k

        var small = new TopKStream(5);
        small.Add(1);
        try { small.KthLargest(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
```

