**Logic**

An elastic sliding window, valid because all values are positive, which makes the running sum monotonic: extending always increases it and shrinking always decreases it.

Expand the right edge adding to the sum. While the sum meets the target, record the width and shrink from the left, since a shorter qualifying window may still exist. Each index moves forward only, so O(n) despite the nested loop.

With negative values allowed, the monotonicity is lost and this approach breaks entirely.

**Program**

```csharp
using System;

public class Solution
{
    public static int MinSubArrayLen(int target, int[] nums)
    {
        if (nums == null || nums.Length == 0) return 0;

        int left = 0, best = int.MaxValue;
        long sum = 0;

        for (int right = 0; right < nums.Length; right++)
        {
            sum += nums[right];

            // Shrink while still valid: a shorter window may also qualify.
            while (sum >= target)
            {
                best = Math.Min(best, right - left + 1);
                sum -= nums[left++];
            }
        }

        return best == int.MaxValue ? 0 : best;   // 0 means no qualifying subarray
    }

    public static void Main()
    {
        Console.WriteLine(MinSubArrayLen(7, new[] { 2, 3, 1, 2, 4, 3 }));   // [4,3]
        Console.WriteLine(MinSubArrayLen(4, new[] { 1, 4, 4 }));
        Console.WriteLine(MinSubArrayLen(11, new[] { 1, 1, 1, 1, 1, 1, 1, 1 }));  // impossible
        Console.WriteLine(MinSubArrayLen(11, new[] { 1, 2, 3, 4, 5 }));
        Console.WriteLine(MinSubArrayLen(1, new[] { 1 }));
        Console.WriteLine(MinSubArrayLen(100, new[] { 100 }));
    }
}
```

