**Approach**

Start by pinning down scope, because the question is deliberately open: multiple floors, several vehicle sizes, pricing, and how a spot is chosen. Then model the nouns as classes and put the varying behaviour behind interfaces so pricing and allocation can change without touching the rest.

The two decisions an interviewer is looking for: spot allocation as a **Strategy** so "nearest to the entrance" can become "nearest to the lift" without editing the lot, and pricing as a separate abstraction for the same reason.

**Class structure**

```
                      +---------------------+
                      |     ParkingLot      |
                      +---------------------+
                      | - floors            |
                      | - allocation  <>----+---> IAllocationStrategy
                      | - pricing     <>----+---> IPricingStrategy
                      +---------------------+
                      | Park(vehicle)       |
                      | Leave(ticket)       |
                      +----------+----------+
                                 |  1..*
                                 v
                      +---------------------+
                      |    ParkingFloor     |
                      +---------------------+
                      | - spots             |
                      +----------+----------+
                                 |  1..*
                                 v
                      +---------------------+
                      |    ParkingSpot      |
                      +---------------------+
                      | Size, IsFree        |
                      +---------------------+

   Vehicle (abstract)              IPricingStrategy
      ^     ^      ^                     ^
      |     |      |                     |
  Motorbike Car  Truck            HourlyPricing
```

**Flow**

```
  vehicle arrives
       |
       v
  ParkingLot.Park(vehicle)
       |
       +--> allocation.FindSpot(floors, vehicle.Size)
       |         |
       |         +--> no spot? --> return null (lot full)
       |         |
       |         +--> spot found
       |                |
       v                v
  spot.Occupy()    Ticket { spot, vehicle, entryTime }
       |
       v
  ... time passes ...
       |
  ParkingLot.Leave(ticket)
       |
       +--> pricing.Calculate(ticket, exitTime)
       +--> spot.Release()
       v
     fee
```

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public enum VehicleSize { Motorbike, Compact, Large }

public abstract class Vehicle
{
    protected Vehicle(string registration, VehicleSize size)
    { Registration = registration; Size = size; }

    public string Registration { get; }
    public VehicleSize Size { get; }
}

public class Motorbike : Vehicle
{
    public Motorbike(string reg) : base(reg, VehicleSize.Motorbike) { }
}

public class Car : Vehicle
{
    public Car(string reg) : base(reg, VehicleSize.Compact) { }
}

public class Truck : Vehicle
{
    public Truck(string reg) : base(reg, VehicleSize.Large) { }
}

public class ParkingSpot
{
    public ParkingSpot(string id, VehicleSize size) { Id = id; Size = size; }

    public string Id { get; }
    public VehicleSize Size { get; }
    public bool IsFree { get; private set; } = true;

    // A spot fits anything of its own size or smaller.
    public bool Fits(VehicleSize size) => IsFree && size <= Size;

    public void Occupy() => IsFree = false;
    public void Release() => IsFree = true;
}

public class ParkingFloor
{
    public ParkingFloor(int number, IEnumerable<ParkingSpot> spots)
    { Number = number; Spots = spots.ToList(); }

    public int Number { get; }
    public IReadOnlyList<ParkingSpot> Spots { get; }
    public int FreeCount => Spots.Count(s => s.IsFree);
}

public class Ticket
{
    public Ticket(Vehicle vehicle, ParkingSpot spot, DateTime entry)
    { Vehicle = vehicle; Spot = spot; Entry = entry; }

    public Vehicle Vehicle { get; }
    public ParkingSpot Spot { get; }
    public DateTime Entry { get; }
}

// Strategy: how a spot is chosen can change without touching ParkingLot.
public interface IAllocationStrategy
{
    ParkingSpot FindSpot(IEnumerable<ParkingFloor> floors, VehicleSize size);
}

public class NearestFirstAllocation : IAllocationStrategy
{
    public ParkingSpot FindSpot(IEnumerable<ParkingFloor> floors, VehicleSize size) =>
        floors.OrderBy(f => f.Number)
              .SelectMany(f => f.Spots)
              .FirstOrDefault(s => s.Fits(size));
}

// Strategy: pricing varies by operator, season, vehicle type.
public interface IPricingStrategy
{
    decimal Calculate(Ticket ticket, DateTime exit);
}

public class HourlyPricing : IPricingStrategy
{
    private static readonly Dictionary<VehicleSize, decimal> RatePerHour = new()
    {
        [VehicleSize.Motorbike] = 1m,
        [VehicleSize.Compact] = 2m,
        [VehicleSize.Large] = 4m,
    };

    public decimal Calculate(Ticket ticket, DateTime exit)
    {
        // Part hours are charged as full hours, and a stay always costs at least one.
        double hours = (exit - ticket.Entry).TotalHours;
        int chargeable = Math.Max(1, (int)Math.Ceiling(hours));
        return chargeable * RatePerHour[ticket.Vehicle.Size];
    }
}

public class ParkingLot
{
    private readonly List<ParkingFloor> _floors;
    private readonly IAllocationStrategy _allocation;
    private readonly IPricingStrategy _pricing;

    public ParkingLot(IEnumerable<ParkingFloor> floors,
                      IAllocationStrategy allocation,
                      IPricingStrategy pricing)
    {
        _floors = floors.ToList();
        _allocation = allocation;
        _pricing = pricing;
    }

    public Ticket Park(Vehicle vehicle, DateTime now)
    {
        var spot = _allocation.FindSpot(_floors, vehicle.Size);
        if (spot == null) return null;            // lot full for this size

        spot.Occupy();
        return new Ticket(vehicle, spot, now);
    }

    public decimal Leave(Ticket ticket, DateTime now)
    {
        decimal fee = _pricing.Calculate(ticket, now);
        ticket.Spot.Release();
        return fee;
    }

    public int FreeSpots => _floors.Sum(f => f.FreeCount);
}

public class Solution
{
    public static void Main()
    {
        var floor1 = new ParkingFloor(1, new[]
        {
            new ParkingSpot("1-A", VehicleSize.Motorbike),
            new ParkingSpot("1-B", VehicleSize.Compact),
        });

        var floor2 = new ParkingFloor(2, new[]
        {
            new ParkingSpot("2-A", VehicleSize.Large),
        });

        var lot = new ParkingLot(new[] { floor1, floor2 },
                                 new NearestFirstAllocation(),
                                 new HourlyPricing());

        var start = new DateTime(2026, 1, 1, 9, 0, 0);

        var bikeTicket = lot.Park(new Motorbike("BIKE-1"), start);
        Console.WriteLine($"{bikeTicket.Spot.Id} {lot.FreeSpots}");

        var carTicket = lot.Park(new Car("CAR-1"), start);
        Console.WriteLine($"{carTicket.Spot.Id} {lot.FreeSpots}");

        // A truck needs a Large spot; only floor 2 has one.
        var truckTicket = lot.Park(new Truck("TRUCK-1"), start);
        Console.WriteLine($"{truckTicket.Spot.Id} {lot.FreeSpots}");

        // Nothing left for a second car.
        Console.WriteLine(lot.Park(new Car("CAR-2"), start) == null);

        Console.WriteLine(lot.Leave(carTicket, start.AddHours(2.5)));   // 3 hours x 2
        Console.WriteLine(lot.FreeSpots);

        // A large spot accepts a smaller vehicle.
        Console.WriteLine(lot.Leave(truckTicket, start.AddMinutes(10)));  // minimum 1 hour
    }
}
