**Approach**

The interesting part is not the elevator, it is the **dispatcher**: which car should answer a hall call. Model each car as a state machine, keep its pending stops in two ordered sets, and put the selection rule behind an interface so the scheduling policy can change.

The classic algorithm is SCAN, often called the elevator algorithm: keep travelling in the current direction serving every stop on the way, then reverse. It beats first-come-first-served because it avoids the lift oscillating between floors.

**States and transitions**

```
            +----------+   request above    +-----------+
            |   IDLE   |------------------->|  MOVING   |
            |          |                    |    UP     |
            +----------+<-------------------+-----------+
              ^      |    no stops left        |
              |      | request below           | reached a stop
              |      v                         v
              |  +-----------+           +-----------+
              |  |  MOVING   |           |   DOORS   |
              |  |   DOWN    |---------->|   OPEN    |
              |  +-----------+           +-----------+
              |                                |
              +--------------------------------+
                        no stops left
```

**Dispatch flow**

```
   hall call (floor 7, going UP)
            |
            v
   +------------------------+
   |   ElevatorController   |
   +------------------------+
            |
            | scheduler.Choose(cars, call)
            v
   +--------+--------+--------+
   |  Car A |  Car B |  Car C |
   |  fl 3  |  fl 9  |  fl 7  |
   |   UP   |  DOWN  |  IDLE  |
   +--------+--------+--------+
       |        |        |
    cost 4   cost 2   cost 0      <-- idle car on the floor wins
       |        |        |
       +--------+--------+
                |
                v
         Car C .AddStop(7)
```

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public enum Direction { Idle, Up, Down }

public class Elevator
{
    // Stops above and below are kept separately so SCAN can drain one set
    // fully before reversing.
    private readonly SortedSet<int> _up = new();
    private readonly SortedSet<int> _down = new();

    public Elevator(int id, int floor = 0) { Id = id; CurrentFloor = floor; }

    public int Id { get; }
    public int CurrentFloor { get; private set; }
    public Direction Direction { get; private set; } = Direction.Idle;
    public bool DoorsOpen { get; private set; }
    public int PendingStops => _up.Count + _down.Count;

    public void AddStop(int floor)
    {
        if (floor == CurrentFloor) { DoorsOpen = true; return; }

        if (floor > CurrentFloor) _up.Add(floor); else _down.Add(floor);

        if (Direction == Direction.Idle)
            Direction = floor > CurrentFloor ? Direction.Up : Direction.Down;
    }

    // One simulation tick: move a floor, or open doors on arrival.
    public void Step()
    {
        DoorsOpen = false;

        if (PendingStops == 0) { Direction = Direction.Idle; return; }

        // SCAN: continue in the current direction while stops remain that way.
        if (Direction == Direction.Up && _up.Count == 0) Direction = Direction.Down;
        if (Direction == Direction.Down && _down.Count == 0) Direction = Direction.Up;

        CurrentFloor += Direction == Direction.Up ? 1 : -1;

        var set = Direction == Direction.Up ? _up : _down;
        if (set.Remove(CurrentFloor)) DoorsOpen = true;

        if (PendingStops == 0) Direction = Direction.Idle;
    }

    // How costly it is for this car to answer a call, lower is better.
    public int CostFor(int floor, Direction wanted)
    {
        int distance = Math.Abs(CurrentFloor - floor);

        if (Direction == Direction.Idle) return distance;

        bool movingToward = (Direction == Direction.Up && floor > CurrentFloor)
                         || (Direction == Direction.Down && floor < CurrentFloor);

        // Same direction and on the way: cheap. Otherwise it must finish first.
        return movingToward && Direction == wanted ? distance : distance + PendingStops * 2 + 10;
    }
}

public interface IScheduler
{
    Elevator Choose(IEnumerable<Elevator> cars, int floor, Direction wanted);
}

public class NearestCarScheduler : IScheduler
{
    public Elevator Choose(IEnumerable<Elevator> cars, int floor, Direction wanted) =>
        cars.OrderBy(c => c.CostFor(floor, wanted)).ThenBy(c => c.Id).First();
}

public class ElevatorController
{
    private readonly List<Elevator> _cars;
    private readonly IScheduler _scheduler;

    public ElevatorController(IEnumerable<Elevator> cars, IScheduler scheduler)
    { _cars = cars.ToList(); _scheduler = scheduler; }

    public Elevator RequestFrom(int floor, Direction wanted)
    {
        var car = _scheduler.Choose(_cars, floor, wanted);
        car.AddStop(floor);
        return car;
    }

    public void Step() { foreach (var c in _cars) c.Step(); }

    public string State => string.Join(" ", _cars.Select(c =>
        $"[{c.Id}:{c.CurrentFloor}{(c.DoorsOpen ? "*" : "")}]"));
}

public class Solution
{
    public static void Main()
    {
        var cars = new[] { new Elevator(1, 3), new Elevator(2, 9), new Elevator(3, 7) };
        var controller = new ElevatorController(cars, new NearestCarScheduler());

        // Car 3 is already on floor 7 and idle, so it wins.
        Console.WriteLine(controller.RequestFrom(7, Direction.Up).Id);

        // A call from floor 4: car 1 at floor 3 is nearest.
        Console.WriteLine(controller.RequestFrom(4, Direction.Up).Id);

        Console.WriteLine(controller.State);
        controller.Step();
        Console.WriteLine(controller.State);

        // Car 1 travels 3 -> 4 and opens its doors.
        Console.WriteLine(cars[0].DoorsOpen);
        Console.WriteLine(cars[0].Direction);

        // A single car serving several stops in one sweep.
        var solo = new Elevator(9, 0);
        solo.AddStop(3); solo.AddStop(1); solo.AddStop(5);
        var visited = new List<int>();
        for (int t = 0; t < 6; t++) { solo.Step(); if (solo.DoorsOpen) visited.Add(solo.CurrentFloor); }
        Console.WriteLine(string.Join(",", visited));
    }
}
