**Approach**

This is the textbook case for the **State pattern**. A vending machine's behaviour depends entirely on where it is in the transaction, and expressing that with flags and if-chains produces code where every new state multiplies the conditionals.

Each state becomes a class that knows which transitions are legal from it. Inserting money while dispensing, or selecting an item before paying, is rejected by the state rather than by a scattered guard.

**State machine**

```
        +---------------+  insert coin   +---------------+
        |     IDLE      |--------------->|  HAS MONEY    |
        |               |<---------------|               |
        +---------------+  refund        +---------------+
              ^                                  |
              |                                  | select(item)
              |                                  v
              |                          +---------------+
              |    sufficient funds?     |   CHECKING    |
              |                          +---------------+
              |                            |          |
              |                    no      |          |  yes
              |              (stay, prompt) |          v
              |                            |  +---------------+
              |                            |  |  DISPENSING   |
              |                            |  +---------------+
              |                            |          |
              +----------------------------+----------+
                      return change, back to IDLE
```

**Flow**

```
  user            Machine           State              Inventory
   |                 |                |                    |
   |-- insert 50 --->|-- Insert() --->|                    |
   |                 |                |-- balance += 50    |
   |<-- balance 50 --|                |                    |
   |                 |                |                    |
   |-- select(A1) -->|-- Select() --->|-- price? --------->|
   |                 |                |<-- 35, in stock ---|
   |                 |                |                    |
   |                 |                |-- dispense ------->|
   |                 |                |   (stock -= 1)     |
   |<-- item + 15 ---|                |                    |
   |    change       |                |                    |
```

**Program**

```csharp
using System;
using System.Collections.Generic;

public record Product(string Code, string Name, int PriceInCents);

public interface IVendingState
{
    string Insert(VendingMachine machine, int cents);
    string Select(VendingMachine machine, string code);
    string Refund(VendingMachine machine);
}

public class IdleState : IVendingState
{
    public string Insert(VendingMachine m, int cents)
    {
        m.Balance += cents;
        m.SetState(new HasMoneyState());
        return $"balance {m.Balance}";
    }

    public string Select(VendingMachine m, string code) => "insert money first";
    public string Refund(VendingMachine m) => "nothing to refund";
}

public class HasMoneyState : IVendingState
{
    public string Insert(VendingMachine m, int cents)
    {
        m.Balance += cents;
        return $"balance {m.Balance}";
    }

    public string Select(VendingMachine m, string code)
    {
        if (!m.TryGetProduct(code, out var product)) return "unknown code";
        if (m.StockOf(code) == 0) return "out of stock";
        if (m.Balance < product.PriceInCents)
            return $"need {product.PriceInCents - m.Balance} more";

        // Only now is the transaction committed.
        m.SetState(new DispensingState());
        return m.State.Select(m, code);
    }

    public string Refund(VendingMachine m)
    {
        int refunded = m.Balance;
        m.Balance = 0;
        m.SetState(new IdleState());
        return $"refunded {refunded}";
    }
}

public class DispensingState : IVendingState
{
    public string Insert(VendingMachine m, int cents) => "please wait, dispensing";

    public string Select(VendingMachine m, string code)
    {
        m.TryGetProduct(code, out var product);

        int change = m.Balance - product.PriceInCents;
        m.RemoveStock(code);
        m.Balance = 0;
        m.SetState(new IdleState());

        return change > 0 ? $"{product.Name} + change {change}" : product.Name;
    }

    public string Refund(VendingMachine m) => "cannot refund while dispensing";
}

public class VendingMachine
{
    private readonly Dictionary<string, Product> _products = new();
    private readonly Dictionary<string, int> _stock = new();

    public VendingMachine() => State = new IdleState();

    public IVendingState State { get; private set; }
    public int Balance { get; set; }

    public void SetState(IVendingState state) => State = state;

    public void Load(Product product, int quantity)
    {
        _products[product.Code] = product;
        _stock[product.Code] = _stock.GetValueOrDefault(product.Code) + quantity;
    }

    public bool TryGetProduct(string code, out Product product) =>
        _products.TryGetValue(code, out product);

    public int StockOf(string code) => _stock.GetValueOrDefault(code);
    public void RemoveStock(string code) => _stock[code]--;

    public string Insert(int cents) => State.Insert(this, cents);
    public string Select(string code) => State.Select(this, code);
    public string Refund() => State.Refund(this);
    public string StateName => State.GetType().Name;
}

public class Solution
{
    public static void Main()
    {
        var machine = new VendingMachine();
        machine.Load(new Product("A1", "Crisps", 35), 1);
        machine.Load(new Product("A2", "Chocolate", 80), 0);   // deliberately empty

        Console.WriteLine(machine.Select("A1"));       // no money yet
        Console.WriteLine(machine.Insert(20));
        Console.WriteLine(machine.Select("A1"));       // not enough
        Console.WriteLine(machine.Insert(30));
        Console.WriteLine(machine.Select("A1"));       // dispenses with change
        Console.WriteLine(machine.StateName);

        Console.WriteLine(machine.Select("A1"));       // sold out now
        machine.Insert(100);
        Console.WriteLine(machine.Select("A2"));       // loaded with zero stock
        Console.WriteLine(machine.Refund());
    }
}
```

**Output**

```
insert money first
balance 20
need 15 more
balance 50
Crisps + change 15
IdleState
insert money first
out of stock
refunded 100
```

**Approach**

The modelling decision that matters is separating **Book** (the title, ISBN, author) from **BookItem** (a physical copy with its own barcode). A library owns three copies of one book; a member borrows a copy, not a title. Conflating them makes availability and reservations impossible to express.

Beyond that, the business rules — loan period, borrowing limit, fines — belong in a policy object rather than scattered through the member and loan classes, so a different branch can apply different rules.

**Class structure**

```
     +----------------+           +-------------------+
     |     Book       | 1      *  |    BookItem       |
     |----------------|<>---------|-------------------|
     | Isbn, Title    |           | Barcode           |
     | Author         |           | Status            |
     +----------------+           +---------+---------+
                                            |
                                            | 0..1
                                            v
     +----------------+           +-------------------+
     |    Member      | 1      *  |      Loan         |
     |----------------|<>---------|-------------------|
     | Id, Name       |           | Issued, Due       |
     | ActiveLoans    |           | Returned          |
     +----------------+           +-------------------+

     +--------------------------------------------+
     |               Library                      |
     |--------------------------------------------|
     |  Checkout(member, isbn)                     |
     |  Return(barcode)                            |
     |  Reserve(member, isbn)                      |
     |             |                               |
     |             +-----> ILendingPolicy          |
     +--------------------------------------------+
                                ^
                                |
                        StandardPolicy
                     (14 days, 3 books, 50p/day)
```

**Checkout flow**

```
  member                Library            Policy           BookItem
    |                      |                  |                 |
    |-- checkout(isbn) --->|                  |                 |
    |                      |-- CanBorrow? --->|                 |
    |                      |   (limit, fines) |                 |
    |                      |<-- yes/no -------|                 |
    |                      |                  |                 |
    |                      |-- find available copy ------------>|
    |                      |<-- copy, or none ------------------|
    |                      |                  |                 |
    |                      |-- DueDate() ---->|                 |
    |                      |<-- +14 days -----|                 |
    |                      |                  |                 |
    |                      |-- mark Loaned -------------------->|
    |<-- Loan -------------|                  |                 |
```

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public enum ItemStatus { Available, Loaned, Reserved, Lost }

public record Book(string Isbn, string Title, string Author);

public class BookItem
{
    public BookItem(string barcode, Book book) { Barcode = barcode; Book = book; }

    public string Barcode { get; }
    public Book Book { get; }
    public ItemStatus Status { get; set; } = ItemStatus.Available;
}

public class Member
{
    public Member(string id, string name) { Id = id; Name = name; }

    public string Id { get; }
    public string Name { get; }
    public List<Loan> Loans { get; } = new();
    public decimal OutstandingFines { get; set; }

    public IEnumerable<Loan> ActiveLoans => Loans.Where(l => l.Returned == null);
}

public class Loan
{
    public Loan(Member member, BookItem item, DateTime issued, DateTime due)
    { Member = member; Item = item; Issued = issued; Due = due; }

    public Member Member { get; }
    public BookItem Item { get; }
    public DateTime Issued { get; }
    public DateTime Due { get; }
    public DateTime? Returned { get; set; }
}

// Rules live here so a branch can apply different ones.
public interface ILendingPolicy
{
    int MaxConcurrentLoans { get; }
    DateTime DueDate(DateTime issued);
    decimal FineFor(Loan loan, DateTime returned);
    bool CanBorrow(Member member, out string reason);
}

public class StandardPolicy : ILendingPolicy
{
    public int MaxConcurrentLoans => 3;

    public DateTime DueDate(DateTime issued) => issued.AddDays(14);

    public decimal FineFor(Loan loan, DateTime returned)
    {
        int daysLate = (int)Math.Ceiling((returned - loan.Due).TotalDays);
        return daysLate <= 0 ? 0m : daysLate * 0.50m;
    }

    public bool CanBorrow(Member member, out string reason)
    {
        if (member.OutstandingFines > 10m) { reason = "fines exceed the limit"; return false; }
        if (member.ActiveLoans.Count() >= MaxConcurrentLoans) { reason = "loan limit reached"; return false; }
        reason = null;
        return true;
    }
}

public class Library
{
    private readonly List<BookItem> _items = new();
    private readonly Dictionary<string, Queue<Member>> _reservations = new();
    private readonly ILendingPolicy _policy;

    public Library(ILendingPolicy policy) => _policy = policy;

    public void AddCopy(BookItem item) => _items.Add(item);

    public int AvailableCopies(string isbn) =>
        _items.Count(i => i.Book.Isbn == isbn && i.Status == ItemStatus.Available);

    public Loan Checkout(Member member, string isbn, DateTime now, out string reason)
    {
        if (!_policy.CanBorrow(member, out reason)) return null;

        // A reservation queue takes precedence over a walk-up request.
        if (_reservations.TryGetValue(isbn, out var queue) && queue.Count > 0
            && queue.Peek().Id != member.Id)
        {
            reason = "all copies are reserved for other members";
            return null;
        }

        var item = _items.FirstOrDefault(i => i.Book.Isbn == isbn && i.Status == ItemStatus.Available);
        if (item == null) { reason = "no copy available"; return null; }

        if (queue?.Count > 0 && queue.Peek().Id == member.Id) queue.Dequeue();

        item.Status = ItemStatus.Loaned;
        var loan = new Loan(member, item, now, _policy.DueDate(now));
        member.Loans.Add(loan);
        _loans.Add(loan);          // the library tracks its own loans

        reason = null;
        return loan;
    }

    public decimal Return(string barcode, DateTime now)
    {
        var item = _items.First(i => i.Barcode == barcode);
        var loan = FindActiveLoan(item);

        if (loan == null) return 0m;

        loan.Returned = now;
        decimal fine = _policy.FineFor(loan, now);
        loan.Member.OutstandingFines += fine;

        // If someone is waiting, hold the copy rather than shelving it.
        bool reserved = _reservations.TryGetValue(item.Book.Isbn, out var q) && q.Count > 0;
        item.Status = reserved ? ItemStatus.Reserved : ItemStatus.Available;

        return fine;
    }

    public int Reserve(Member member, string isbn)
    {
        if (!_reservations.TryGetValue(isbn, out var queue))
            _reservations[isbn] = queue = new Queue<Member>();

        queue.Enqueue(member);
        return queue.Count;   // position in the queue
    }

    private readonly List<Loan> _loans = new();

    private Loan FindActiveLoan(BookItem item) =>
        _loans.FirstOrDefault(l => l.Item == item && l.Returned == null);
}

public class Solution
{
    public static void Main()
    {
        var library = new Library(new StandardPolicy());
        var book = new Book("978-0", "Clean Code", "Martin");

        library.AddCopy(new BookItem("C1", book));
        library.AddCopy(new BookItem("C2", book));

        var alice = new Member("M1", "Alice");
        var bob = new Member("M2", "Bob");

        var day0 = new DateTime(2026, 1, 1);

        var loan = library.Checkout(alice, "978-0", day0, out string reason);
        Console.WriteLine($"{loan.Item.Barcode} due {loan.Due:yyyy-MM-dd}");
        Console.WriteLine(library.AvailableCopies("978-0"));

        var second = library.Checkout(bob, "978-0", day0, out _);
        Console.WriteLine(library.AvailableCopies("978-0"));

        // No copies left.
        Console.WriteLine(library.Checkout(new Member("M3", "Cara"), "978-0", day0, out reason) == null);
        Console.WriteLine(reason);

        // Returned four days late: 4 x 0.50
        Console.WriteLine(library.Return("C1", day0.AddDays(18)));
        Console.WriteLine(alice.OutstandingFines);
        Console.WriteLine(library.AvailableCopies("978-0"));
    }
}
